(window.EPS ||= {})[41] = {"no":41,"chapter":"2장 세 나라의 시대","when":"612년","read":"읽기 17~19분","ago":"약 1,410년 전","title":"백만 군사는 어떻게 이천 명이 되었을까","subtitle":"큰 수를 적은 쪽과 그 수를 세어 본 쪽은 끝내 다른 사람이었습니다","intro":"오늘 이야기의 무대는 <b>고구려</b>예요. 세 나라가 서로 겨루는 동안, 서쪽에서는 삼백 년 넘게 갈라져 싸우던 중국이 <b>수나라</b>로 하나가 되었어요. 하나가 된 큰 나라는 이웃을 가만두지 않았지요. 612년, 그 나라의 황제가 눈으로는 헤아릴 수도 없는 군사를 이끌고 서쪽 국경을 건너옵니다. 그런데 옛 책은 그 군사 가운데 살아 돌아간 사람이 놀랄 만큼 적었다고 적어 두었어요. 그 사이에 무슨 일이 있었을까요? 강을 지키던 군사와 강가 마을 아이를 따라가며 알아볼까요?","acts":[{"heading":"세는 사람들","blocks":[{"t":"p","dlg":false,"html":"평양에서 북쪽으로 이틀쯤 걸어 올라가면 서쪽으로 흐르는 큰 강이 하나 있었습니다. 살수라고 했습니다. 오늘날의 청천강입니다."},{"t":"p","dlg":false,"html":"강은 넓었지만 한 군데만은 걸어서 건널 수 있었습니다. 물이 얕고 바닥이 단단한 <em class=\"dot\">여울</em>이었습니다. 배가 없는 사람이 강을 건너려면 누구든 그 여울로 와야 했습니다."},{"t":"p","dlg":false,"html":"여울가에는 말뚝이 하나 박혀 있었고, 말뚝에는 손바닥만 한 나무쪽이 몇 개 걸려 있었습니다."},{"t":"p","dlg":false,"html":"나무쪽을 갈아 매다는 것은 살돌의 일이었습니다. 살돌은 그 여울을 지키는 군사였습니다."},{"t":"p","dlg":false,"html":"살돌이 적는 것은 늘 같았습니다. 물이 무릎까지 오는지 허리까지 오는지, 건너는 데 몇 걸음이 걸리는지, 소달구지가 지나갈 수 있는지."},{"t":"p","dlg":false,"html":"여미는 여울에서 백 걸음 떨어진 마을에 살았습니다. 열한 살이었습니다."},{"t":"p","dlg":false,"html":"여미는 그 여울을 살돌보다 잘 알았습니다. 어디가 가장 깊은지, 어디쯤에서 물살이 사람을 밀어내는지 발바닥으로 알았습니다."},{"t":"p","dlg":true,"html":"“오늘은 무릎.”"},{"t":"p","dlg":false,"html":"여미가 물속에서 소리쳤습니다. 살돌은 그것을 나무쪽에 적었습니다."},{"t":"illust","n":1,"cap":"여울가 말뚝에 나무쪽을 걸어 매는 군사와 물속에 선 아이","src":"img/web/ep041-plate-1.jpg?v=28cf73e55d"},{"t":"p","dlg":false,"html":"그런데 그해 봄부터 나무쪽에 적히는 것이 달라졌습니다."},{"t":"p","dlg":false,"html":"곡식 몇 섬이 어느 성으로 들어갔는지, 어느 성에 군사가 몇이나 있는지, 화살은 얼마나 쌓여 있는지. 살돌이 적는 나무쪽의 절반이 <em class=\"dot\">군량</em> 이야기가 되었습니다. 싸움이 나면 군사들이 성에 틀어박혀 먹을 곡식을 미리 채워 두어야 했기 때문입니다."},{"t":"p","dlg":true,"html":"“왜 갑자기 이런 걸 적어요?”"},{"t":"p","dlg":false,"html":"여미가 물었습니다."},{"t":"p","dlg":true,"html":"“서쪽에서 온다. 서쪽의 큰 나라가 군사를 이끌고 쳐들어온다는 말이다.”"},{"t":"p","dlg":false,"html":"서쪽에서는 아주 오랫동안 여러 나라가 갈라져 싸우고 있었는데, 스무 해 남짓 전에 그 나라들이 하나로 합쳐졌습니다. 그렇게 중국을 다시 하나로 합친 나라가 <em class=\"dot\">수나라</em>였습니다."},{"t":"p","dlg":false,"html":"하나가 된 나라는 동쪽을 보았습니다. 열네 해 전에 한 번 군사를 보냈다가 돌아간 일이 있었지만, 이번에는 그때와 견줄 수 없었습니다."},{"t":"p","dlg":true,"html":"“왜 우리한테 와요?”"},{"t":"p","dlg":true,"html":"“온 세상을 제 발아래 두고 싶은 게지.” 살돌이 말했습니다. “그런데 동쪽에서 고구려만은 고개를 숙이지 않으니, 그게 눈엣가시인 게다.”"},{"t":"p","dlg":false,"html":"여름이 오기 전에 <em class=\"hint\">전갈</em>이 왔습니다. 살돌은 그것을 나무쪽에 옮겨 적다가 손을 멈추고, 전갈을 가져온 군사에게 되물었습니다."},{"t":"p","dlg":true,"html":"“몇이라고요?”"},{"t":"p","dlg":true,"html":"“백십삼만 삼천팔백.”"},{"t":"p","dlg":false,"html":"곁에서 듣던 여미가 물었습니다."},{"t":"p","dlg":true,"html":"“그게 얼마예요?”"},{"t":"p","dlg":false,"html":"살돌은 한참 있다가 대답했습니다."},{"t":"p","dlg":true,"html":"“네 마을에 집이 서른 채지. 한 집에 다섯 사람이면 백오십이다. 그런 마을이 칠천 개는 있어야 그 수가 된다.”"},{"t":"p","dlg":false,"html":"여미는 마을을 일곱 개까지 세어 보고 그만두었습니다. 일곱 개도 여미가 아는 세상의 전부였습니다."},{"t":"p","dlg":false,"html":"전갈에는 이런 말도 붙어 있었습니다. 저쪽 사람들은 그 군사를 이백만이라고 불렀고, 군량을 나르는 사람은 그 두 배였다고요."},{"t":"p","dlg":true,"html":"“그럼 곡식 지고 오는 사람이 싸우는 사람보다 많은 거예요?”"},{"t":"p","dlg":true,"html":"“그렇다는구나.”"},{"t":"p","dlg":false,"html":"살돌은 나무쪽을 말뚝에 걸면서 말했습니다."},{"t":"p","dlg":true,"html":"“이건 적힌 수다. 센 수가 아니고. 누가 하나하나 세어 본 게 아니라, 저쪽이 그렇다고 적어 보낸 수라는 말이다.”"},{"t":"p","dlg":false,"html":"그리고 실제로, 그 큰 군대는 첫 여름을 국경에서 다 써 버렸습니다. 고구려는 서쪽에서 평양으로 오는 길목마다 <em class=\"dot\">산성</em>을 쌓아 두었거든요. 산 위에서 아래를 내려다보며 지키니, 쳐들어오는 쪽은 화살을 맞으며 비탈을 기어올라야 했습니다. 서쪽 문에 해당하는 산성 하나가 몇 달을 버티는 동안, 백만이라는 수는 그 성 앞에 그냥 서 있었습니다."},{"t":"p","dlg":false,"html":"기다리다 못한 황제는 군사를 갈라 <em class=\"dot\">별동대</em>를 만들었습니다. 그 별동대가 삼십만 오천이었습니다."},{"t":"p","dlg":true,"html":"“별동대가 뭐예요?” 여미가 물었습니다."},{"t":"p","dlg":true,"html":"“본대에서 따로 떼어 내 빠르게 움직이게 한 부대다.” 살돌이 말했습니다. “성을 하나하나 치다가는 해가 넘어가니, 성은 그냥 지나쳐 평양으로 곧장 달려가겠다는 거지.”"},{"t":"p","dlg":false,"html":"살돌은 그 수를 나무쪽에 적으며 말을 이었습니다."},{"t":"p","dlg":true,"html":"“우리가 세게 될 수는 이 수다. 평양으로 가려면 이 강을 건너야 하니, 우리 앞으로 올 군사는 이 삼십만 오천이다.”"}]},{"heading":"항복하러 간 사람","blocks":[{"t":"p","dlg":false,"html":"별동대가 <em class=\"hint\">압록수</em> 서쪽에 이르렀다는 말이 왔을 때, 임금은 신하 하나를 그 <em class=\"hint\">진영</em>으로 보냈습니다."},{"t":"p","dlg":false,"html":"임금의 이름은 영양왕이었습니다. 보낸 신하의 이름은 을지문덕이었습니다."},{"t":"p","dlg":false,"html":"을지문덕은 항복하겠다고 하며 적의 진영으로 들어갔습니다. 정말로 항복하러 간 것이 아니었습니다. 저쪽이 어떤 형편인지 제 눈으로 보려고 간 것이었습니다."},{"t":"p","dlg":false,"html":"수나라의 <em class=\"hint\">장수</em> 가운데 우중문이라는 사람이 있었습니다. 우중문은 황제에게서 <em class=\"dot\">밀지</em>를 하나 받아 두고 있었습니다. 남몰래 내린 명령이라 을지문덕은 그런 것이 있는 줄 알 리가 없었습니다."},{"t":"p","dlg":false,"html":"밀지에 적힌 것은 이러했습니다. 고구려의 임금이나 을지문덕이 오거든 반드시 사로잡으라."},{"t":"p","dlg":false,"html":"그러니 을지문덕은 잡히러 걸어 들어간 셈이었습니다. 실제로 우중문은 그를 붙들려고 했습니다. 그런데 항복하러 오는 사람을 달래어 받아들이라고 황제가 함께 보낸 벼슬아치 하나가 굳이 말렸습니다."},{"t":"p","dlg":false,"html":"그래서 을지문덕은 걸어서 그 진영을 나왔습니다."},{"t":"p","dlg":false,"html":"을지문덕이 그 진영에서 본 것은 군사들 얼굴에 도는 굶주린 빛이었습니다."},{"t":"p","dlg":false,"html":"까닭이 있었습니다. 저쪽에서는 군사 한 사람마다 백 일치 곡식을 지웠습니다. 거기에 갑옷과 창과 천막까지 얹으니 한 사람이 진 짐이 세 섬을 넘었습니다. 사람이 그것을 지고 걸을 수는 없었습니다."},{"t":"spot","n":1,"size":"large","cap":"수나라 군사 한 사람에게 백 일치 곡식과 갑옷, 창, 천막을 함께 지게 했다","src":"img/web/ep041-spot-1.jpg?v=e72f7ced91"},{"t":"p","dlg":false,"html":"장수들은 명을 내렸습니다. 쌀을 버리는 자는 목을 벤다."},{"t":"p","dlg":false,"html":"그러자 군사들은 밤마다 제 천막 밑에 구덩이를 파고 곡식을 묻었습니다. 버리다 들키면 죽으니, 아무도 모르게 땅에 묻어 짐을 던 것입니다. 그래서 그 군대는 평양에 닿기도 전에 먹을 것이 거의 떨어졌습니다."},{"t":"p","dlg":false,"html":"을지문덕이 돌아간 뒤에야 우중문은 뉘우쳤습니다. 사람을 보내 “더 할 말이 있으니 돌아오라”고 불렀지만, 을지문덕은 뒤를 돌아보지 않고 압록수를 건너 돌아왔습니다."},{"t":"p","dlg":false,"html":"그다음에 벌어진 일을 살돌은 오래 이해하지 못했습니다."},{"t":"p","dlg":false,"html":"고구려 군사는 싸울 때마다 졌습니다. 하루에 일곱 번을 싸워 일곱 번을 다 져 준 날도 있었습니다."},{"t":"p","dlg":false,"html":"전갈이 올 때마다 살돌은 말뚝 앞에서 주먹을 쥐었습니다."},{"t":"p","dlg":true,"html":"“또 졌답니까.”"},{"t":"p","dlg":true,"html":"“또 졌다.”"},{"t":"p","dlg":false,"html":"지는 동안 저쪽은 남쪽으로 남쪽으로 내려왔습니다. 이기고 있다고 믿으면서요. 그런데 한 걸음 내려올 때마다 저쪽의 곡식 자루는 한 줌씩 더 비어 갔습니다."},{"t":"p","dlg":false,"html":"여미의 마을은 그 무렵 비었습니다. 사람들은 곡식을 지고 산성으로 올라갔습니다. 여미도 따라 올라갔다가 두 번이나 몰래 내려와 여울을 들여다보았습니다."},{"t":"spot","n":2,"size":"normal","cap":"여미의 마을 사람들은 곡식을 지고 산성으로 올라가, 마을을 비워 두었다","src":"img/web/ep041-spot-2.jpg?v=8777a7f63c"},{"t":"p","dlg":false,"html":"그리고 어느 날 여미는 그 여울을 삼십만 오천이 건너는 것을 보았습니다."},{"t":"p","dlg":false,"html":"살돌과 여미는 갈대 뒤에 엎드려 있었습니다. 앞선 무리가 물에 들어서고, 마지막 무리가 다 건널 때까지 해가 한참 기울었습니다. 여미는 그동안 아무 말도 하지 않았습니다. 그렇게 많은 사람을 한꺼번에 본 것은 처음이라, 무슨 말을 해야 할지 알 수 없었습니다."},{"t":"p","dlg":false,"html":"수나라 군대는 살수를 건너 평양성에서 삼십 리 떨어진 곳까지 갔습니다. 그리고 산을 등지고 진을 쳤습니다. 그러고는 더 나아가지 못했습니다."},{"t":"p","dlg":false,"html":"며칠 뒤, <em class=\"hint\">전령</em>이 여울을 건너다가 살돌에게 이런 말을 흘렸습니다. 을지문덕이 우중문에게 <em class=\"dot\">한시</em> 한 편을 지어 보냈다고요. 다섯 글자씩 넉 줄, 모두 스무 글자였습니다."},{"t":"illust","n":2,"cap":"적장에게 보낼 넉 줄짜리 시를 붓으로 적는 장수","src":"img/web/ep041-plate-2.jpg?v=16a2b69c3c"},{"t":"p","dlg":false,"html":"전령이 그것을 우리말로 읽어 주었습니다."},{"t":"p","dlg":true,"html":"“그대의 신묘한 꾀는 하늘의 이치를 다 헤아렸고, 기묘한 셈은 땅의 이치를 다 알았소. 싸워 이겨 공이 이미 높으니, 넉넉한 줄 알고 이만 그치기를 바라오.”"},{"t":"p","dlg":false,"html":"여미가 고개를 갸웃했습니다."},{"t":"p","dlg":true,"html":"“칭찬이잖아요.”"},{"t":"p","dlg":false,"html":"살돌에게도 그렇게 들렸습니다. 그런데 전령이 웃었습니다."},{"t":"p","dlg":false,"html":"앞의 세 줄은 우중문을 높이는 말이었지만, 마지막 줄은 이만하면 되었으니 그만 돌아가라는 말이었습니다."},{"t":"p","dlg":true,"html":"“게다가,” 전령이 말했습니다. “이겼다고 적어 주었으니 저쪽은 이겼다면서 돌아갈 수 있게 되었지. 진 채로 돌아가면 황제에게 벌을 받겠지만, 이기고 돌아간다면 할 말이 생기거든.”"}]},{"heading":"반쯤 건넜을 때","blocks":[{"t":"p","dlg":false,"html":"시를 받은 뒤, 을지문덕은 다시 사람을 보내 항복하겠다는 말을 전했습니다. 군사를 돌리기만 하면 우리 임금을 모시고 가서 황제를 뵙겠다는 것이었지요."},{"t":"p","dlg":false,"html":"물론 거짓말이었습니다."},{"t":"p","dlg":false,"html":"다만 저쪽에는 돌아갈 구실이 필요했습니다. 군사는 지쳤고 먹을 것은 없었고 평양성은 높았습니다. 항복을 받았으니 이기고 돌아간다. 그렇게 말할 수 있게 된 것이지요."},{"t":"p","dlg":false,"html":"칠월, 수나라 군대는 북쪽으로 돌아섰습니다."},{"t":"p","dlg":false,"html":"살돌은 그제야 알았습니다. 일곱 번을 져 준 것은, 굶주린 군대를 더 지치게 하면서 먹을 것 하나 없는 먼 곳까지 끌고 들어오려는 것이었습니다. 이제 그 군대는 올 때 걸어온 먼 길을 빈속으로 되짚어 가야 했습니다."},{"t":"p","dlg":false,"html":"돌아가는 길은 오는 길과 달랐습니다. 그들은 네모지게 진을 짜고 걸었습니다. <em class=\"hint\">사방</em>에서 고구려 군사가 달려들었기 때문입니다."},{"t":"spot","n":3,"size":"normal","cap":"돌아가는 수나라 군사는 네모로 진을 짜고 걸으며, 사방의 공격에 대비했다","src":"img/web/ep041-spot-3.jpg?v=78836b891c"},{"t":"p","dlg":false,"html":"그리고 그 길 위에 살수가 있었습니다."},{"t":"p","dlg":false,"html":"여미가 살돌에게 말해 준 것은 이것이었습니다. 어른 걸음으로 백스무 걸음쯤이고, 가운데가 가장 깊고 물살이 세다고요. 반을 건넌 사람은 얼른 되돌아설 수도 없다고요."},{"t":"p","dlg":false,"html":"을지문덕이 기다린 자리도 거기였습니다. 그 강을 아는 사람이라면 누구나 아는 자리였으니까요."},{"t":"p","dlg":false,"html":"군사가 반쯤 건넜을 때, 고구려 군사가 뒤에서 그 뒤쪽을 쳤습니다."},{"t":"p","dlg":false,"html":"뒤쪽을 맡고 있던 저쪽 장수 하나가 그 자리에서 죽었습니다. 그러자 진이 무너졌습니다. 물속에 있던 사람은 앞으로도 뒤로도 갈 수 없었고, 뒤에 있던 사람은 앞을 밀었습니다."},{"t":"p","dlg":false,"html":"살돌은 그날 사람을 세었습니다. 세는 것이 그의 일이었으니까요. 세다가 그만두었습니다. 그날 본 것은 나무쪽에 적을 수 있는 수가 아니었습니다."},{"t":"p","dlg":false,"html":"살아남은 사람들은 북쪽으로 달아났습니다. 하루 낮 하루 밤을 쉬지 않고 걸어 압록수까지 갔다고 합니다. 사백오십 리 길이었습니다."},{"t":"p","dlg":false,"html":"며칠 뒤 여미는 강가에 내려갔습니다."},{"t":"p","dlg":false,"html":"물가에는 떠내려온 것들이 걸려 있었습니다. 자루, 신, 부러진 창대. 그리고 손바닥만 한 나무 조각이 하나 있었습니다."},{"t":"p","dlg":false,"html":"여미는 그것을 주워 살돌에게 가져갔습니다. 글자가 적혀 있었지만 여미도 살돌도 읽지 못했습니다."},{"t":"illust","n":3,"cap":"싸움이 끝난 강가에서 글자가 적힌 나무 조각을 주워 든 아이","src":"img/web/ep041-plate-3.jpg?v=60278dd3d2"},{"t":"p","dlg":true,"html":"“뭐라고 적힌 거예요?”"},{"t":"p","dlg":true,"html":"“모른다.”"},{"t":"p","dlg":false,"html":"살돌은 한참 들여다보다가 말했습니다."},{"t":"p","dlg":true,"html":"“그런데 이건 안다. 이건 세는 거다. 곡식이든 사람이든, 몇인지 적어 둔 나무쪽이다.”"},{"t":"p","dlg":false,"html":"저쪽에도 살돌 같은 사람이 있어서 곡식이든 사람이든 나무쪽에 적었던 것이지요."},{"t":"p","dlg":false,"html":"여미가 물었습니다."},{"t":"p","dlg":true,"html":"“이 사람도 집이 있었을까요.”"},{"t":"p","dlg":true,"html":"“있었겠지.”"},{"t":"p","dlg":false,"html":"살돌은 나무 조각을 여미에게 돌려주었습니다."},{"t":"p","dlg":true,"html":"“우리 쪽에도 돌아오지 못한 사람이 있다. 이긴 싸움이라고 아무도 안 죽는 것은 아니니까. 다만 그 수는 아무도 적지 않았다.”"},{"t":"p","dlg":false,"html":"가을에 셈이 끝났습니다."},{"t":"p","dlg":false,"html":"압록수를 건너 요동성까지 살아 돌아간 사람은 이천칠백이었습니다. 삼십만 오천 가운데 이천칠백입니다."},{"t":"p","dlg":false,"html":"그러니 “백만 군사가 이천 명이 되었다”는 말은 조금 어긋난 말입니다."},{"t":"p","dlg":false,"html":"게다가 백만이라는 그 수도 조심해서 보아야 합니다. 그것은 수나라가 제 손으로 적은 수이고, 옛 책에 적힌 이런 큰 수는 부풀려진 경우가 많다고 보는 학자가 많습니다. 진 쪽이 제 군대를 크게 적은 것이 이상해 보이지만, 그만한 군대를 일으켰다는 것 자체가 황제의 자랑이었으니까요. 살돌이 말한 대로, 적힌 수와 센 수는 다를 수 있습니다."},{"t":"p","dlg":false,"html":"수나라는 그 뒤로도 두 번 더 왔습니다. 이듬해에는 오다가 제 나라 안에서 반란이 나서 되돌아갔고, 그다음 해에는 오기는 왔으나 싸우지 못하고 물러났습니다."},{"t":"p","dlg":false,"html":"그리고 여섯 해 뒤, 수나라는 무너졌습니다. 갈라진 중국을 하나로 합친 지 서른 해도 되지 않아서였습니다. 백성을 너무 많이 끌어다 썼기 때문이라고 뒷날 사람들은 적었습니다."},{"t":"p","dlg":false,"html":"무너진 자리에는 더 크고 더 오래갈 나라가 들어섰습니다. 당이었습니다."},{"t":"p","dlg":false,"html":"살돌은 그 뒤로도 여울가에서 나무쪽을 갈아 매달았습니다. 다만 거기 적히는 것이 다시 물 높이로만 돌아가지는 않았습니다. 이겼는데도 고구려는 마음을 놓지 못했으니까요. 서쪽에 누가 서든, 서쪽을 계속 보고 있어야 하는 나라가 되었기 때문입니다."}]}],"words":[{"w":"여울","d":"물이 얕고 바닥이 단단해 걸어서 건널 수 있는 강의 자리"},{"w":"군량","d":"싸움터에서 군사들이 먹을 곡식"},{"w":"수나라","d":"오랫동안 여럿으로 갈라져 있던 중국을 다시 하나로 합친 나라"},{"w":"산성","d":"산에 쌓아 아래를 내려다보며 지키는 성"},{"w":"별동대","d":"본대에서 따로 떼어 내 빠르게 움직이게 한 부대"},{"w":"밀지","d":"남이 모르게 몰래 내리는 임금의 명령"},{"w":"한시","d":"한자로 지은 시"}],"hints":[{"w":"전갈","d":"사람을 시켜 전하는 말이나 소식"},{"w":"압록수","d":"압록강의 옛 이름"},{"w":"진영","d":"군대가 머물러 있는 곳"},{"w":"장수","d":"군사를 거느리는 우두머리"},{"w":"전령","d":"명령이나 소식을 전하는 군사"},{"w":"사방","d":"동서남북 네 방향. 곧 모든 곳"}],"after":{"title":"한 해만 남은 사람","html":["이렇게 큰 싸움을 이끌었는데도, 을지문덕에 대해 우리가 아는 것은 612년 한 해가 거의 전부입니다. 『삼국사기』의 을지문덕 열전은 첫머리를 아예 이렇게 시작합니다. 그 집안 내력을 알 수 없다고요. 언제 태어났는지도, 언제 죽었는지도, 그 뒤에 무슨 일을 했는지도 적혀 있지 않습니다. 이름이 남은 사람인데도 남은 것은 한 해뿐인 셈이지요. 그래서 뒷날 사람들은 그를 두고 저마다 다르게 상상했습니다. 조선 시대에는 그를 기리는 사당이 세워졌고, 살수 가까운 고을에는 그가 여기서 무엇을 했다더라 하는 이야기가 여럿 생겨났습니다. 기록이 비어 있는 자리를 사람들의 이야기가 채운 것입니다."]},"ifme":{"q":"그만 돌아가라고 말해야 하는데 그렇게 말할 수 없을 때, 나라면 어떻게 말하겠어요?","html":["을지문덕은 우중문에게 “돌아가라”고 곧장 말하지 않았습니다. 대신 세 줄에 걸쳐 칭찬을 하고 마지막 한 줄에서 그 말을 했지요. 곧장 말했다면 우중문은 화가 나서 더 버텼을지도 모릅니다. 여러분도 그런 자리에 서 본 적이 있을 거예요. 그만하라고 말하고 싶은데 그대로 말하면 싸움이 되는 자리요. 나라면 무슨 말을 어떻게 고르겠어요? 그리고 그렇게 돌려 말하는 것은 늘 좋은 방법일까요? 이 질문에는 정답이 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기는 <b>기록</b>입니다. 을지문덕과 영양왕, 수 양제와 우중문은 실제로 있었던 사람이고, 항복하는 척 적진에 들어간 일도 하루에 일곱 번 싸워 일곱 번 져 준 일도 『삼국사기』에 그대로 적혀 있어요. 스무 글자짜리 시도 그 책에 글자 그대로 실려 있고요. 백십삼만 삼천팔백과 삼십만 오천과 이천칠백이라는 세 수도 모두 옛 책이 적어 둔 수입니다. 살돌과 여미는 지어낸 사람이에요. 살수를 지키던 군사도 강가 마을 아이도 이름이 하나도 남아 있지 않거든요. 그리고 꼭 알아야 할 것이 하나 있습니다. <b>을지문덕이 살수에 둑을 쌓아 물을 가두었다가 터뜨렸다는 이야기는 『삼국사기』에도 『수서』에도 없습니다.</b> 옛 책이 적은 것은 「군사가 반쯤 건넜을 때 뒤를 쳤다」까지예요. 둑 이야기는 아주 뒷날에 덧붙여진 것이고, 그것이 처음 글로 적힌 것은 백 년도 채 되지 않았답니다."]},"quiz":[{"n":1,"kind":"사실 확인","q":"을지문덕이 항복하는 척 적의 진영에 들어가 알아낸 것은 무엇이었나요?","opts":["황제가 요동성 앞에서 이미 돌아갔다는 것","우중문이 항복할 마음을 먹고 있다는 것","수나라 군사들이 살수의 여울을 이미 알고 있다는 것","수나라 군사들이 굶주리고 있다는 것"],"answer":3,"why":{"0":"황제는 성 앞에서 기다리다 못해 별동대를 떼어 보냈습니다.","1":"우중문은 오히려 을지문덕을 사로잡으라는 밀지를 받고 있었습니다.","2":"여울을 발바닥으로 아는 쪽은 저쪽이 아니었고, 을지문덕이 살피러 간 곳도 강이 아니라 진영이었습니다."},"ref":"을지문덕이 그 진영에서 본 것은 군사들 얼굴에 도는 굶주린 빛이었습니다.","more":"왜 굶었을까요. 『삼국사기』는 그 까닭을 아주 자세히 적어 두었어요. 군사 한 사람에게 백 일치 양식과 갑옷·창·천막을 함께 주니 <b>한 사람 몫이 세 섬이 넘었다</b>고 해요. 그래서 「쌀을 버리는 자는 목을 벤다」는 명이 내렸는데도 병사들은 <b>천막 아래에 구덩이를 파고 몰래 묻었고</b>, 길을 반쯤 갔을 때 이미 양식이 떨어졌다고 적혀 있습니다. 군대가 클수록 먹을 것도 늘어나는데, 그 먹을 것을 나르는 사람도 결국 먹어야 하지요."},{"n":2,"kind":"사실 확인","q":"고구려 군사가 살수에서 수나라 군대를 친 것은 언제였나요?","opts":["수나라 군대가 강가에 진을 치고 잠든 밤에","수나라 군대가 강을 다 건너 언덕에 올라섰을 때","수나라 군사가 반쯤 건넜을 때, 뒤에서","수나라 군대가 강으로 들어서기 전, 앞을 막아서서"],"answer":2,"why":{"0":"저쪽은 네모지게 진을 짜고 걸으며 싸우던 중이었지 잠들어 있지 않았습니다.","1":"다 건넌 뒤였다면 물속에서 앞뒤로 갇히는 일이 없었을 것입니다.","3":"앞을 막아섰다면 저쪽은 강에 들어서지 않고 다른 길을 찾았을 것입니다."},"ref":"군사가 반쯤 건넜을 때, 고구려 군사가 뒤에서 그 뒤쪽을 쳤습니다.","more":"『삼국사기』 원문은 이 대목을 짧게 적습니다. <b>「살수에 이르러 군사가 반쯤 건넜을 때 우리 군사가 뒤에서 그 후군을 쳤다(至薩水 軍半濟 我軍自後擊其後軍)」</b>. 그때 죽은 저쪽 장수의 이름은 <b>신세웅</b>이라고 적혀 있어요. 여기까지가 옛 책이 말해 주는 전부이고, 강물을 가두었다가 터뜨렸다는 말은 한 글자도 없답니다."},{"n":3,"kind":"추론","q":"“백만 군사가 이천 명이 되었다”는 말이 어긋난 말인 까닭은 무엇일까요?","opts":["백만도 이천칠백도 뒷날 사람들이 지어낸 수이기 때문에","백만과 이천칠백이 서로 다른 무리를 센 수이기 때문에","고구려가 이겼으므로 죽은 사람이 없었기 때문에","옛 책에는 이천칠백이라는 수가 적혀 있지 않기 때문에"],"answer":1,"why":{"0":"두 수 모두 옛 책에 적혀 있는 수이고, 다만 부풀려졌을 가능성이 이야기되는 것입니다.","2":"이긴 쪽에도 돌아오지 못한 사람이 있었다고 살돌이 말합니다.","3":"요동성으로 돌아간 사람이 이천칠백이라는 것은 옛 책이 적어 둔 수입니다."},"ref":"삼십만 오천 가운데 이천칠백입니다.","more":"수를 하나씩 갈라 보면 이렇습니다. 『삼국사기』가 적은 <b>113만 3,800명</b>은 요하를 건넌 군사를 다 합한 수이고(게다가 「이백만이라 불렀다」는 말과 「군량 나르는 자는 그 두 배」라는 말이 함께 붙어 있어요), <b>30만 5,000명</b>은 그 가운데 평양으로 곧장 달려간 별동대의 수이며, <b>2,700명</b>은 그 별동대 가운데 요동성까지 살아 돌아온 수예요. 요동성 둘레에 남아 있던 군사들은 이 마지막 수에 들어가지 않습니다."},{"n":4,"kind":"낱말·표현","q":"'별동대'는 무엇을 가리키는 말인가요?","opts":["임금의 명을 남몰래 전하러 다니던 사람들","성을 지키려고 산 위에 따로 쌓아 둔 작은 성","군량을 나르는 일만 맡아서 하던 사람들","본대에서 따로 떼어 내 빠르게 움직이게 한 부대"],"answer":3,"why":{"0":"남몰래 내리는 임금의 명령은 밀지라고 합니다.","1":"산에 쌓아 아래를 내려다보며 지키는 성은 산성이라고 합니다.","2":"군량은 싸움터에서 군사들이 먹을 곡식을 가리키는 말입니다."},"ref":"본대에서 따로 떼어 내 빠르게 움직이게 한 부대다.","more":"별동대를 뗀 것은 성이 열리지 않았기 때문이에요. 고구려는 국경에서 평양까지 가는 길목마다 산성을 두어서, 성 하나를 그냥 지나치면 등 뒤에서 길이 끊기게 되어 있었지요. 그래서 큰 군대는 성 앞에 묶이고, 성을 무시하고 달려간 별동대는 등 뒤에 아무 발판도 없이 적진 깊숙이 들어가게 됩니다. 빨리 가려고 뗀 부대가 가장 위태로운 부대가 된 셈이에요."},{"n":5,"kind":"생각 넓히기","q":"학자들의 해석을 따른다면, 을지문덕이 우중문에게 보낸 시의 마지막 줄은 무슨 뜻이었을까요?","opts":["겉으로는 칭찬하는 척하면서, 이만하면 됐으니 돌아가라고 이른 것입니다","항복할 테니 평양성으로 곧장 들어오라고 청한 것입니다","정말로 우중문의 재주에 감탄해 스승으로 삼고 싶다는 뜻입니다","하늘과 땅의 이치를 알려 주는 책을 보내 달라고 부탁한 것입니다"],"answer":0,"why":{"1":"항복하겠다는 말은 시가 아니라 그 뒤에 따로 보낸 전갈에 있었습니다.","2":"그를 높이는 말은 앞의 세 줄이고, 마지막 줄은 그 반대쪽으로 돌아섭니다.","3":"하늘과 땅의 이치는 우중문을 높이는 말 속에 나온 것이지 부탁이 아닙니다."},"ref":"앞의 세 줄은 우중문을 높이는 말이었지만, 마지막 줄은 이만하면 되었으니 그만 돌아가라는 말이었습니다.","more":"시의 원문은 스무 글자예요. <b>「神策究天文 妙算窮地理 戰勝功旣高 知足願云止」</b>. 마지막 줄의 <b>「知足」(지족)</b>은 「넉넉한 줄 안다」는 뜻으로, 옛 중국 책 『노자』에 나오는 말이에요. 상대가 읽으면 곧바로 알아들을 만한 말을 골라 쓴 셈이지요. 이 시는 우리나라에 남아 있는 가장 오래된 한시 가운데 하나로 꼽히고, 「여수장우중문시」라는 이름으로 불립니다."}],"summary":["오랫동안 갈라져 있던 중국을 하나로 합친 수나라가 612년에 고구려로 쳐들어왔어요. 옛 책은 그 군사를 백십삼만 삼천팔백이라고 적었지요.","을지문덕은 항복하는 척 적진에 들어가 그들이 굶주리고 있다는 것을 알아냈고, 일부러 지면서 적을 평양 가까이까지 끌어들였어요.","돌아가던 수나라 군대가 살수를 반쯤 건넜을 때 고구려가 뒤를 쳤어요. 별동대 삼십만 오천 가운데 살아 돌아간 사람은 이천칠백이었습니다."],"bait":["살수에서 진 나라는 곧 무너졌고 더 큰 나라가 그 자리에 섰습니다. 고구려는 국경에 천 리나 되는 성을 쌓기 시작하지요. 그 공사를 맡은 사람이 어느 날 <span class=\"blur\">임금을 갈아치웁니다</span>. 성을 쌓던 사람이 왜 임금을 죽였을까요……"]};

;
(window.EPS ||= {})[42] = {"no":42,"chapter":"2장 세 나라의 시대","when":"631~642년","read":"읽기 16~18분","ago":"약 1,380년 전","title":"성을 쌓던 사람이 왜 임금을 죽였을까","subtitle":"열여섯 해 동안 돌을 진 사람들이 있었고, 그 돌 위에서 나라가 통째로 바뀌었습니다","intro":"오늘 이야기의 무대는 <b>고구려</b>의 서쪽 변경이에요. 세 나라의 시대도 이제 마지막 백 년에 들어섰지요. 고구려 서쪽의 큰 나라가 한 번 더 주인을 바꾸자, 고구려는 국경을 따라 아주 긴 성을 쌓기 시작했어요. 이렇게 나라의 경계를 따라 길게 이어 쌓은 성을 <b>장성</b>이라고 해요. 그런데 그 공사를 맡아 보던 사람이 어느 날 임금을 갈아 치웁니다. 성을 쌓던 사람이 왜 임금을 죽였을까요? 그 성에서 돌을 지던 아버지와 아이를 따라가며 알아볼까요?","acts":[{"heading":"뼈를 묻고 간 사람들","blocks":[{"t":"p","dlg":false,"html":"그해 이월, 아직 눈이 덜 녹은 골짜기로 관리 하나가 올라왔습니다."},{"t":"p","dlg":false,"html":"관리는 마을 사람들을 마당에 모아 놓고 <em class=\"hint\">목판</em>을 펼쳐 이름을 부르기 시작했습니다. 나라의 큰 공사에 <em class=\"dot\">부역</em>을 나갈 사람들이었습니다. 열다섯이 넘고 예순이 안 된 사내는 거의 다 불렸습니다."},{"t":"p","dlg":false,"html":"쇠골도 불렸습니다. 스물여섯이었습니다."},{"t":"p","dlg":true,"html":"“어디로 갑니까.”"},{"t":"p","dlg":true,"html":"“서쪽.”"},{"t":"p","dlg":true,"html":"“서쪽 어디.”"},{"t":"p","dlg":true,"html":"“가 보면 안다.”"},{"t":"p","dlg":false,"html":"지팡이를 짚은 늙은이가 앞으로 나섰습니다."},{"t":"p","dlg":true,"html":"“우리가 이겼잖소. 스무 해 전에. 서쪽에서 쳐들어온 군사들을 강에서 다 쓸어 냈다고 온 나라가 떠들썩했는데, 이제 와서 서쪽에 무슨 일이 있단 말이오.”"},{"t":"illust","n":1,"cap":"눈이 덜 녹은 마을 마당에서 이름이 불리는 사람들","src":"img/web/ep042-plate-1.jpg?v=c1cc654483"},{"t":"p","dlg":false,"html":"관리는 잠깐 대답하지 않았습니다."},{"t":"p","dlg":false,"html":"이긴 것은 맞았습니다. 그러나 그 뒤에 벌어진 일까지 골짜기 사람들이 다 알지는 못했습니다. 고구려에 지고 돌아간 그 나라는 얼마 못 가 무너졌고, 그 자리에 더 큰 나라가 섰습니다. 새로 선 그 나라를 당이라고 했습니다. 그리고 지난겨울 그 나라의 <em class=\"dot\">사신</em>이 다녀갔습니다."},{"t":"p","dlg":false,"html":"사신은 옛 싸움터를 돌며 스무 해 전에 죽은 그쪽 군사들의 뼈를 거두어 묻고 제사를 지냈습니다. 그 싸움터에는 고구려가 이긴 것을 기리려고 크게 쌓아 올린 <em class=\"dot\">경관</em>이 서 있었습니다. 사신은 그 경관을 헐어 버렸고, 임금은 헐도록 두었습니다."},{"t":"p","dlg":false,"html":"관리가 그 이야기를 하자 늙은이의 얼굴이 벌게졌습니다."},{"t":"p","dlg":true,"html":"“그건 우리가 이겼다는 표 아니오. 그걸 남의 나라 사람이 와서 허물었는데 보고만 있었단 말이오?”"},{"t":"p","dlg":true,"html":"“큰 싸움을 치른 지 얼마 안 되어 나라가 아직 지쳐 있다.” 관리가 말했습니다. “새로 선 큰 나라와 지금 다투어 봐야 좋을 것이 없다고 임금께서 보신 게지. 돌무더기 하나 내주고 몇 해를 버는 편이 낫다고.”"},{"t":"p","dlg":false,"html":"늙은이는 고개를 저었습니다. 골짜기 사람들도 대부분 그 말에 수긍하지 않는 얼굴이었습니다."},{"t":"p","dlg":true,"html":"“헐린 것은 다시 쌓으면 되지 않소.” 쇠골이 말했습니다."},{"t":"p","dlg":true,"html":"“다시 쌓으라는 것이 아니다.” 관리가 목판을 접었습니다. “성을 쌓으라신다. 저 나라가 지금은 웃으며 사신을 보내도, 언제 마음을 바꿔 군사를 보낼지 모른다. 싸움을 피하는 것과 싸움에 대비하는 것은 다른 일이 아니다.”"},{"t":"p","dlg":true,"html":"“성이야 산마다 있지 않습니까.”"},{"t":"p","dlg":true,"html":"“그 성들을 다 잇는다.”"},{"t":"p","dlg":false,"html":"관리가 손가락으로 북쪽 하늘을 가리켰다가 천천히 남쪽으로 내렸습니다. 북쪽 끝 <em class=\"hint\">부여성</em>에서 남쪽 바닷가까지였습니다. 천 리가 넘는 거리였습니다."},{"t":"p","dlg":false,"html":"골짜기가 조용해졌습니다."},{"t":"p","dlg":true,"html":"“천 리짜리 담을 어떻게 쌓습니까.” 쇠골이 물었습니다."},{"t":"p","dlg":true,"html":"“담을 쌓는 것이 아니다.” 관리가 말했습니다. “있는 성을 손보고, 성과 성 사이에 사람이 넘어 다니는 낮은 자리를 막는 것이다. 그러면 서쪽에서 오는 것들은 성을 하나하나 다 열고 와야 한다. 성 하나를 여는 데 한 달이 걸리면, 열 개를 열려면 열 달이 걸리겠지.”"},{"t":"p","dlg":false,"html":"그해 봄부터 쇠골은 서쪽으로 갔습니다. 봄에 가서 겨울에 돌아왔고, 다음 봄에 또 갔습니다."},{"t":"p","dlg":false,"html":"가서 지내는 곳은 성 아래 골짜기에 지은 임시 <em class=\"hint\">움막</em>이었습니다. 스무 사람이 한 움막에 들었고, 곡식은 나라에서 내주었지만 늘 모자랐습니다. 소금은 더 귀해서 집에서 가져온 소금 주머니를 베개 밑에 두고 자는 사람도 있었습니다."},{"t":"spot","n":1,"size":"normal","cap":"성 쌓는 사람들은 한 움막에 스무 명씩 묵었고, 귀한 소금은 베개 밑에 두었다","src":"img/web/ep042-spot-1.jpg?v=000bbf4af8"},{"t":"p","dlg":false,"html":"일은 거의 다 돌이었습니다. 산에서 돌을 떼어 내고, 지게에 얹어 비탈을 오르고, 모서리를 다듬어 앞뒤가 맞지 않는 것을 골라냈습니다. 고구려의 성벽은 돌을 곧게만 올리지 않고 안쪽으로 조금씩 물려 가며 쌓아서, 아래가 넓고 위가 좁았습니다. 그래야 무게가 아래로 고루 실려 오래 버틴다고 했습니다."},{"t":"p","dlg":false,"html":"쇠골이 처음으로 신기해한 것은 성벽이 곧게만 가지 않는다는 것이었습니다. 벽이 한참 가다가 사람 키의 몇 곱절만 한 네모가 밖으로 불쑥 튀어나왔습니다."},{"t":"p","dlg":true,"html":"“저건 왜 튀어나오게 쌓습니까?”"},{"t":"p","dlg":false,"html":"돌을 다듬던 늙은 석수가 턱으로 성벽 아래를 가리켰습니다."},{"t":"p","dlg":true,"html":"“적이 성벽에 바짝 붙으면 위에서는 안 보인다. 제 발밑이니까. 그래서 벽 밖으로 저렇게 네모나게 튀어나오게 <em class=\"dot\">치</em>를 쌓아 두면, 거기 올라서서 벽을 따라 옆으로 내다보며 성에 달라붙는 적을 옆에서 막을 수 있지.”"},{"t":"p","dlg":false,"html":"쇠골은 성벽 위에서 고개를 내밀어 보았습니다. 바로 발밑은 보이지 않았지만, 치 쪽으로 눈을 돌리자 벽 아래가 한눈에 들어왔습니다."},{"t":"spot","n":2,"size":"large","cap":"성벽 밖으로 내민 치에서는, 벽에 바짝 붙은 적을 옆에서 살펴 막을 수 있었다","src":"img/web/ep042-spot-2.jpg?v=684d50d05b"},{"t":"p","dlg":false,"html":"그해 겨울 쇠골이 집에 돌아왔을 때 아이가 나 있었습니다. 봄내라고 지었습니다."}]},{"heading":"아홉 해가 지나고","blocks":[{"t":"p","dlg":false,"html":"봄내가 열 살이 되던 해에도 성은 다 서지 않았습니다."},{"t":"p","dlg":false,"html":"그 아홉 해 동안 골짜기에 오는 사람은 해마다 조금씩 바뀌었습니다. 첫해에 쇠골과 나란히 이름이 불렸던 이웃 하나는 네 해째 봄에 나오지 않았습니다. 겨울에 앓다가 죽었다고 했습니다. 그 자리에는 그 집의 맏아들이 나왔는데, 아버지가 지던 지게를 그대로 졌습니다."},{"t":"p","dlg":false,"html":"성은 그렇게 사람을 갈아 끼우며 조금씩 길어졌습니다."},{"t":"p","dlg":false,"html":"그해 봄 봄내는 처음으로 아버지를 따라갔습니다. 아이가 할 수 있는 일은 물을 나르는 것이었습니다. 나무 물통 둘을 어깨에 걸고 골짜기 아래 샘에서 성벽 위까지 하루에도 몇 번씩 올랐습니다."},{"t":"p","dlg":true,"html":"“아버지, 이거 언제 다 쌓아요?”"},{"t":"p","dlg":true,"html":"“모르겠다.”"},{"t":"p","dlg":true,"html":"“열 해나 쌓았잖아요.”"},{"t":"p","dlg":true,"html":"“열 해 더 쌓을 수도 있지.”"},{"t":"p","dlg":false,"html":"봄내는 아버지의 손을 보았습니다. 굳은살이 두껍게 앉아서 손금이 어디 있는지 알 수 없는 손이었습니다."},{"t":"p","dlg":false,"html":"그 봄에 새 감독이 왔습니다."},{"t":"p","dlg":false,"html":"고구려는 도읍을 다섯 부(部)로 나누었고, 부마다 대인이라 부르는 우두머리 집안이 있었습니다. 새 감독은 그 가운데 한 집안의 아들이라고 했습니다. 이름은 연개소문이었습니다."},{"t":"p","dlg":false,"html":"<em class=\"hint\">인부</em>들 사이에 그의 이야기가 돌았습니다."},{"t":"p","dlg":false,"html":"그의 아버지는 고구려에서 가장 높은 벼슬인 <em class=\"dot\">대대로</em>를 지낸 사람이었습니다. 아버지가 죽자 아들이 그 자리를 이어야 했는데, 도읍의 높은 사람들이 그의 성품을 꺼려 이어받지 못하게 막았다고 했습니다. 그가 머리를 조아리고 “한번만 맡겨 보시고 안 되겠거든 그때 내치십시오”라고 빈 뒤에야 겨우 그 자리에 앉았다는 것이었습니다."},{"t":"p","dlg":false,"html":"또 하나 도는 이야기가 있었습니다. 그가 스스로 물속에서 태어났다고 말하고 다닌다는 것이었습니다."},{"t":"p","dlg":true,"html":"“그게 정말이에요?” 봄내가 물었습니다."},{"t":"p","dlg":true,"html":"“물속에서 나는 사람이 어디 있느냐.”"},{"t":"p","dlg":true,"html":"“그럼 왜 그런 말을 해요?”"},{"t":"p","dlg":false,"html":"쇠골은 돌을 내려놓고 한참 있다가 대답했습니다."},{"t":"p","dlg":true,"html":"“그런 말을 하고 다니면 사람들이 보통 사람이 아닌 줄 알고 무서워하니까.”"},{"t":"p","dlg":false,"html":"봄내는 그 사람을 딱 한 번 보았습니다. 물통을 진 채 성벽 위에 서 있을 때였습니다. 말에서 내리는 사람 둘레로 사람들이 저절로 물러섰고, 그 사람은 성벽이 꺾이는 자리에 한참 서 있다가 갔습니다."},{"t":"illust","n":2,"cap":"물통을 진 아이가 성벽 위에서 새 감독을 멀리 내려다봅니다","src":"img/web/ep042-plate-2.jpg?v=2d8ae352c8"},{"t":"p","dlg":false,"html":"그날 저녁 인부들의 말이 갈렸습니다."},{"t":"p","dlg":true,"html":"“어젯밤에 우리 밥을 같이 먹더라. 소금국에 조밥을.”"},{"t":"p","dlg":true,"html":"“그 앞에서 아무도 고개를 못 들던데.”"},{"t":"p","dlg":true,"html":"“둘 다 그럴 수 있지. 밥을 같이 먹는 것도, 사람을 떨게 하는 것도 다 사람을 부리는 재주니까.”"},{"t":"p","dlg":false,"html":"쇠골은 둘 다 들었지만 어느 쪽도 제 눈으로 보지는 못했습니다."},{"t":"p","dlg":true,"html":"“아버지.” 봄내가 물었습니다. “저렇게 높은 사람이 왜 여기까지 와요? 도읍에 있으면 안 돼요?”"},{"t":"p","dlg":true,"html":"“낸들 아느냐.”"},{"t":"p","dlg":false,"html":"이 골짜기에서 도읍까지는 걸어서 여러 날이 걸렸습니다."},{"t":"p","dlg":false,"html":"감독이 온 뒤로 공사는 빨라졌습니다. 해가 진 뒤에도 <em class=\"hint\">관솔불</em>을 켜고 돌을 다듬는 날이 늘었습니다. 봄내는 그해 여름에 물통을 스무 번씩 졌습니다."},{"t":"spot","n":3,"size":"normal","cap":"감독이 온 뒤에는 해가 져도 관솔불을 켜고, 성 쌓을 돌을 다듬는 날이 늘었다","src":"img/web/ep042-spot-3.jpg?v=b842602184"},{"t":"p","dlg":false,"html":"가을에 집으로 돌아가는 길에 봄내가 물었습니다."},{"t":"p","dlg":true,"html":"“아버지, 성이 다 서면 저 사람은 뭐가 좋아요?”"},{"t":"p","dlg":true,"html":"“성이 서면 서쪽에서 오는 것들이 못 들어오지.”"},{"t":"p","dlg":true,"html":"“그건 우리한테 좋은 거고요. 저 사람한테는요?”"},{"t":"p","dlg":false,"html":"쇠골은 대답하지 않았습니다. 성이 서면 골짜기 사람들은 마음 놓고 살 수 있습니다. 그런데 도읍의 큰 집안 사람이 여러 날 길을 와서 인부들 틈에 섞여 지내는 것이 그 사람에게는 무슨 좋은 일일까요. 쇠골도 그것은 알지 못했습니다."}]},{"heading":"시월","blocks":[{"t":"p","dlg":false,"html":"두 해가 더 지나, 봄내가 열두 살이던 해 시월이었습니다."},{"t":"p","dlg":false,"html":"어느 날 아침 감독이 군사를 데리고 도읍으로 내려갔습니다. 성 쌓는 자리에는 아무 말도 남기지 않았습니다."},{"t":"p","dlg":false,"html":"소식은 여러 날 뒤에 왔습니다. 곡식을 싣고 온 사람들이 가져왔습니다."},{"t":"p","dlg":false,"html":"소식을 가져온 사람도 그 자리에 있었던 것은 아니었습니다. 도읍에서 들은 것을 옮겼고, 그 사람도 누구에게 들은 것이었습니다. 골짜기까지 오는 동안 그 이야기가 몇 사람의 입을 지났는지는 아무도 세지 않았습니다."},{"t":"p","dlg":false,"html":"그 무렵 도읍에서는 임금과 여러 대인이 그를 죽이기로 의논하고 있었습니다. 그의 성품이 사납고 모질다는 것이 까닭이었다고 옛 책은 적었습니다. 그가 그것을 먼저 알았습니다. 그리고 그들보다 먼저 움직였습니다."},{"t":"p","dlg":false,"html":"그는 제 <em class=\"dot\">부병</em>을 성 남쪽 벌판에 죽 늘어세우고 <em class=\"dot\">사열</em>을 하겠다고 했습니다. 그러고는 사열을 보러 오라고 여러 <em class=\"hint\">대신</em>을 불렀습니다. 술과 음식도 차려 두었습니다. 누가 보아도 군사를 구경하고 함께 먹고 마시는 자리였습니다."},{"t":"p","dlg":false,"html":"부름을 받고 온 사람들은 그 자리에서 죽었습니다. 백 명이 넘었습니다."},{"t":"p","dlg":false,"html":"그는 곧바로 궁으로 갔습니다. 임금도 그날 죽었습니다."},{"t":"p","dlg":false,"html":"그는 임금의 조카를 새 임금으로 세웠습니다. 그리고 스스로 <em class=\"dot\">막리지</em>가 되었습니다. 임금 자리에는 새 사람이 앉았지만, 그 임금을 세운 사람은 그였습니다. 이제 고구려의 군사도 벼슬아치도 그의 말을 따라야 했습니다. 그가 나라를 손에 쥔 것입니다."},{"t":"p","dlg":false,"html":"이야기를 다 들은 뒤에도 골짜기는 한동안 조용했습니다. 그러다 여기저기서 말이 터져 나왔습니다."},{"t":"p","dlg":true,"html":"“임금이 먼저 죽이려 했다지 않소. 가만있었으면 제가 죽었을 거요.”"},{"t":"p","dlg":true,"html":"“먼저든 나중이든 임금은 임금이오. 신하가 임금을 죽이는 법은 없소.”"},{"t":"p","dlg":true,"html":"“그 임금은 우리가 이긴 표를 남의 나라 사람이 허무는 걸 보고만 있었소.”"},{"t":"p","dlg":true,"html":"“그래서 우리한테 뭐가 달라지오? 돌은 그대로 우리가 지는데.”"},{"t":"p","dlg":false,"html":"아무도 다른 사람을 설득하지 못했습니다."},{"t":"p","dlg":true,"html":"“아버지는 어느 쪽이에요?” 봄내가 물었습니다."},{"t":"p","dlg":false,"html":"쇠골은 한참 있다가 말했습니다."},{"t":"p","dlg":true,"html":"“나는 열 해가 넘게 이 성을 쌓았다. 그동안 임금이 바뀐 것은 오늘이 처음이다. 그런데 임금이 바뀌어도 내일 아침에 나는 저 돌을 진다. 누가 옳은지는 나도 모르겠다.”"},{"t":"p","dlg":false,"html":"이튿날 아침 쇠골은 돌을 졌습니다. 골짜기의 다른 사람들도 다 졌습니다. 다만 그날부터 재촉이 심해졌습니다. 도읍에서 내려온 말은 성을 더 빨리 쌓으라는 것이었습니다."},{"t":"p","dlg":true,"html":"“임금을 죽인 사람이 나라를 쥐었으니, 서쪽 나라가 그걸 핑계 삼아 가만있지 않을 거라던데.”"},{"t":"p","dlg":false,"html":"누군가 그렇게 말했습니다. 그리고 그 말은 맞았습니다."},{"t":"p","dlg":false,"html":"성은 그 뒤로도 쌓였습니다. 처음 돌을 뜬 해부터 다 쌓기까지 열여섯 해가 걸렸습니다. 쇠골은 그 열여섯 해를 거의 다 그 골짜기에서 보냈습니다."},{"t":"p","dlg":false,"html":"다 쌓고 나서도 그 성에는 이름이 없었습니다. 옛 책은 그저 “긴 성”이라고만 적어 두었고, 그 뒤에 “천 리가 넘는다”고 덧붙였습니다. 「천리장성」이라는 이름은 뒷사람들이 그 두 말을 붙여 부른 것입니다."},{"t":"p","dlg":false,"html":"봄내가 다 자란 뒤에 아버지에게 물은 적이 있습니다."},{"t":"p","dlg":true,"html":"“이 성은 누구 성이에요?”"},{"t":"p","dlg":true,"html":"“임금 성이지.”"},{"t":"p","dlg":true,"html":"“임금이 바뀌었잖아요.”"},{"t":"p","dlg":false,"html":"쇠골은 제 손을 들여다보았습니다. 열여섯 해 동안 돌을 진 손이었습니다."},{"t":"p","dlg":true,"html":"“그럼 쌓은 사람 성이겠구나.”"},{"t":"p","dlg":false,"html":"그러나 그 성을 적어 둔 책에는 쌓은 사람의 이름이 한 사람도 없습니다."},{"t":"illust","n":3,"cap":"열여섯 해 만에 다 선 성벽 위에 나란히 앉은 두 사람","src":"img/web/ep042-plate-3.jpg?v=049d7766b0"}]}],"words":[{"w":"부역","d":"나라의 큰 공사에 백성이 불려 나가 일하던 것"},{"w":"사신","d":"임금의 뜻을 전하러 다른 나라에 보내는 신하"},{"w":"경관","d":"싸움에서 이긴 것을 기리려고 크게 쌓아 올린 기념물"},{"w":"치","d":"성벽 밖으로 네모나게 튀어나오게 쌓아, 성에 달라붙는 적을 옆에서 막는 자리"},{"w":"대대로","d":"고구려에서 나랏일을 도맡아 보던 가장 높은 벼슬"},{"w":"부병","d":"부마다 따로 거느리던 군사"},{"w":"사열","d":"군사들을 죽 늘어세워 놓고 살펴보는 일"},{"w":"막리지","d":"군사와 벼슬아치를 함께 거느리던 고구려의 가장 높은 자리"}],"hints":[{"w":"목판","d":"글을 적은 나무판"},{"w":"부여성","d":"고구려 북쪽 끝에 있던 성"},{"w":"움막","d":"땅을 파고 거적 따위를 덮어 대충 지은 집"},{"w":"인부","d":"품삯을 받고 힘든 일을 하는 사람"},{"w":"관솔불","d":"송진이 엉긴 소나무 가지에 붙인 불"},{"w":"대신","d":"나라의 높은 신하"}],"after":{"title":"이름이 바뀐 사람","html":["연개소문의 성은 「연(淵)」입니다. 그런데 당나라에서 지은 책들은 그의 성을 「천(泉)」이라고 적었어요. 당나라를 세운 첫 황제의 이름이 이연(李淵)이었기 때문입니다. 옛 중국에서는 황제 집안 사람의 이름에 든 글자를 그대로 쓰지 않고 다른 글자로 바꾸어 적는 법이 있었거든요. 그래서 당나라 사람들의 책에서 그는 「천개소문」이 되었습니다. 『삼국사기』도 그 책들을 옮겨 오면서 그의 성을 천씨라고 적었고요. 뒷날 그의 아들 무덤에서 나온 돌에도 「천남생」이라고 새겨져 있습니다. 이름 한 글자에도 적는 사람의 사정이 묻어 있는 셈이지요."]},"ifme":{"q":"같은 사람을 두고 「영웅」이라고 적은 책과 「역적」이라고 적은 책이 함께 남아 있다면, 나는 그 사람을 어떻게 기억하면 좋을까요?","html":["연개소문은 이웃의 큰 나라가 쳐들어왔을 때 그것을 막아 낸 사람입니다. 동시에 임금과 신하 백여 명을 죽이고 힘을 잡은 사람이기도 하지요. 이 둘은 서로 다른 이야기가 아니라 한 사람의 같은 삶입니다. 한쪽만 골라 기억하면 마음이 편하지만, 그러면 그 사람의 절반을 지우는 셈이 됩니다. 두 가지를 다 안 채로 한 사람을 기억하는 방법이 있을까요? 만약 내가 그 골짜기에서 돌을 지던 사람이었다면 저녁의 그 네 마디 가운데 어느 쪽에 고개를 끄덕였을까요? 이 질문에는 정답이 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 옛 책에 이름과 사건이 또렷이 적혀 있다는 뜻이에요. 성을 쌓기 시작한 해도, 사열을 핑계로 대신들을 불러 모은 일도, 임금이 죽고 그 조카가 새 임금이 된 일도 『삼국사기』 고구려본기와 개소문 열전에 그대로 있습니다. 다만 쇠골과 봄내는 지어낸 사람이에요. 열여섯 해 동안 그 돌을 진 사람이 수없이 많았을 텐데, 옛 책은 그들의 이름을 한 사람도 적어 두지 않았거든요. 연개소문이 그 골짜기에 왔다는 기록도 없어요. 그가 장성 쌓는 일을 맡아 보았다는 데까지가 우리가 아는 전부랍니다. 그리고 한 가지 더 있습니다. 연개소문을 어떻게 볼 것인가는 지금도 갈려요. 『삼국사기』를 쓴 김부식은 그를 임금을 죽인 역적이라 크게 나무랐고, 훨씬 뒷날 나라를 빼앗긴 시절의 사람들은 그를 큰 나라에 맞선 영웅으로 다시 읽었습니다. 어느 쪽도 아직 이기지 못했어요."]},"quiz":[{"n":1,"kind":"사실 확인","q":"고구려가 국경을 따라 아주 긴 성을 쌓기 시작한 것은 어떤 일이 있고 나서였나요?","opts":["서쪽의 큰 나라가 고구려의 성을 하나 빼앗아 갔기 때문에","이웃 나라와 국경을 어디로 할지 다투다가 싸움이 났기 때문에","서쪽에 더 큰 나라가 서고, 그 나라의 사신이 경관을 헐고 간 뒤","임금이 도읍을 서쪽으로 옮기기로 정했기 때문에"],"answer":2,"why":{"0":"성을 빼앗겼다는 이야기는 나오지 않고, 골짜기 사람들은 스무 해 전에 이겼던 일을 이야기합니다.","1":"성을 쌓기 시작한 때에는 아직 싸움이 벌어지지 않았습니다.","3":"도읍을 옮긴다는 말은 어디에도 없고, 관리가 가리킨 것은 북쪽 끝에서 남쪽 바닷가까지의 국경이었습니다."},"ref":"사신은 그 경관을 헐어 버렸고, 임금은 헐도록 두었습니다.","more":"『삼국사기』 고구려본기 영류왕 14년(631년) 조에 이 두 가지가 나란히 적혀 있어요. 당나라가 광주사마 장손사를 보내 <b>수나라 군사들의 유해를 묻고 제사 지내게 하며 그때 세운 경관을 헐었다</b>는 것과, 그해 이월에 <b>왕이 사람들을 움직여 장성을 쌓았다</b>는 것이지요. 경관은 싸움에 이긴 쪽이 그 사실을 오래 남기려고 크게 쌓아 올린 것이라, 그것을 헐었다는 것은 「그 승리를 인정하지 않겠다」는 말이나 같았어요. 그런데도 고구려가 그것을 막지 않은 데에는 까닭이 있었어요. 앞선 큰 싸움으로 나라가 지쳐 있었기 때문에, 임금은 서쪽의 새 나라와 되도록 다투지 않으려 했거든요. 성을 쌓는 일과 사신을 곱게 돌려보내는 일은 그 임금에게 한 가지 생각의 두 쪽이었던 셈이에요."},{"n":2,"kind":"사실 확인","q":"연개소문은 도읍의 대신들을 무슨 구실로 한자리에 불러 모았나요?","opts":["서쪽에서 온 사신을 함께 맞이하자며 불렀습니다","성을 다 쌓았으니 잔치를 열자며 불렀습니다","임금이 병들었으니 함께 문병을 가자며 불렀습니다","군사를 사열할 테니 함께 보자며 대신들을 불렀습니다"],"answer":3,"why":{"0":"사신이 다녀간 것은 성을 쌓기 시작하기 전, 그러니까 열 해도 더 전의 일입니다.","1":"이 일이 벌어졌을 때 성은 아직 다 쌓이지 않았고, 그 뒤로도 여러 해를 더 쌓았습니다.","2":"임금이 병들었다는 이야기는 나오지 않습니다."},"ref":"그러고는 사열을 보러 오라고 여러 대신을 불렀습니다.","more":"『삼국사기』는 그가 <b>부병을 모두 모아 놓고 마치 군대를 사열할 것처럼 하고, 성 남쪽에 술과 안주를 성대히 차려 놓은 뒤 여러 대신을 불러 함께 보자고 했다</b>고 적어요. 온 사람들을 모두 죽였는데 <b>대략 백여 명</b>이었다고도 적혀 있고요. 이 일이 일어난 때는 642년 시월입니다."},{"n":3,"kind":"추론","q":"도읍의 높은 사람들이 연개소문에게 성 쌓는 일을 맡긴 데에는 어떤 뜻이 숨어 있었을까요?","opts":["도읍에서 아주 멀리 떨어진 곳에 그를 두려고","그가 스스로 성을 쌓겠다고 여러 번 청했기 때문에","그가 돌을 다루는 솜씨로 이름난 장인이었기 때문에","성을 쌓을 사람이 그 말고는 아무도 남지 않았기 때문에"],"answer":0,"why":{"1":"그가 스스로 청했다면 임금과 대인들이 뒤에 그를 죽이려고 의논할 까닭이 없습니다.","2":"그는 돌을 다루는 사람이 아니라 큰 집안의 아들이었고, 돌을 다룬 것은 쇠골 같은 사람들이었습니다.","3":"성을 쌓은 것은 해마다 마을에서 불려 나간 수많은 사람들이었습니다."},"ref":"이 골짜기에서 도읍까지는 걸어서 여러 날이 걸렸습니다.","more":"이것은 이야기가 곧바로 말해 주지 않는 대목이라, 흩어진 조각을 이어야 보여요. ① 사람들이 그의 성품을 꺼려 아버지의 자리를 잇지 못하게 막았다 ② 그런데도 그렇게 큰 집안의 사람이 도읍에서 여러 날 걸리는 변방에 와 있다 ③ 그 얼마 뒤 임금과 대인들이 그를 죽이기로 의논한다. 국사편찬위원회의 설명도 영류왕이 그를 <b>평양에서 멀리 떼어 놓으려고</b> 장성 감독을 맡겼다고 봅니다. 다만 「멀리 보내려는 뜻이었다」고 옛 책이 못 박아 적은 것은 아니고, 학자들이 앞뒤를 이어 그렇게 읽는 것이에요."},{"n":4,"kind":"낱말·표현","q":"'치'는 무엇을 가리키는 말인가요?","opts":["싸움에서 이긴 것을 기리려고 크게 쌓아 올린 기념물","나라의 큰 공사에 백성이 불려 나가 일하던 것","성을 쌓으려고 산에서 떼어 내 모서리를 다듬은 돌","성벽 밖으로 네모나게 튀어나오게 쌓아, 성에 달라붙는 적을 옆에서 막는 자리"],"answer":3,"why":{"0":"이긴 것을 기리려고 크게 쌓아 올린 기념물은 경관이라고 합니다.","1":"백성이 불려 나가 일하던 것은 부역이라고 합니다.","2":"돌은 치를 쌓는 재료일 뿐이고, 치는 성벽에서 튀어나온 자리를 가리킵니다."},"ref":"그래서 벽 밖으로 저렇게 네모나게 튀어나오게 치를 쌓아 두면, 거기 올라서서 벽을 따라 옆으로 내다보며 성에 달라붙는 적을 옆에서 막을 수 있지.","more":"치는 고구려 성의 큰 특징이에요. 성벽이 곧기만 하면 벽에 바짝 달라붙은 적은 위에서 내려다볼 수가 없는데, 일정한 사이를 두고 네모난 자리를 밖으로 내밀면 그 옆구리를 볼 수 있게 되지요. 요동의 백암성이나 서울의 아차산 보루 같은 고구려 성터에서 지금도 볼 수 있고, 뒷날 조선의 성에도 이어집니다."},{"n":5,"kind":"생각 넓히기","q":"학자들의 해석을 따른다면, 당나라에서 지은 책들이 연개소문의 성을 「천(泉)」이라고 적은 까닭은 무엇일까요?","opts":["그가 물속에서 태어났다고 스스로 말하고 다녔기 때문에","당나라를 세운 황제 집안의 이름과 같은 글자를 피하려고","고구려 사람들이 그의 성을 잘못 적어 두었기 때문에","「연」과 「천」이 본디 같은 글자였기 때문에"],"answer":1,"why":{"0":"물속에서 태어났다는 말은 그가 스스로 하고 다닌 이야기이지 성이 바뀐 까닭은 아닙니다.","2":"그의 성을 바꾸어 적은 것은 고구려 쪽이 아니라 당나라 쪽 책입니다.","3":"「연(淵)」과 「천(泉)」은 뜻이 비슷할 뿐 서로 다른 글자입니다."},"ref":"당나라를 세운 첫 황제의 이름이 이연(李淵)이었기 때문입니다.","more":"이렇게 임금이나 그 집안 어른의 이름에 든 글자를 피해서 다른 글자로 바꾸어 적는 것을 <b>피휘</b>라고 해요. 그래서 『구당서』·『신당서』 같은 당나라 쪽 책에는 그가 「천개소문」으로 나오고, 그 책들을 참고한 『삼국사기』 개소문 열전도 <b>「성은 천씨이다」</b>로 시작합니다. 기록은 이렇게 적는 사람이 놓인 사정을 탑니다. 무엇이 적혔는지만 볼 것이 아니라 <b>누가 어디서 적었는지</b>를 함께 보아야 하는 까닭이지요."}],"summary":["서쪽에 더 큰 나라가 서고 그 나라의 사신이 고구려의 기념물을 헐고 가자, 고구려는 국경을 따라 아주 긴 성을 쌓기 시작했어요. 그 공사는 열여섯 해나 이어졌습니다.","그 성 쌓는 일을 맡아 보던 연개소문이 642년에 임금과 대신 백여 명을 죽이고 나라를 손에 쥐었어요. 임금의 조카를 새 임금으로 세우고 자신은 막리지가 되었지요.","그를 두고 「큰 나라에 맞선 영웅」이라는 말과 「임금을 죽인 역적」이라는 말이 함께 남아 있어요. 천사백 년이 지난 오늘까지도 어느 한쪽으로 정해지지 않았습니다."],"bait":["그가 나라를 손에 쥐자, 서쪽의 황제가 그것을 쳐들어올 구실로 삼습니다. 성들이 차례로 열렸지요. 그런데 마지막 작은 성 하나 앞에서 황제가 멈춰 섭니다. 그 성을 지킨 성주는 <span class=\"blur\">이름이 남아 있지 않습니다</span>. 왜일까요……"]};

;
(window.EPS ||= {})[43] = {"no":43,"chapter":"2장 세 나라의 시대","when":"645년","read":"읽기 16~18분","ago":"약 1,380년 전","title":"이름 없는 성주는 어떻게 황제를 물리쳤을까","subtitle":"석 달 가까이 버틴 성이 있었습니다. 그 성을 지킨 사람의 이름은 남지 않았습니다","intro":"오늘 이야기의 무대는 <b>고구려</b>예요. 이 무렵 서쪽에서는 살수에서 크게 지고 무너진 나라의 자리에 새 나라가 섰고, 그 나라의 황제가 몸소 군사를 이끌고 요동으로 넘어왔어요. 고구려의 큰 성들이 차례로 열렸지만 마지막에 만난 작은 성 하나에서 황제는 끝내 멈춰 섰지요. 그런데 이상한 일이 있습니다. 그 성을 끝까지 지켜 낸 사람이 누구였는지 오늘 우리는 모릅니다. 어느 옛 책에도 적혀 있지 않거든요. 성 안에 있던 아이와 성벽을 고치던 늙은이를 따라가며 알아볼까요?","acts":[{"heading":"성벽은 어디부터 무너지나","blocks":[{"t":"p","dlg":false,"html":"요동의 여름은 짧습니다."},{"t":"p","dlg":false,"html":"성 아래 <em class=\"hint\">조밭</em>은 아직 푸른데 아무도 그것을 벨 생각을 하지 않았습니다. 서쪽 길로 사람이 자꾸 넘어왔기 때문입니다. 곧 이곳도 싸움터가 될 텐데, 덜 여문 조를 벨 틈이 없었습니다."},{"t":"p","dlg":false,"html":"넘어온 사람들은 성문 앞에 주저앉아 같은 말을 했습니다. 개모성이 열렸다. 요동성이 열렸다. 백암성은 싸우지도 않고 문을 열었다."},{"t":"spot","n":1,"size":"normal","cap":"서쪽 성들이 잇달아 열리자, 그곳에서 넘어온 사람들이 안시성 앞에 주저앉았다","src":"img/web/ep043-spot-1.jpg?v=23777a7e95"},{"t":"p","dlg":false,"html":"<em class=\"dot\">요동</em> 땅의 성들이 몇 달 사이에 차례로 열린 것입니다. 이제 서쪽에서 오는 군대와 안시성 사이에는 막아 줄 큰 성이 남아 있지 않았습니다."},{"t":"p","dlg":false,"html":"넘어온 사람들은 황제 이야기도 했습니다. 살수에서 진 그 나라가 무너진 자리에 선 새 나라였는데, 이름을 <em class=\"dot\">당</em>이라고 했습니다. 당의 황제는 남에게 맡기지 않고 제가 직접 군사를 몰고 왔습니다. 고구려에서 신하 하나가 임금을 갈아치운 일을 두고 그 죄를 묻겠다고 했다지요."},{"t":"p","dlg":false,"html":"봄내는 그 말을 성문 안쪽에 앉아 들었습니다. 열다섯이었습니다."},{"t":"p","dlg":false,"html":"세 해 전까지 봄내는 아버지를 따라 성 쌓는 골짜기에 있었습니다. 나라가 국경에 천 리나 되는 성을 쌓던 때였고, 봄내의 아버지가 그 일에 불려 갔습니다. 봄내는 물통을 지고 성벽을 오르내리며, 어른들이 돌을 쌓고 흙을 다지는 것을 날마다 곁에서 보았습니다. 그래서 봄내는 성벽이 어떻게 서는지 알았고, 어디부터 무너지는지는 더 잘 알았습니다."},{"t":"p","dlg":false,"html":"안시성의 무너진 자리를 고치는 일은 덤불이 맡고 있었습니다. 예순이 넘은 늙은이였습니다."},{"t":"p","dlg":false,"html":"덤불이 벌어진 틈에 돌을 끼워 넣고 그 사이에 잔돌을 박고 있었습니다. 봄내가 옆에 쭈그리고 앉아 한참 보다가 말했습니다."},{"t":"p","dlg":true,"html":"“어른, 거기 말고요.”"},{"t":"p","dlg":true,"html":"“뭐라고?”"},{"t":"p","dlg":true,"html":"“세 걸음 아래요. 아래가 밀리면 위는 그냥 따라 내려와요. 위만 막아 봐야 소용없어요.”"},{"t":"illust","n":1,"cap":"성벽 아래쪽 세 걸음 자리를 손가락으로 가리키는 아이","src":"img/web/ep043-plate-1.jpg?v=2d7655de67"},{"t":"p","dlg":false,"html":"덤불이 손을 멈추고 봄내를 보았습니다."},{"t":"p","dlg":true,"html":"“네가 그걸 어떻게 아느냐.”"},{"t":"p","dlg":true,"html":"“성 쌓는 데서 오래 있었어요. 성벽은 위에서부터 무너지지 않아요.”"},{"t":"p","dlg":false,"html":"덤불은 잠시 그대로 있다가 <em class=\"hint\">연장</em>을 챙겨 세 걸음 아래로 내려갔습니다. 그날부터 봄내는 덤불을 따라다녔습니다."},{"t":"p","dlg":false,"html":"안시성은 큰 성이 아니었습니다. 산줄기를 타고 앉은 성이라 둘레가 길지 않았고, 대신 성으로 오르는 길이 가팔랐습니다. 그리고 고구려 사람들이 성을 쌓을 때 흔히 하던 것이 이 성에도 있었습니다. 성벽을 곧게만 두르지 않고 군데군데를 바깥으로 네모나게 내밀어 쌓은 <em class=\"dot\">치</em>였습니다. 봄내가 아버지의 골짜기에서 날마다 보던 바로 그것이었습니다."},{"t":"p","dlg":true,"html":"“성벽에 딱 붙으면 위에서 안 보이잖아요.”"},{"t":"p","dlg":true,"html":"“저기서 보인다.” 덤불이 내민 자리를 턱으로 가리켰습니다. “치 밑에 붙은 놈은 위를 못 본다. 옆은 더 못 보고. 우리는 옆에서 다 보고.”"},{"t":"p","dlg":false,"html":"어느 저녁, 성벽 위를 한 사람이 천천히 걸었습니다. 걸음마다 멈춰 서서 아래를 내려다보았고, 사람들은 그가 지나갈 때마다 하던 일을 멈추고 고개를 숙였습니다."},{"t":"p","dlg":true,"html":"“저분은 누구예요?”"},{"t":"p","dlg":true,"html":"“<em class=\"dot\">성주</em>님이시다. 이 성의 군사도 사람도 다 저분이 맡으셨지.”"},{"t":"p","dlg":true,"html":"“성주님 이름이 뭐예요?”"},{"t":"p","dlg":false,"html":"덤불은 잔돌을 하나 골라 틈에 박았습니다."},{"t":"p","dlg":true,"html":"“성주님은 성주님이지.”"},{"t":"p","dlg":false,"html":"봄내는 더 묻지 않았습니다. 성 안 사람들에게 그는 이름보다 「성주님」이 먼저인 사람이었습니다."}]},{"heading":"예순 날","blocks":[{"t":"p","dlg":false,"html":"여름이 한창일 때 당의 군사가 성 앞 벌판에 닿았습니다."},{"t":"p","dlg":false,"html":"성을 에워싼 군사는 성 안에서 세다가 그만둘 만큼 많았습니다."},{"t":"p","dlg":true,"html":"“저렇게 큰 군대가 왜 이 작은 성 하나를 붙잡고 있어요?” 봄내가 물었습니다. “그냥 지나가면 되잖아요.”"},{"t":"p","dlg":true,"html":"“등 뒤에 성을 두고 가는 군대는 없다.” 덤불이 말했습니다. “저들이 지나가면 우리가 뒤에서 나가 길을 끊을 테니까. 이 성을 열어야 저들은 앞으로 갈 수 있다.”"},{"t":"p","dlg":false,"html":"첫날부터 벌판에 큰 나무 틀이 여럿 섰습니다. 당의 군사들은 그 <em class=\"dot\">포차</em>에 돌덩이를 얹어 성으로 날려 보냈습니다. 포차가 던진 돌이 성벽 위에 떨어지면 그 자리에 사람이 서 있을 수 없었습니다. 성 안 사람들은 나무를 엮어 성벽 위를 덮었습니다. 덮으면 부서졌고, 부서지면 밤에 다시 엮었습니다."},{"t":"p","dlg":false,"html":"공격은 하루에 한 번이 아니었습니다. 여섯 번이나 일곱 번씩 밀려왔습니다."},{"t":"p","dlg":false,"html":"그러던 어느 날, 성 동남쪽 벌판에서 흙이 오르기 시작했습니다."},{"t":"p","dlg":false,"html":"처음에는 무엇을 하는지 아무도 몰랐습니다. 사람들이 흙을 지고 와서 한자리에 부었고, 다음 날에도 부었고, 그다음 날에도 부었습니다."},{"t":"p","dlg":false,"html":"닷새째 되던 날 덤불이 성벽 위에서 그것을 내려다보다가 말했습니다."},{"t":"p","dlg":true,"html":"“산을 만드는구나.”"},{"t":"p","dlg":true,"html":"“산을요?”"},{"t":"p","dlg":true,"html":"“성보다 높은 산. 저기 올라서면 성 안이 다 내려다보이지. 거기서 활을 쏘고, 성벽 위로 건너오려는 게다.”"},{"t":"p","dlg":false,"html":"당의 군사는 밤에도 흙을 날랐습니다. 횃불이 줄지어 오르내리는 것이 성 안에서도 보였습니다."},{"t":"p","dlg":false,"html":"그러자 성 안에서도 성벽을 높이기 시작했습니다. 성 안 사람들은 흙산이 한 <em class=\"hint\">자</em> 오르면 성벽도 한 자 올렸습니다. 흙산이 성벽보다 높아지지 못하게 하려는 것이었습니다. 돌이 모자라면 집을 헐어 그 돌을 썼습니다. 봄내는 흙을 다지는 자리에 붙었습니다. 흙은 켜켜이 얇게 깔고 밟아 다지고 다시 깔아야 무너지지 않는다는 것을 봄내는 골짜기에서 보아 알고 있었습니다."},{"t":"spot","n":2,"size":"large","cap":"성 안에서는 흙을 얇게 깔고 다졌고, 성 밖에서는 흙산을 높이려고 계속 부었다","src":"img/web/ep043-spot-2.jpg?v=1faedd5eb5"},{"t":"p","dlg":true,"html":"“저쪽은 저렇게 안 해요.” 봄내가 말했습니다. “붓기만 해요.”"},{"t":"p","dlg":true,"html":"“급하니까.”"},{"t":"p","dlg":true,"html":"“급하면 무너져요.”"},{"t":"p","dlg":false,"html":"덤불은 대답하지 않았습니다. 그 말이 맞기를 바라는 얼굴이었지만, 바란다고 되는 일이 아니라는 것도 알고 있었습니다."},{"t":"p","dlg":false,"html":"흙산은 예순 날 만에 다 섰습니다. 성 안 사람들이 아무리 성벽을 올려도 따라잡을 수 없었습니다. 꼭대기가 성벽보다 높아서 거기 올라서면 성 안 마당까지 훤히 들여다보였습니다."},{"t":"illust","n":2,"cap":"성보다 높이 솟은 흙산과, 그만큼 높아진 성벽","src":"img/web/ep043-plate-2.jpg?v=95f8b906f3"},{"t":"p","dlg":false,"html":"그 예순 날 동안 성 안 사람들은 성 밖으로 나갈 수 없었습니다. 곡식은 줄었고 물은 아꼈고 다친 사람은 늘었습니다. 봄내는 낮에 흙을 다지고 밤에 나무를 엮었습니다. 눈을 감으면 돌이 성벽에 부딪는 소리가 그대로 들려왔습니다."},{"t":"p","dlg":false,"html":"당의 장수 하나가 군사를 데리고 흙산 꼭대기에 올라가 그 자리를 지켰습니다."},{"t":"p","dlg":false,"html":"그런데 그 산이 무너졌습니다."},{"t":"p","dlg":false,"html":"제 무게를 못 이기고 한쪽으로 쏟아져 내린 것입니다. 그 흙이 성벽 한 자락을 눌러 함께 무너뜨렸고, 성 안 사람들 수백 명이 무너진 자리로 쏟아져 나가 흙산을 차지했습니다."},{"t":"p","dlg":false,"html":"성벽이 무너진 것은 당의 군사가 예순 날 동안 바라 온 일이었습니다. 무너진 자리로 한꺼번에 밀고 들어왔다면 성은 그날 열렸을지도 모릅니다. 그런데 흙산 꼭대기를 지키던 장수가 하필 그때 제자리에 없었습니다. 군사들을 이끌고 밀고 들어올 사람이 없었던 것입니다."},{"t":"p","dlg":false,"html":"성 안 사람들은 산을 차지하고 그 둘레를 파서 도랑을 두르고 거기서 지켰습니다."},{"t":"p","dlg":false,"html":"예순 날 걸려 쌓은 산이 하루 만에 주인이 바뀐 것입니다. 성 안을 내려다보려고 쌓은 산 위에, 이제는 성 안 사람들이 서서 당의 진영을 내려다보았습니다."},{"t":"p","dlg":false,"html":"황제는 몹시 노했습니다. 흙산을 맡았던 장수를 벌하고, 사흘 동안 쉬지 않고 성을 쳤습니다. 사흘이 지나도 성은 열리지 않았습니다."}]},{"heading":"비단 백 필, 그리고 오백 년","blocks":[{"t":"p","dlg":false,"html":"가을이 왔습니다."},{"t":"p","dlg":false,"html":"요동의 가을은 짧고 겨울이 일찍 옵니다. 풀이 마르면 말이 먹을 것이 없고, 물이 얼면 배가 다니지 못합니다. 게다가 멀리서 실어 온 군량이 바닥을 보이고 있었습니다. 이대로 겨울을 맞으면 성을 에워싼 쪽이 먼저 굶고 얼 판이었습니다."},{"t":"p","dlg":false,"html":"그해 가을 어느 날, 황제는 군사를 돌리라고 명했습니다. <em class=\"dot\">회군</em>이었습니다."},{"t":"p","dlg":false,"html":"성 안에서는 아무도 나오지 않았습니다. 지난 몇 달 동안 그랬듯이 담 뒤에 엎드려 지켜보기만 했습니다. 덤불은 물러나는 척하다 되돌아오는 군대도 있다며 고개를 드는 봄내의 머리를 눌렀습니다."},{"t":"p","dlg":false,"html":"당의 군사가 물러나 벌판을 채우고 늘어섰을 때, 성벽 위로 사람 하나가 올라섰습니다."},{"t":"p","dlg":false,"html":"성주였습니다."},{"t":"p","dlg":false,"html":"그는 성 위에 서서 아래를 향해 절했습니다. 싸움을 걸지도 않았고 소리를 지르지도 않았습니다. 그저 떠나는 이에게 작별하듯 절을 하고 물러났습니다."},{"t":"illust","n":3,"cap":"군사가 물러가는 벌판을 향해 성벽 위에서 절하는 사람","src":"img/web/ep043-plate-3.jpg?v=f41a593836"},{"t":"p","dlg":false,"html":"황제는 그것을 보고 사람을 시켜 성으로 비단 백 <em class=\"hint\">필</em>을 보냈습니다. 성을 굳게 지킨 것을 <em class=\"hint\">가상히</em> 여긴다는 뜻이었습니다."},{"t":"p","dlg":false,"html":"봄내는 성문 안쪽에서 그 비단 꾸러미가 들어오는 것을 보았습니다."},{"t":"p","dlg":true,"html":"“어른, 저건 왜 주는 거예요? 우리랑 싸운 사람이잖아요.”"},{"t":"p","dlg":true,"html":"“저쪽이 졌으니까.” 덤불이 말했습니다. “이 성을 못 열고 돌아가는 게다. 그래도 황제가 졌다고 말할 수는 없으니, 제 임금을 끝까지 지킨 신하를 칭찬해 주고 간다는 말로 돌아가는 게지. 원수라도 잘 싸운 사람은 알아본다는 뜻도 있고.”"},{"t":"p","dlg":true,"html":"“이상해요.”"},{"t":"p","dlg":true,"html":"“이상하지.”"},{"t":"p","dlg":false,"html":"덤불이 한참 만에 덧붙였습니다."},{"t":"p","dlg":true,"html":"“저쪽도 오늘 일을 적을 것이다. 우리 성주님 이름도 적히겠지.”"},{"t":"p","dlg":false,"html":"봄내는 그 말을 오래 기억했습니다."},{"t":"p","dlg":false,"html":"그런데 적히지 않았습니다."},{"t":"p","dlg":false,"html":"오백 년이 지났습니다."},{"t":"p","dlg":false,"html":"고려의 한 사람이 임금의 명을 받아 세 나라의 역사를 한 벌로 묶는 일을 맡았습니다. 김부식이었습니다. 그는 남아 있는 옛 책을 다 모아 놓고 중국 쪽 기록까지 나란히 펴 놓고 읽었습니다. 그렇게 해서 묶인 책이 『삼국사기』입니다."},{"t":"p","dlg":false,"html":"안시성 대목에 이르렀을 때 그는 붓을 멈췄습니다."},{"t":"spot","n":3,"size":"normal","cap":"오백 년 뒤 김부식은 남은 옛 책과 중국 기록을 모아, 세 나라의 역사를 엮었다","src":"img/web/ep043-spot-3.jpg?v=1a08612f4c"},{"t":"p","dlg":false,"html":"황제의 이름은 남아 있었습니다. 당 태종입니다. 김부식이 보기에 그는 어지러운 세상을 거두었고 군사를 부리는 데에 지는 법이 없던 임금이었습니다. 그런 임금이 동쪽에 와서 끝내 못 연 성이 하나 있었으니, 그 성을 지킨 사람은 보통 사람이 아니었을 것입니다."},{"t":"p","dlg":false,"html":"그런데 그 사람의 이름이 어디에도 없었습니다. 옛 책들은 그를 「성주」라고만 적어 두었습니다."},{"t":"p","dlg":false,"html":"김부식은 그 대목 끝에 짧은 글을 하나 붙였습니다. 역사책을 쓴 사람이 사건을 다 적은 뒤 그 끝에 제 생각을 밝혀 적는 글, <em class=\"dot\">사론</em>이었습니다. 거기에 그는 이렇게 적었습니다. 역사가 그의 성과 이름을 잃어버렸으니 참으로 <em class=\"hint\">애석한</em> 일이라고요."},{"t":"p","dlg":false,"html":"이름이 남지 않는 일은 드물지 않았습니다. 세금 자루에 매달린 나무쪽에는 곡식을 보낸 사람의 이름이 또렷한데 그가 누구인지는 아무도 모릅니다. 신라의 옛 도읍에 남은 커다란 무덤들은 그 안에 무엇이 들었는지 다 보여 주면서 누가 누웠는지는 끝내 말하지 않고요. 안시성은 그 반대였습니다. 한 일이 이렇게 또렷이 남았는데 이름만 없습니다."},{"t":"p","dlg":false,"html":"빈자리는 오래 비어 있지 못했습니다."},{"t":"p","dlg":false,"html":"김부식이 붓을 놓고 사백 년쯤 더 지난 뒤, 사람들이 그 성주를 어떤 이름으로 부르기 시작했습니다. 그 이름은 우리 옛 기록에서 나온 것이 아니었습니다. 바다 건너에서 지어진 이야기책에 그런 이름이 있었고, 그것이 우리 쪽으로 넘어와 입에서 입으로 옮겨 다녔지요. 그 바다 건너는 서쪽, 곧 중국이었습니다. 처음 적어 둔 사람도 그저 이렇게 들었다고만 적었습니다."},{"t":"p","dlg":false,"html":"그래서 오늘날 역사책들은 대개 그를 「안시성 성주」라고만 부릅니다."},{"t":"p","dlg":false,"html":"봄내가 그 뒤 어떻게 되었는지는 알 수 없습니다. 덤불도, 성벽 위에서 절하던 사람도 마찬가지고요. 요동 어느 산줄기에 옛 성벽이 아직 남아 있지만, 그 성이 정말 안시성인지도 학자들은 아직 다투고 있습니다."},{"t":"p","dlg":false,"html":"이름도 모르고 자리도 확실하지 않은데, 그 성이 석 달 가까이 버텼다는 것만은 우리 책에도 저쪽 책에도 똑같이 적혀 있습니다."}]}],"words":[{"w":"요동","d":"랴오허강 동쪽 땅으로, 고구려가 서쪽에서 오는 군대를 처음 막던 곳"},{"w":"당","d":"618년에 세워져 삼백 년 가까이 이어진 중국의 나라"},{"w":"치","d":"성벽 바깥으로 네모나게 내밀어 쌓아, 성벽에 달라붙은 적을 옆에서 칠 수 있게 만든 자리"},{"w":"성주","d":"성을 맡아 지키는 우두머리"},{"w":"포차","d":"돌덩이를 얹어 멀리 날려 보내는 커다란 틀"},{"w":"회군","d":"군사를 돌려 돌아가는 것"},{"w":"사론","d":"역사책을 쓴 사람이 사건 끝에 제 생각을 밝혀 적은 짧은 글"}],"hints":[{"w":"조밭","d":"조를 기르는 밭. 조는 좁쌀이 열리는 곡식"},{"w":"연장","d":"일할 때 쓰는 도구"},{"w":"자","d":"길이를 재는 옛 단위. 한 자는 한 뼘 반쯤"},{"w":"필","d":"옷감을 세는 단위"},{"w":"가상히","d":"착하고 훌륭하게"},{"w":"애석한","d":"슬프고 아까운"}],"after":{"title":"뒷사람들이 붙인 이름","html":["빈 이름 자리는 아주 뒷날에 채워졌습니다. 중국 명나라 때 나온 이야기책 『당서지전통속연의』에 안시성 성주가 「양만춘」이라는 이름으로 나옵니다. 역사책이 아니라 사람들이 재미로 읽던 소설이었지요. 임진왜란 무렵 조선에 온 명나라 장수가 그 이름을 말했고, 그것을 들은 윤근수가 『월정만필』에 적어 두었습니다. 1669년에는 임금이 신하에게 그 이름의 내력을 물었다는 기록도 있고요. 그렇게 사백 년을 건너온 이름이 오늘 우리 귀에 익은 것입니다. 그런데 어느 기록도 그 이름이 처음 어디서 왔는지는 말해 주지 않습니다."]},"ifme":{"q":"아무도 모르는 빈자리에 누군가 이름을 하나 놓아 두었다면, 나는 그것을 어떻게 다루면 좋을까요?","html":["「모른다」는 말은 견디기 어렵습니다. 그래서 사람들은 빈자리를 자꾸 무언가로 채우지요. 안시성 성주에게 붙은 이름도 그렇게 생겼습니다. 그 이름을 아예 쓰지 말자고 하면 사람들이 오래 불러 온 것을 지우는 일이 되고, 그냥 쓰자고 하면 모르는 것을 아는 척하는 일이 됩니다. 나라면 그 사람을 무엇이라고 부를지, 그리고 그렇게 부를 때 무엇을 함께 말해 두어야 할지 이야기해 보세요. 정답은 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 옛 책에 이름과 사건이 적혀 있다는 뜻이에요. 『삼국사기』 고구려본기 보장왕 4년 조와 중국의 『자치통감』이 645년의 안시성 싸움을 나란히 적고 있습니다. 흙산을 예순 날 동안 쌓은 것도, 그 산이 무너져 고구려 쪽이 차지한 것도, 황제가 물러가며 비단 백 필을 보낸 것도 옛 책에 있는 그대로예요. 김부식이 사론에 「역사가 그 성과 이름을 잃었으니 참으로 애석하다」는 뜻을 적은 것도 사실이고요. 봄내와 덤불은 지어낸 사람이고, 두 사람이 나눈 말과 성벽을 고치는 장면도 지어낸 것입니다. 뒷날 사람들은 그 성주를 「양만춘」이라 부르기 시작했지만, 그 이름이 어디서 왔는지는 아직 아무도 밝히지 못했어요. 「그런 사람이 없었다」는 뜻이 아니라 「그의 이름을 모른다」는 뜻이랍니다."]},"quiz":[{"n":1,"kind":"사실 확인","q":"당의 군사가 예순 날에 걸쳐 쌓아 올린 흙산은 그 뒤 어떻게 되었나요?","opts":["성벽보다 낮아서 아무 소용이 없었습니다","무너지면서 성벽을 함께 무너뜨렸고, 성 안 사람들이 나가 그 산을 차지했습니다","성 안 사람들이 불을 질러 태워 없앴습니다","당의 군사가 스스로 허물어 버리고 물러났습니다"],"answer":1,"why":{"0":"흙산 꼭대기는 성벽보다 높아서 성 안 마당까지 들여다보였습니다.","2":"흙을 쌓아 올린 산이라 불로 태울 수 있는 것이 아니었습니다.","3":"흙산은 제 무게를 못 이기고 저절로 무너진 것입니다."},"ref":"그 흙이 성벽 한 자락을 눌러 함께 무너뜨렸고, 성 안 사람들 수백 명이 무너진 자리로 쏟아져 나가 흙산을 차지했습니다.","more":"『자치통감』은 이 흙산을 두고 <b>「밤낮으로 쉬지 않았으니 무릇 예순 날이요, 들인 품이 오십만이었다」</b>라고 적어요. 「오십만」은 한 사람이 하루 일한 것을 하나로 세어 모두 더한 수랍니다. 흙산 꼭대기가 성에서 몇 길 떨어져 성 안을 내려다볼 수 있었다는 것도 같은 책에 있어요. 국사편찬위원회 우리역사넷도 이 대목을 <b>「연인원 50만 명을 동원하여 60여 일 걸려서 흙으로 높은 산을 쌓고」</b>라고 풀이합니다."},{"n":2,"kind":"사실 확인","q":"황제가 군사를 돌리던 날, 성주는 무엇을 했고 황제는 성으로 무엇을 보냈나요?","opts":["성주가 성문을 열고 나와 항복했고, 황제는 그를 데리고 돌아갔습니다","성주가 아무것도 하지 않았고, 황제도 아무것도 남기지 않았습니다","성주가 황제에게 화살을 쏘았고, 황제는 성을 다시 쳤습니다","성주가 성벽 위에 올라 절을 했고, 황제는 성으로 비단 백 필을 보냈습니다"],"answer":3,"why":{"0":"성문은 끝내 열리지 않았고 성 안에서는 아무도 나오지 않았습니다.","1":"황제는 성을 굳게 지킨 것을 가상히 여겨 성으로 비단을 보냈습니다.","2":"성주는 싸움을 걸지도 않았고 소리를 지르지도 않았습니다."},"ref":"황제는 그것을 보고 사람을 시켜 성으로 비단 백 필을 보냈습니다.","more":"『자치통감』의 이 대목은 <b>「성주가 성에 올라 절하여 작별하니, 황제가 그가 굳게 지킨 것을 가상히 여겨 비단 백 필을 주어 임금 섬김을 격려했다」</b>입니다. 그런데 우리에게 널리 알려진 이야기는 조금 달라요. 성주가 쏜 화살에 황제가 눈을 다쳤다는 이야기지요. <b>그 이야기는 『삼국사기』에도 『자치통감』에도 없습니다.</b> 훨씬 뒷날인 고려 말에 이색이 지은 시에 처음 자취가 보이고, 조선 후기에 박지원이 『열하일기』에 세상에 그렇게 전한다며 옮겨 적었어요. 그러니 사실로 말하기는 어렵답니다."},{"n":3,"kind":"추론","q":"성 안 사람들이 예순 날 동안 한 일과, 흙산이 무너지던 날 벌어진 일을 이어 보면 안시성이 버틴 까닭에 대해 무엇을 짐작할 수 있을까요?","opts":["성 안에 곡식과 물이 넉넉해서 견디기 어렵지 않았다는 뜻입니다","당의 군사가 처음부터 싸울 마음이 없었다는 뜻입니다","성을 지킨 것은 성주 한 사람의 재주가 아니라 성 안 사람들이 오래 함께 해낸 일이었다는 뜻입니다","성벽이 워낙 높고 튼튼해서 처음부터 손댈 수 없는 성이었다는 뜻입니다"],"answer":2,"why":{"0":"곡식은 줄었고 물은 아꼈고 다친 사람은 늘었습니다.","1":"공격은 하루에 여섯 번이나 일곱 번씩 밀려왔습니다.","3":"안시성은 둘레가 길지 않은 작은 성이었고, 그 성벽마저 흙산에 눌려 한 번 무너졌습니다."},"ref":"성 안 사람들은 흙산이 한 자 오르면 성벽도 한 자 올렸습니다.","more":"옛 기록도 이 편의 이야기처럼 성주 한 사람만 그리지 않아요. 『자치통감』은 흙산을 쌓는 동안 <b>「성 안에서도 또한 그 성을 높여 맞섰다」</b>고 적고, 흙산이 무너진 뒤에는 <b>「고구려 군사 수백 명이 무너진 성터로 나와 싸워 마침내 흙산을 빼앗고 도랑을 파서 지켰다」</b>고 적습니다. 성주가 아니라 「성 안」과 「군사 수백 명」이 주어인 문장이지요. 안시성 싸움이 어떤 한 사람의 이야기가 아니라는 것을 옛 책이 이미 그렇게 적어 둔 셈이에요."},{"n":4,"kind":"낱말·표현","q":"이 이야기에서 '사론'은 무엇을 가리키는 말인가요?","opts":["역사책을 쓴 사람이 사건 끝에 제 생각을 밝혀 적은 짧은 글입니다","성을 맡아 지키는 우두머리를 이르는 말입니다","군사를 돌려 돌아가는 것을 이르는 말입니다","돌덩이를 얹어 멀리 날려 보내는 커다란 틀입니다"],"answer":0,"why":{"1":"그것은 본문에서 성주라고 부른 것입니다.","2":"그것은 본문에서 회군이라고 부른 것입니다.","3":"그것은 본문에서 포차라고 부른 것입니다."},"ref":"역사책을 쓴 사람이 사건을 다 적은 뒤 그 끝에 제 생각을 밝혀 적는 글, 사론이었습니다.","more":"『삼국사기』에는 이런 글이 서른 편 남짓 실려 있어요. 「논하여 말한다(論曰)」로 시작해서 사건을 평하지요. 안시성 대목의 사론에서 김부식은 이름을 잃은 성주를 두고, 옛 중국 학자가 <b>「제나라와 노나라의 큰 신하들도 역사가 그 이름을 잃었다」</b>고 한탄한 것과 다를 바 없다고 적었습니다. 이름이 사라지는 일이 우리에게만 있었던 것이 아니라는 뜻이었지요."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 김부식이 남긴 이 사론 한 대목이 오늘 우리에게 특별히 값진 까닭은 무엇일까요?","opts":["그 사론 덕분에 안시성이 어디에 있던 성인지 확실해졌기 때문입니다","그 일이 있고 오백 년 뒤의 사람도 이미 그 이름을 몰랐다는 것을 알려 주기 때문입니다","그 사론에 안시성 성주의 이름이 또렷이 적혀 있기 때문입니다","김부식이 안시성 싸움을 직접 보고 적은 글이기 때문입니다"],"answer":1,"why":{"0":"그 성이 정말 안시성인지도 학자들은 아직 다투고 있습니다.","2":"김부식은 그 이름을 끝내 찾지 못해 애석하다고 적었습니다.","3":"김부식은 그 싸움이 있고 오백 년이나 지난 뒤의 사람입니다."},"ref":"그런데 그 사람의 이름이 어디에도 없었습니다.","more":"이런 자리를 역사에서는 아주 값지게 봅니다. 「기록이 없다」와 「기록이 없다고 적힌 기록이 있다」는 다르거든요. 뒤엣것은 <b>언제부터 몰랐는지</b>를 알려 주니까요. 김부식의 사론 덕분에 우리는 늦어도 1145년에는 그 이름이 이미 사라져 있었다는 것을 압니다. 그래서 그 뒤에 나타난 이름은 <b>다시 찾아낸 이름이 아니라 새로 생긴 이름</b>으로 보아야 한다는 판단이 서지요. 사백 년 뒤에 나온 이름을 학자들이 조심스러워하는 까닭이 여기에 있습니다."}],"summary":["645년, 당의 황제가 몸소 군사를 이끌고 쳐들어와 고구려의 큰 성들을 차례로 열었지만 안시성 하나만은 끝내 열지 못했어요.","당의 군사가 예순 날에 걸쳐 성보다 높은 흙산을 쌓았는데, 그 산이 무너지며 성벽을 함께 무너뜨렸고 성 안 사람들이 나가 그 산을 차지했어요.","황제는 물러가면서 성주에게 비단 백 필을 보냈지만 그 성주의 이름은 어느 기록에도 남지 않았고, 오백 년 뒤의 김부식도 이미 그 이름을 몰랐어요."],"bait":["황제는 돌아갔고 고구려는 북쪽에서 버텼습니다. 그런데 남쪽에서는 그보다 세 해 앞서 다른 일이 벌어지고 있었지요. 백제가 신라의 성 마흔 곳을 빼앗고 대야성을 무너뜨립니다. 그 성에서 <span class=\"blur\">한 사람의 딸과 사위</span>가 죽었습니다. 그 소식을 들은 사람은 무엇을 결심했을까요……"]};

;
(window.EPS ||= {})[44] = {"no":44,"chapter":"2장 세 나라의 시대","when":"642년","read":"읽기 15~17분","ago":"약 1,380년 전","title":"딸을 잃은 아버지는 무엇을 결심했을까","subtitle":"그날 대야성에서 빼앗긴 것은 성 하나만이 아니었습니다","intro":"오늘 이야기의 무대는 <b>신라</b>예요. 이 무렵 세 나라는 백 년 가까이 서로 등을 돌린 채 싸우고 있었어요. 북쪽에서 고구려가 당의 황제를 막아 내는 동안, 남쪽에서는 백제가 신라를 세게 밀어붙였지요. 642년, 백제 군사가 신라의 서쪽 성 마흔 곳을 빼앗고 <b>대야성</b>까지 무너뜨립니다. 그 성에서 한 사람의 딸과 사위가 죽었어요. 딸을 잃은 그 아버지는 무엇을 결심했을까요? 그 성에서 살아 나온 아이를 따라가며 알아볼까요?","acts":[{"heading":"성문 안의 원한","blocks":[{"t":"p","dlg":false,"html":"낙동강 서쪽, 산과 산 사이에 대야성이 있었습니다."},{"t":"p","dlg":false,"html":"신라가 서쪽을 지키려고 쌓은 성이었습니다. 이 성을 넘어서면 도읍 서라벌까지 앞을 막아설 큰 성이 없었습니다. 그래서 신라는 이 성에 늘 높은 <em class=\"hint\">벼슬아치</em>를 보냈습니다."},{"t":"p","dlg":false,"html":"북쪽에서 고구려가 당의 황제를 물리치기 세 해 전이었습니다. 남쪽에서는 이미 다른 일이 벌어지고 있었습니다."},{"t":"p","dlg":false,"html":"642년, 그 성을 맡은 <em class=\"dot\">도독</em>은 김품석이었습니다. 성의 군사도 고을의 살림도 모두 그가 맡았습니다. 도독은 서라벌에서 왔습니다. 함께 온 부인은 고타소라 했고, 고타소의 아버지는 서라벌에서 손꼽히는 사람이었습니다. 김춘추라는 이름이었지요."},{"t":"p","dlg":false,"html":"가온은 그해 열 살이었습니다. 어머니를 따라 성 안 <em class=\"hint\">곳간</em>에서 일했습니다. 곡식 자루를 세고 옮기고, 쥐가 파먹은 자루를 골라내는 일이었습니다."},{"t":"p","dlg":false,"html":"여름이 되자 서쪽에서 사람들이 들어오기 시작했습니다."},{"t":"p","dlg":false,"html":"백제 군사가 신라의 서쪽 성을 차례로 빼앗고 있었습니다. 옛 책은 그해 가을 첫 달에 마흔 곳이 넘는 성이 넘어갔다고 적었습니다. 앞장선 것은 백제의 임금이었습니다. 성을 잃은 사람들이 짐을 이고 지고 대야성으로 밀려들었고, 먹을 입이 늘어난 만큼 곳간은 빠르게 줄었습니다."},{"t":"spot","n":1,"size":"large","cap":"성을 잃은 사람들이 대야성으로 몰려들자, 먹을 입이 늘어 곳간의 곡식이 줄었다","src":"img/web/ep044-spot-1.jpg?v=65f6b6d843"},{"t":"p","dlg":false,"html":"가온은 자루를 세면서 어른들의 말을 들었습니다. 낮에는 백제 이야기를 했고, 밤에는 목소리를 낮추어 성안의 다른 이야기를 했습니다."},{"t":"p","dlg":false,"html":"성안에 아내를 빼앗긴 사람이 하나 있었습니다."},{"t":"p","dlg":false,"html":"빼앗은 사람은 도독이었습니다. 도독 곁에서 일을 돕던 벼슬아치였는데, 그 아내가 곱다는 말을 듣고 도독이 데려갔다고 했습니다. 옛 책은 이 일을 아주 짧게 적어 두었습니다. 보고서 빼앗았다고요. 그 사람은 그것을 원망했습니다. 그러나 성에서 가장 높은 사람이 한 일이라, 그 원망을 입 밖에 낼 곳이 없었습니다."},{"t":"p","dlg":false,"html":"가온은 그 사람을 알았습니다. 곳간 앞에서 몇 번 마주쳤는데 인사를 해도 대답이 없었습니다."},{"t":"p","dlg":true,"html":"“저 아저씨는 왜 사람을 안 봐요?”"},{"t":"p","dlg":false,"html":"어머니는 가온의 입을 막았습니다. 그런 말은 도독의 귀에 들어가면 안 되는 말이었습니다."},{"t":"p","dlg":false,"html":"성에는 소식을 나르는 사람도 있었습니다. 하늬였습니다. 성과 성 사이를 오가며 말을 전하는 일을 했고, 골짜기와 <em class=\"hint\">등성이</em>의 좁은 길을 훤히 알았습니다. 그해 여름 하늬가 가져오는 소식은 하나같이 나빴습니다."},{"t":"p","dlg":false,"html":"가을 둘째 달, 백제 군사가 골짜기를 메웠습니다. 옛 책은 그 수를 일만이라고 적었습니다. 성문을 닫아건 대야성은 곳간의 곡식으로 버텨야 했습니다."},{"t":"p","dlg":false,"html":"닷새째 되던 밤에 곳간에 불이 났습니다."},{"t":"p","dlg":false,"html":"가온은 그 불을 보았습니다. 불길이 마른 자루를 타고 넘어가는 것이 물이 흐르는 것 같았습니다. 사람들이 물동이를 이어 나르다가 그만두었습니다. 곡식은 벌써 없었습니다."},{"t":"illust","n":1,"cap":"한밤중에 곡식 곳간이 타는 대야성","src":"img/web/ep044-plate-1.jpg?v=2bb4daf2cf"},{"t":"p","dlg":false,"html":"불을 놓은 사람은 도독에게 아내를 빼앗긴 바로 그 사람이었습니다."},{"t":"p","dlg":false,"html":"그는 성 밖의 백제 군사와 이미 말을 맞추어 두고 있었습니다. 성안에 있으면서 밖의 적과 몰래 손을 잡았으니, 옛 책은 그가 <em class=\"dot\">내응</em>이 되었다고 적었습니다."},{"t":"p","dlg":false,"html":"곡식이 타자 성안 사람들은 겁을 먹었습니다. 먹을 것이 없으면 성벽이 아무리 튼튼해도 오래 버틸 수 없습니다. 도독은 그날 밤 하늬를 불러 서라벌에 <em class=\"dot\">원병</em>을 청하는 <em class=\"hint\">전갈</em>을 들려 보냈습니다."},{"t":"p","dlg":false,"html":"하늬가 뒷문으로 나가려 할 때 어머니가 가온의 등을 밀었습니다."},{"t":"p","dlg":true,"html":"“따라가라.”"},{"t":"p","dlg":true,"html":"“엄마는요?”"},{"t":"p","dlg":true,"html":"“따라가라니까. 여기 있으면 너도 어찌 될지 모른다.”"}]},{"heading":"대나무는 부러져도","blocks":[{"t":"p","dlg":false,"html":"둘은 밤새 걸었습니다."},{"t":"p","dlg":false,"html":"하늬는 앞서 걸으며 자꾸 뒤를 돌아보았습니다. 가온이 따라오는지 보는 것이 아니라, 성이 아직 거기 있는지 보는 것이었습니다."},{"t":"p","dlg":false,"html":"이튿날 낮에 등성이 하나를 넘고 나서 하늬가 멈춰 섰습니다. 가온도 따라 돌아보았습니다. 산 너머에서 연기가 한 줄 올라오고 있었습니다. 하늬는 아무 말도 하지 않았지만, 가온은 그것이 대야성 쪽이라는 것을 알았습니다."},{"t":"illust","n":2,"cap":"산등성이에서 뒤를 돌아보는 두 사람","src":"img/web/ep044-plate-2.jpg?v=b7d4d42477"},{"t":"p","dlg":false,"html":"성이 열린 뒤에 그 안에서 무슨 일이 있었는지, 두 사람은 한참 뒤에야 들었습니다. 오늘 우리가 아는 것도 그 성에서 살아 나온 사람들의 말을 옛 책이 받아 적은 것입니다."},{"t":"p","dlg":false,"html":"곳간이 타 버리자 성안 사람들은 오래 버틸 수 없다고 여겼습니다."},{"t":"p","dlg":false,"html":"도독을 돕던 벼슬아치 하나가 성벽에 올라 백제 장군을 불러 <em class=\"dot\">항복</em>하겠다고 했습니다."},{"t":"p","dlg":true,"html":"“우리를 죽이지 않겠다면 성을 내어 드리겠소.”"},{"t":"p","dlg":false,"html":"백제 장군이 대답했습니다."},{"t":"p","dlg":true,"html":"“그리하지 않는다면 저 해를 두고 맹세하리다.”"},{"t":"p","dlg":false,"html":"그때 막아선 사람이 있었습니다. 죽죽이었습니다."},{"t":"p","dlg":false,"html":"죽죽은 <em class=\"hint\">대야주</em> 사람이었습니다. 서라벌에서 내려온 벼슬아치가 아니라 그 골짜기에서 나고 자란 사람이었고, 아버지가 지어 준 이름을 그대로 쓰고 있었습니다."},{"t":"p","dlg":true,"html":"“말이 답니다.” 죽죽이 말했습니다. “듣기 좋은 말로 우리를 꾀는 것입니다. 성을 나가면 붙들립니다.”"},{"t":"p","dlg":false,"html":"도독은 듣지 않았습니다. 성문이 열렸습니다."},{"t":"p","dlg":false,"html":"먼저 나간 군사들은 돌아오지 못했습니다. 성 밖에 숨어 있던 백제 군사들이 일어나 그들을 덮쳤습니다. 죽죽의 말대로였습니다."},{"t":"p","dlg":false,"html":"그날 도독과 그 부인도 그 성에서 죽었습니다. 성문이 열린 뒤에 무슨 일이 있었는지는 옛 책마다 다르게 적혀 있습니다."},{"t":"p","dlg":false,"html":"죽죽은 남은 군사를 모아 성문을 다시 닫았습니다. 문을 열자고 한 사람도 열지 말자고 한 사람도 같은 성 안에 있었고, 이제 남은 것은 열지 말자고 한 사람들이었습니다."},{"t":"spot","n":2,"size":"normal","cap":"죽죽은 남은 군사를 모아 열린 성문을 다시 닫고, 성 안에서 끝까지 버티려 했다","src":"img/web/ep044-spot-2.jpg?v=57d0fdd36c"},{"t":"p","dlg":false,"html":"곁에 있던 사람이 말했습니다."},{"t":"p","dlg":true,"html":"“이래서는 온전할 수 없소. 살아서 항복했다가 뒷날을 <em class=\"hint\">도모하는</em> 편이 낫지 않겠소.”"},{"t":"p","dlg":false,"html":"죽죽이 대답했습니다."},{"t":"p","dlg":true,"html":"“그대의 말이 옳소. 그러나 내 아버지가 나를 죽죽이라 이름 지은 것은, 추운 겨울에도 시들지 말고 꺾일지언정 굽지 말라는 뜻이었소. 어찌 죽는 것이 두려워 살아서 항복하겠소.”"},{"t":"p","dlg":false,"html":"죽죽의 이름에 든 「죽」은 대나무를 뜻하는 글자였습니다. 대나무는 한겨울에도 잎이 푸르고, 부러질지언정 휘어지지 않습니다. 그 이름대로 살겠다는 것, 그것이 죽죽이 끝까지 지키려 한 <em class=\"dot\">절개</em>였습니다."},{"t":"p","dlg":false,"html":"죽죽은 성이 무너질 때까지 싸우다 그 자리에서 죽었습니다. 곁에서 함께 싸운 사람도 그러했습니다. 뒷날 임금은 그 소식을 듣고 슬퍼하며 죽죽에게 벼슬을 내리고 그 집안 사람들을 도읍으로 옮겨 살게 했습니다."},{"t":"p","dlg":false,"html":"성안에 남은 사람들은 붙들려 백제 땅으로 갔습니다. 옛 책은 남녀 천여 명이라 적었고, 그들을 나라 서쪽 여러 고을에 나누어 살게 했다고 적었습니다. 그다음에 그 사람들이 어떻게 되었는지는 한 줄도 적혀 있지 않습니다."},{"t":"p","dlg":false,"html":"가온의 어머니가 그 안에 있었는지 없었는지도 아무도 모릅니다."},{"t":"p","dlg":false,"html":"백제에게도 갚을 것이 있었습니다."},{"t":"p","dlg":false,"html":"여든여덟 해 전, 백제의 임금이 신라 땅에서 죽었습니다. 그 임금이 성왕입니다. 백 년 넘게 함께 고구려를 막아 온 두 나라가 한강을 두고 갈라선 뒤의 일이었지요. 그 뒤로 백제와 신라는 다시 손을 잡지 않았습니다. 백제 사람들에게 그것은 잊을 수 없는 일이었고, 그해 가을에 군사를 몰고 서쪽 성들을 빼앗은 것도 백제의 임금 자신이었습니다."}]},{"heading":"기둥에 기대선 사람","blocks":[{"t":"p","dlg":false,"html":"하늬와 가온이 서라벌에 닿았을 때, 원병은 이미 소용이 없었습니다. 도우러 갈 성이 벌써 무너지고 없었기 때문입니다."},{"t":"p","dlg":false,"html":"서라벌은 컸습니다. 가온은 기와지붕이 그렇게 멀리까지 이어진 것을 처음 보았습니다. 골목마다 사람이 다녔고 저잣거리에서는 장사꾼이 소리를 질렀습니다. 성 하나가 무너진 것을 아무도 모르는 것 같았습니다."},{"t":"p","dlg":true,"html":"“여기 사람들은 아직 몰라.” 하늬가 말했습니다."},{"t":"p","dlg":false,"html":"그날 저녁에는 알게 되었습니다."},{"t":"p","dlg":false,"html":"하늬가 도독의 전갈과 함께, 곳간이 타던 밤과 산 너머의 연기를 전했기 때문입니다. 뒤이어 성이 무너졌다는 소식도 닿았습니다. 소식은 그렇게 도읍에 퍼졌습니다."},{"t":"p","dlg":false,"html":"그리고 같은 소식이 성 안쪽의 한 집에도 닿았습니다. 도독의 부인, 고타소의 아버지가 사는 집이었습니다."},{"t":"p","dlg":false,"html":"김춘추는 마당을 지나다가 그 말을 들었습니다."},{"t":"p","dlg":false,"html":"그는 온종일 기둥에 기대어 선 채로, 앞을 지나가는 사람도 알아보지 못했습니다."},{"t":"p","dlg":false,"html":"가온은 그 집 문간에 앉아 그것을 보았습니다. 사람들이 드나들며 그 앞에서 몸을 굽혔지만 그는 아무에게도 대답하지 않았습니다. 해가 담을 넘어가고 마당 그림자가 길어지고 다시 짧아지도록 그 자리였습니다."},{"t":"illust","n":3,"cap":"기둥에 기대어 온종일 서 있는 사람과 문간에 앉은 아이","src":"img/web/ep044-plate-3.jpg?v=f7af7401c2"},{"t":"p","dlg":false,"html":"가온은 그때 그 사람이 누구인지 몰랐습니다. 다만 저렇게 오래 서 있는 사람은 처음 보았습니다. 딸을 잃은 사람이라는 것은 나중에야 들었습니다."},{"t":"p","dlg":false,"html":"해가 기울 무렵 그가 입을 열었습니다."},{"t":"p","dlg":true,"html":"“아아. 사내대장부가 어찌 백제 하나를 삼키지 못하겠는가.”"},{"t":"p","dlg":false,"html":"가온이 듣기에 그것은 울음 대신 나온 말 같았습니다. 반드시 백제를 꺾고 말겠다는 말이었습니다."},{"t":"p","dlg":false,"html":"그러고는 임금 앞으로 나아갔습니다. 그때 신라를 다스리던 이는 이 땅의 첫 여자 임금이었습니다."},{"t":"p","dlg":true,"html":"“고구려에 <em class=\"dot\">사신</em>으로 보내 주십시오. 군사를 빌려 백제에 <em class=\"dot\">원수</em>를 갚겠습니다.”"},{"t":"p","dlg":false,"html":"임금은 그것을 허락했습니다."},{"t":"p","dlg":false,"html":"그는 군사를 모으지 않았습니다."},{"t":"p","dlg":false,"html":"신라는 서쪽에서 성 마흔 곳을 잃었고, 대야성까지 열리자 서라벌로 오는 길목이 뚫렸습니다. 남은 성들은 저마다 제 성을 지키기에도 벅찼습니다."},{"t":"p","dlg":false,"html":"그리고 고구려는 신라가 오래 싸워 온 나라였습니다. 두 나라는 백 년 가까이 국경에서 서로 성을 빼앗았습니다. 그 나라에 제 발로 걸어 들어가 군사를 꾸어 달라고 하겠다는 것이었습니다."},{"t":"p","dlg":false,"html":"그 이야기를 들은 하늬가 혀를 찼습니다."},{"t":"p","dlg":true,"html":"“원수의 나라에 혼자 들어가서 군사를 꾸어 달라니. 거기서 붙들리기라도 하면 어쩌려고.”"},{"t":"p","dlg":false,"html":"그해 겨울, 그는 북쪽으로 떠났습니다."},{"t":"spot","n":3,"size":"normal","cut":true,"width":640,"height":800,"cap":"김춘추는 백제를 꺾을 군사를 빌리려고, 그해 겨울 고구려로 길을 떠났다","src":"img/web/ep044-spot-3.png?v=9e84ca89d6"},{"t":"p","dlg":false,"html":"떠나기 전에 그는 딸의 이름을 입에 올리지 않았습니다. 옛 책도 딸이 남편을 따라 그 성에서 죽었다고 적은 뒤, 곧바로 그 아버지가 기둥에 기대어 서 있었다는 것과 무엇을 하려 했는지를 적었습니다."},{"t":"p","dlg":false,"html":"가온은 서라벌에 남았습니다."},{"t":"p","dlg":false,"html":"겨울이 되자 하늬가 다시 길을 떠나며 말했습니다."},{"t":"p","dlg":true,"html":"“너, 성을 무너지게 한 게 누군지 알지.”"},{"t":"p","dlg":false,"html":"가온은 대답하지 않았습니다. 알고 있었습니다. 곳간에 불을 놓은 것은 성안 사람이었지요. 아내를 빼앗겨 원한이 맺힌 사람이었고, 그 앞에서 어른들이 목소리를 낮추던 그 사람이었습니다. 성을 무너뜨린 것이 백제 군사만은 아니라는 것을 가온도 알았습니다."},{"t":"p","dlg":false,"html":"그런데 가온이 밤마다 떠올리는 얼굴은 그 사람이 아니었습니다. 골짜기를 메운 횃불이었습니다. 가온의 미움은 자꾸만 그 횃불 쪽으로만 갔습니다."},{"t":"p","dlg":false,"html":"가온은 그 겨울을 서라벌에서 났습니다. 그리고 그 뒤로 여러 해 동안, 백제라는 말을 들으면 다른 생각을 하지 못하는 사람으로 자랐습니다."}]}],"words":[{"w":"도독","d":"한 고을의 군사와 정치를 함께 맡아 다스리던 벼슬"},{"w":"내응","d":"성안에 있으면서 밖의 적과 몰래 손을 잡는 일"},{"w":"원병","d":"어려움에 빠진 편을 도우러 오는 군사"},{"w":"항복","d":"싸움에 진 쪽이 이긴 쪽에게 굽히고 따르겠다고 하는 것"},{"w":"절개","d":"어떤 어려움에도 뜻을 굽히지 않는 곧은 마음"},{"w":"사신","d":"나라를 대신해 다른 나라에 가서 말을 전하고 일을 맺는 사람"},{"w":"원수","d":"자기에게 큰 해를 입혀 깊은 원한이 맺힌 상대"}],"hints":[{"w":"벼슬아치","d":"나라의 벼슬을 하는 사람"},{"w":"곳간","d":"곡식이나 물건을 넣어 두는 곳"},{"w":"등성이","d":"산의 등줄기"},{"w":"전갈","d":"사람을 시켜 전하는 말이나 소식"},{"w":"대야주","d":"대야성을 중심으로 한 고을. 오늘날의 합천 일대"},{"w":"도모하는","d":"어떤 일을 이루려고 꾀하는"}],"after":{"title":"산 사람 여덟과 죽은 사람 둘","html":["여섯 해 뒤인 648년, 신라의 한 장군이 대야성 아래까지 밀고 내려가 백제 장수 여덟 사람을 사로잡았습니다. 그리고 백제에 사람을 보내 이렇게 전하게 했습니다. 우리 도독 부부의 뼈가 그대의 나라 땅에 묻혀 있소. 지금 그대의 장수 여덟이 내 손에 있으니, 죽은 뼈와 산 사람을 바꾸는 것이 어떻겠소. 백제는 그 말을 받아들였습니다. 두 사람의 뼈가 신라로 돌아왔고 여덟 사람은 살아서 제 나라로 돌아갔습니다. 성이 무너진 지 여섯 해 만이었습니다."]},"ifme":{"q":"가장 소중한 것을 잃었을 때, 나는 그 마음을 어디에 쓰게 될까요?","html":["김춘추는 군사를 모아 곧장 쳐들어가는 대신 원수의 나라에 혼자 걸어 들어가는 쪽을 골랐습니다. 어느 쪽이 옳았는지를 이 이야기가 정해 주지는 않습니다. 다만 슬픔은 사람을 반드시 어딘가로 데려간다는 것, 그리고 그 힘이 어디로 향하느냐에 따라 다음에 벌어지는 일이 아주 달라진다는 것은 분명하지요. 크게 속상했던 날, 나는 그 마음을 무엇에 썼는지 떠올려 보세요. 이 질문에는 정답이 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기는 <b>기록</b>입니다. 『삼국사기』 신라본기 선덕왕 11년 조에 백제가 신라의 서쪽 성 마흔 곳을 빼앗은 일과, 백제 장군이 대야성을 쳐서 함락하고 도독 품석이 죽은 일이 적혀 있어요. 김유신 열전에는 김춘추의 딸 고타소가 남편을 따라 그 성에서 죽었다는 것과, 김춘추가 그 소식을 듣고 온종일 기둥에 기대어 서 있었다는 대목이 있고요. 죽죽 열전에는 성이 왜 열렸는지와 죽죽이 남긴 말이 그대로 실려 있고, 그가 대야주 사람이었다는 것도 거기 적혀 있어요. 다만 성문이 열린 뒤에 무슨 일이 있었는지는 우리 옛 책 안에서도 두 가지로 갈려서, 이 이야기에서는 두 사람이 그 성에서 죽었다는 데까지만 적었어요. 가온과 하늬는 지어낸 사람이에요. 그 성에서 살아 나온 아이의 이름은 어디에도 남아 있지 않으니까요."]},"quiz":[{"n":1,"kind":"사실 확인","q":"대야성의 곳간에 불이 난 까닭은 무엇이었나요?","opts":["백제 군사가 성 밖에서 불화살을 쏘아 넣었기 때문입니다","가문 날씨에 마른 짚에 저절로 불이 붙었기 때문입니다","도독에게 아내를 빼앗긴 사람이 성안에서 불을 놓았기 때문입니다","곳간을 지키던 아이가 등불을 넘어뜨렸기 때문입니다"],"answer":2,"why":{"0":"그날 백제 군사는 골짜기에 있었고, 불은 성 안쪽에서 시작되었습니다.","1":"저절로 붙은 불이었다면 그 사람이 성 밖의 군사와 말을 맞추어 둘 까닭이 없습니다.","3":"가온은 불을 보았을 뿐이고, 옛 책도 불을 놓은 사람을 따로 적어 두었습니다."},"ref":"불을 놓은 사람은 도독에게 아내를 빼앗긴 바로 그 사람이었습니다.","more":"『삼국사기』 죽죽 열전은 이 일을 사건보다 먼저 적어 둡니다. <b>「이보다 앞서 도독 품석이 막객인 사지 검일의 아내가 아름다운 것을 보고 빼앗았다. 검일이 이를 원망했다(先是 都督品釋見幕客舍知黔日之妻有色 奪之 黔日恨之)」</b>. 그러고 나서 성이 공격받자 그가 안에서 호응해 창고를 불태웠고, 그래서 성안이 두려움에 빠져 지킬 수 없게 되었다고 이어집니다. 열여덟 해 뒤 백제가 무너졌을 때 신라는 그를 붙잡아 그 죄를 물었어요. 옛 책은 그 사람의 이름과 함께 <b>그가 왜 그랬는지도 같이 남겨 두었습니다.</b>"},{"n":2,"kind":"사실 확인","q":"딸과 사위가 죽었다는 소식을 들은 김춘추는 그날 어떻게 했나요?","opts":["대야성으로 달려가 무너진 성벽을 다시 쌓았습니다","임금에게 벼슬을 내놓겠다고 아뢰었습니다","그 자리에서 군사를 모아 곧바로 백제로 쳐들어갔습니다","온종일 기둥에 기대어 선 채로 앞을 지나가는 사람도 알아보지 못했습니다"],"answer":3,"why":{"0":"대야성은 이미 백제의 손에 있었고 그가 간 곳은 임금 앞이었습니다.","1":"그가 임금에게 청한 것은 벼슬을 내놓는 일이 아니라 고구려로 보내 달라는 것이었습니다.","2":"그는 군사를 모으지 않았습니다. 그것이 이 편의 가장 중요한 대목입니다."},"ref":"그는 온종일 기둥에 기대어 선 채로, 앞을 지나가는 사람도 알아보지 못했습니다.","more":"『삼국사기』 김유신 열전의 원문은 이렇습니다. <b>「춘추공이 그것을 듣고 기둥에 기대어 서서 온종일 눈을 깜박이지 않았고, 사람이나 물건이 앞을 지나가도 알아보지 못했다(春秋公聞之 倚柱而立 終日不瞬 人物過前而不之省)」</b>. 옛 책이 사람의 마음을 이렇게 자세히 적는 일은 아주 드물어요. 그 뒤에 이어지는 말도 그대로 남아 있습니다. <b>「아아, 대장부가 어찌 백제를 삼키지 못하겠는가(嗟乎 大丈夫豈不能呑百濟乎)」</b>."},{"n":3,"kind":"추론","q":"김춘추가 군사를 모으는 대신 이웃 나라에 사신으로 가겠다고 한 데서 무엇을 짐작할 수 있을까요?","opts":["김춘추가 본디 싸움을 싫어하는 사람이었다는 것","그때 신라의 힘만으로는 백제를 당해 내기 어려웠다는 것","고구려와 신라가 오래전부터 사이좋게 지냈다는 것","그 무렵 신라의 군사가 백제보다 훨씬 많았다는 것"],"answer":1,"why":{"0":"그가 청한 것은 싸우지 말자는 것이 아니라 군사를 빌려 오겠다는 것이었습니다.","2":"본문은 두 나라가 백 년 가까이 국경에서 서로 성을 빼앗았다고 적고 있습니다.","3":"군사가 넉넉했다면 남의 나라에 가서 군사를 꾸어 달라고 할 까닭이 없습니다."},"ref":"신라는 서쪽에서 성 마흔 곳을 잃었고, 대야성까지 열리자 서라벌로 오는 길목이 뚫렸습니다.","more":"『삼국사기』 신라본기는 그해 겨울을 이렇게 적었어요. <b>「왕이 백제를 쳐서 대야성의 싸움을 갚고자 하여, 이찬 김춘추를 고구려에 보내 군사를 청하게 했다(王將伐百濟 以報大耶之役 乃遣伊湌金春秋於高句麗 請師)」</b>. 사신으로 간다는 것은 편한 일이 아니었습니다. 오랫동안 싸워 온 나라의 임금 앞에 혼자 서는 일이었으니까요. 그 길에서 김춘추가 무엇을 겪었는지는 같은 책에 이어서 적혀 있습니다."},{"n":4,"kind":"낱말·표현","q":"'내응'은 무엇을 뜻하는 말인가요?","opts":["한 고을의 군사와 정치를 함께 맡아 다스리던 벼슬","어려움에 빠진 편을 도우러 오는 군사","싸움에 진 쪽이 이긴 쪽에게 굽히고 따르겠다고 하는 것","성안에 있으면서 밖의 적과 몰래 손을 잡는 일"],"answer":3,"why":{"0":"그것은 본문에서 도독이라고 부른 것입니다.","1":"그것은 본문에서 원병이라고 부른 것입니다.","2":"그것은 본문에서 항복이라고 부른 것입니다."},"ref":"성안에 있으면서 밖의 적과 몰래 손을 잡았으니, 옛 책은 그가 내응이 되었다고 적었습니다.","more":"「내응」은 우리가 풀어 쓴 말이 아니라 옛 책에 그대로 있는 말이에요. 죽죽 열전은 <b>「이때에 이르러 내응이 되어 그 창고를 불태웠다(至是 爲內應 燒其倉庫)」</b>라고 적습니다. 같은 열전에는 죽죽이 제 이름을 두고 한 말도 남아 있어요. <b>「내 아버지가 나를 죽죽이라 이름 지은 것은, 추운 겨울에도 시들지 말고 꺾일지언정 굽지 말라고 하신 것이다(吾父名我以竹竹者 使我歲寒不彫 可折而不可屈)」</b>. 이름 하나를 풀어서 제 삶을 설명한 셈이지요."},{"n":5,"kind":"생각 넓히기","q":"학자들의 해석을 따른다면, 이 이야기를 「백제는 나쁜 나라였다」로 읽으면 안 되는 까닭은 무엇일까요?","opts":["백제에게도 신라에게 갚을 일이 있었고, 두 나라 다 제 나라의 살길을 찾고 있었기 때문입니다","옛 책이 백제를 좋은 나라로만 적어 두었기 때문입니다","백제 군사가 대야성에 온 일이 없기 때문입니다","이 일이 실제로 일어난 일이 아니기 때문입니다"],"answer":0,"why":{"1":"옛 책은 백제를 좋게만 적지 않았습니다. 오히려 백제 쪽 기록과 신라 쪽 기록이 같은 일을 서로 다르게 적었지요.","2":"백제 군사는 그해 가을에 골짜기를 메웠고 옛 책은 그 수까지 적어 두었습니다.","3":"이 일은 『삼국사기』에 달까지 적혀 있는 일입니다."},"ref":"백제에게도 갚을 것이 있었습니다.","more":"같은 하루를 두고도 적는 쪽에 따라 남는 말이 달라집니다. 『삼국사기』 백제본기 의자왕 2년 조는 이 일을 백제 쪽에서 이렇게 적었어요. <b>「팔월, 장군 윤충을 보내 군사 일만을 거느리고 신라 대야성을 치게 했다(八月 遣將軍允忠 領兵一萬 攻新羅大耶城)」</b>. 그리고 성을 얻은 뒤 임금이 그 장군에게 말 스무 필과 곡식 일천 석을 상으로 주었다고 덧붙입니다. 신라 쪽 기록에는 슬픔이 적혀 있고 백제 쪽 기록에는 상이 적혀 있는 셈이지요. 어느 쪽이 나쁜지를 정하기 전에 그 말을 누가 적었는지를 먼저 보는 것이 역사를 읽는 방법이랍니다."}],"summary":["642년, 백제가 신라의 서쪽 성 마흔 곳을 빼앗고 대야성까지 무너뜨렸어요. 성문이 열린 데에는 도독에게 아내를 빼앗긴 성안 사람의 원한이 있었지요.","항복하자는 말을 물리치고 끝까지 싸운 죽죽의 이름과, 그가 남긴 말이 『삼국사기』 열전에 적혀 있어요.","그 성에서 딸과 사위를 잃은 김춘추는 군사를 모으는 대신, 원수의 나라 고구려에 사신으로 가겠다고 임금께 청했어요."],"bait":["그 아버지는 군사를 모으지 않았습니다. 대신 <span class=\"blur\">혼자 길을 떠났습니다</span>. 처음 간 곳은 원수의 나라 고구려였고, 다음은 바다 건너 왜였고, 마지막은 서쪽의 당이었지요. 그는 무엇을 얻으러 다녔을까요……"]};

;
(window.EPS ||= {})[45] = {"no":45,"chapter":"2장 세 나라의 시대","when":"642~648년","read":"읽기 17~19분","ago":"약 1,380년 전","title":"원수의 나라에 사신으로 간다는 것","subtitle":"그는 군사를 모으지 않았습니다. 대신 짐을 꾸려 원수의 나라 문으로 걸어 들어갔습니다","intro":"오늘 이야기의 무대는 <b>신라</b>예요. 이 무렵 세 나라는 서로 죽이도록 싸우고 있었지요. 그래도 나라와 나라 사이에는 사람이 오갔어요. 이렇게 나라를 대표해 남의 나라에 가는 사람을 <b>사신</b>이라고 해요. 사신은 군사를 데려가지 않아요. 말과 예물만 들고 가지요. 그렇다면 원수의 나라에 사신으로 간다는 것은 대체 어떤 일이었을까요? 짐을 꾸려 길을 떠난 한 사람을 따라가며 알아볼까요?","acts":[{"heading":"예순 날","blocks":[{"t":"p","dlg":false,"html":"그해 겨울, <em class=\"hint\">금성</em>의 궁궐 문이 열리고 말 몇 필이 나왔습니다."},{"t":"p","dlg":false,"html":"앞선 말에 탄 사람은 김춘추였습니다. 신라에서 손꼽히는 집안의 어른이었고, 몇 달 전 서쪽 대야성에서 딸과 사위를 한꺼번에 잃은 사람이었습니다."},{"t":"p","dlg":false,"html":"성이 무너졌다는 소식을 들은 날, 그는 기둥에 기대선 채로 하루를 보냈습니다. 눈을 깜빡이지 않았고 사람이 앞을 지나가도 알아보지 못했다고 합니다."},{"t":"p","dlg":false,"html":"그러고 나서 그가 한 일은 군사를 모으는 것이 아니었습니다."},{"t":"p","dlg":false,"html":"임금 앞에 나아가 그는 이렇게 말했습니다."},{"t":"p","dlg":true,"html":"“고구려에 가겠습니다. 가서 군사를 빌려 오겠습니다.”"},{"t":"p","dlg":false,"html":"마당이 조용해졌습니다. 고구려는 백 년이 넘도록 신라의 성을 빼앗아 온 나라였습니다. 군사를 빌리러 갈 곳이 아니라 군사가 쳐들어오는 쪽이었습니다."},{"t":"p","dlg":false,"html":"뒤따르는 말에는 <em class=\"dot\">사신</em> 일행이 탔습니다. 그 가운데 스물한 살 난 한별이 있었습니다. 한강 가에서 나고 자란 젊은이였습니다. 그 땅이 신라 땅이 된 지 아흔 해쯤 되었지만 마을 노인들은 아직 북쪽 말투를 썼고, 한별은 그 말을 알아들었습니다. 그래서 뽑혔습니다."},{"t":"p","dlg":false,"html":"금성에서 십 리쯤 나온 자리에서 한 사람이 말을 세웠습니다. 김유신이었습니다. 그해에 서쪽 국경의 군사를 맡은 사람이었지요."},{"t":"p","dlg":false,"html":"두 사람은 말에서 내려 마주 섰습니다."},{"t":"p","dlg":true,"html":"“<em class=\"hint\">공</em>이 예순 날 안에 돌아오지 않으면, 내 말발굽이 고구려와 백제 두 임금의 뜰을 밟을 것입니다.”"},{"t":"p","dlg":false,"html":"김춘추가 웃었습니다."},{"t":"p","dlg":true,"html":"“날을 헤아려 보니 예순 날이면 넉넉하겠습니다. 그날이 지나도 오지 않거든 다시 볼 <em class=\"hint\">기약</em>은 없는 줄 아십시오.”"},{"t":"p","dlg":false,"html":"두 사람은 손가락을 깨물어 피를 내고 서로 나누어 마셨습니다. 한별은 그것을 조금 떨어져서 보았습니다. 예순 날 안에 돌아오지 않으면 군사를 몰고 쳐들어가서라도 데려오겠다는 약속이었고, 피를 나누어 마신 것은 그 약속을 목숨처럼 지키겠다는 맹세였습니다."},{"t":"p","dlg":false,"html":"이백 해도 더 전에, 임금의 아우를 데리러 바다를 건넜다가 돌아오지 못한 신하가 있었습니다. 신라 사람이면 그 이야기를 다 알았습니다. 한별도 알았습니다. 그 사람은 남의 나라에 잡혀 있는 사람을 데리러 간 것이었고, 지금 이 사람은 함께 싸워 줄 동무를 구하러 가는 것이었습니다. 다른 걸음이었습니다. 다만 가는 곳이 남의 나라라는 것만 같았습니다."},{"t":"p","dlg":false,"html":"고구려의 도읍은 평양이었습니다."},{"t":"p","dlg":false,"html":"그 나라는 두어 달 전에 크게 뒤집힌 참이었습니다. 국경에 긴 성을 쌓던 신하 하나가 임금을 죽이고 새 임금을 세운 뒤, 나라의 군사를 통째로 쥐고 있었지요. 그런 나라의 성문 안으로 신라 사신의 깃발이 들어갔습니다."},{"t":"p","dlg":false,"html":"임금 앞에서 김춘추는 백제가 한 해 사이에 신라의 성을 마흔 곳 넘게 빼앗았다고 말했습니다. 그러고는 군사를 빌려 달라고 청했습니다."},{"t":"illust","n":1,"cap":"신라의 사신이 원수의 나라 궁궐 마당에 홀로 섰습니다","src":"img/web/ep045-plate-1.jpg?v=ff3ea9651d"},{"t":"p","dlg":false,"html":"임금은 한참 뒤에 입을 열었습니다."},{"t":"p","dlg":true,"html":"“<em class=\"dot\">죽령</em> 서북쪽 땅은 본래 우리 나라의 것이니, 그 땅을 돌려주면 군사를 내주겠다. 돌려주지 않으면 돌아가지 못할 것이다.”"},{"t":"p","dlg":false,"html":"백 년쯤 전에 신라가 차지한 땅이었습니다. 고구려는 그것을 빌려주는 값이 아니라 제 것을 돌려받는 일이라고 말하고 있었습니다."},{"t":"p","dlg":false,"html":"한별이 통역을 하려다 말고 멈칫했습니다. 통역할 것이 없었습니다. 임금의 말을 김춘추도 그대로 알아들었기 때문입니다."},{"t":"p","dlg":false,"html":"김춘추가 대답했습니다."},{"t":"p","dlg":true,"html":"“나라의 땅은 신하가 제 마음대로 내줄 수 있는 것이 아닙니다.”"},{"t":"p","dlg":false,"html":"땅은 신라의 임금과 백성의 것이지, 사신 한 사람이 약속해 줄 수 있는 것이 아니라는 대답이었습니다. 임금의 얼굴이 굳었습니다. 그날로 김춘추는 손님을 묵게 하는 궁궐 밖 <em class=\"dot\">별관</em>에 갇혔습니다. 문 앞에 군사가 섰고, 하루 한 번 밥상만 들어갔다 나왔습니다."},{"t":"spot","n":1,"size":"normal","cap":"김춘추가 땅을 내줄 수 없다고 하자, 고구려는 별관에 가두고 문 앞을 지켰다","src":"img/web/ep045-spot-1.jpg?v=a5bfc36ec3"}]},{"heading":"간을 두고 온 토끼","blocks":[{"t":"p","dlg":false,"html":"갇힌 날이 스무 날을 넘겼습니다."},{"t":"p","dlg":false,"html":"한별은 별관에 못 들어갔습니다. 성안 여관에 머물며 날마다 문 앞까지 갔다가 돌아왔습니다. 그러는 동안 김춘추는 안에서 짐을 뒤졌습니다."},{"t":"p","dlg":false,"html":"오는 길 어느 고을에서 그 고을 벼슬아치가 <em class=\"hint\">노자</em>로 넣어 준 <em class=\"dot\">청포</em>가 짐 밑에 있었습니다. 삼백 보나 되는 큰 뭉치였습니다. 김춘추는 그것을 밥상을 나르는 사람 편에 내보냈습니다. 받을 사람의 이름을 하나 일러 주면서요."},{"t":"spot","n":2,"size":"normal","cut":true,"width":576,"height":341,"cap":"김춘추의 짐 밑에는 먼 길의 노자로 받은, 푸른 베 청포가 큰 뭉치로 들어 있었다","src":"img/web/ep045-spot-2.png?v=ec6ca7f042"},{"t":"p","dlg":false,"html":"선도해라는 사람이었습니다."},{"t":"p","dlg":false,"html":"선도해는 고구려 임금이 가장 아끼는 신하였습니다. 한별은 나중에야 그 뜻을 알았습니다. 갇힌 사람이 기댈 곳은 임금의 귀에 말이 닿는 사람뿐이었습니다."},{"t":"p","dlg":false,"html":"사흘 뒤 저녁, 그가 술상을 들고 별관으로 들어왔습니다. 갇힌 사람을 위로하러 왔다고 했습니다. 군사들은 막지 않았습니다."},{"t":"p","dlg":false,"html":"두 사람은 마주 앉아 술을 마셨습니다. 나라 이야기도 군사 이야기도 하지 않았습니다. 날이 춥다는 이야기, 평양의 술맛이 어떻다는 이야기만 오갔습니다. 술이 얼근해지자 선도해가 잔을 내려놓고 물었습니다."},{"t":"p","dlg":true,"html":"“공은 거북과 토끼 이야기를 들어 보았는가.”"},{"t":"p","dlg":false,"html":"김춘추가 아니라고 하자 선도해는 농담처럼 이야기를 시작했습니다."},{"t":"illust","n":2,"cap":"고구려의 신하가 술상을 들고 갇힌 사람을 찾아왔습니다","src":"img/web/ep045-plate-2.jpg?v=7dfa54174f"},{"t":"p","dlg":false,"html":"옛날에 동해 용왕의 딸이 병이 났습니다. 무엇을 써도 낫지 않았는데 의원이 말하기를, 토끼의 간을 얻어 약을 지으면 나을 것이라고 했습니다. 그런데 바닷속에 토끼가 있을 리 없었습니다."},{"t":"p","dlg":false,"html":"그때 거북 하나가 나서서 제가 구해 오겠다고 했습니다."},{"t":"p","dlg":false,"html":"거북은 뭍으로 올라가 토끼를 만나 이렇게 말했습니다."},{"t":"p","dlg":true,"html":"“바다 가운데 섬이 하나 있다. 물이 맑고 돌이 희고 숲이 우거지고 열매가 달다. 춥지도 덥지도 않고 매도 못 들어온다. 네가 거기 가면 아무 걱정 없이 살 것이다.”"},{"t":"p","dlg":false,"html":"토끼는 솔깃해서 거북의 등에 올라탔습니다. 한참을 헤엄쳐 가다가 거북이 고개를 돌려 말했습니다."},{"t":"p","dlg":true,"html":"“실은 용왕의 따님이 앓는데 네 간이 있어야 낫는다. 그래서 이 먼 길을 지고 온 것이다.”"},{"t":"p","dlg":false,"html":"토끼가 말했습니다."},{"t":"p","dlg":true,"html":"“아이고, 나는 신령한 짐승의 자손이라 <em class=\"hint\">오장</em>을 꺼내어 씻어서 도로 넣을 줄 안다. 요 며칠 속이 답답하기에 간을 꺼내 씻어서 바위 밑에 놓아두고 왔다. 네 말이 하도 달콤해서 그냥 따라나섰구나. 간은 아직 거기 있으니 돌아가 가져오면 되지 않느냐. 너는 구하는 것을 얻고 나는 간이 없어도 사니, 둘 다 좋은 일 아니냐.”"},{"t":"p","dlg":false,"html":"거북은 그 말을 믿고 도로 헤엄쳐 나왔습니다. 뭍에 닿자마자 토끼는 풀숲으로 뛰어들며 말했습니다."},{"t":"p","dlg":true,"html":"“어리석구나. 간 없이 사는 짐승이 어디 있느냐.”"},{"t":"p","dlg":false,"html":"선도해는 이야기를 마치고 크게 웃었습니다. 그러고는 술상을 그대로 두고 일어나 나갔습니다."},{"t":"p","dlg":false,"html":"김춘추는 그 이야기를 두 번 되짚어 보고 나서야 선도해가 무엇을 일러 주고 갔는지 알았습니다. 거북에게 붙잡힌 토끼는 간을 바위 밑에 두고 왔다고 둘러대어 뭍으로 돌아갔습니다. 붙잡힌 사람도 우선 살아서 나갈 말을 하라는 것이었습니다."},{"t":"p","dlg":false,"html":"이튿날 그는 글을 써서 임금에게 올렸습니다."},{"t":"p","dlg":false,"html":"두 고개 너머의 땅은 본래 대국의 땅이니, 제가 돌아가 우리 임금께 청하여 돌려드리겠습니다. 제 말을 믿지 못하시겠거든 저 해를 두고 맹세하겠습니다."},{"t":"p","dlg":false,"html":"그 무렵 남쪽에서 소식이 올라왔습니다. 예순 날이 지나도록 김춘추가 돌아오지 않자 신라 군사가 한강을 넘어 고구려 땅으로 들어섰다는 것이었습니다. 고구려가 신라에 심어 둔 사람이 알려 온 소식이었습니다. 떠나던 날 김유신이 한 약속, 바로 그 예순 날이었습니다."},{"t":"p","dlg":false,"html":"임금은 김춘추를 후하게 대접해서 돌려보냈습니다."},{"t":"p","dlg":false,"html":"돌아오는 길, 한별이 물었습니다."},{"t":"p","dlg":true,"html":"“정말 그 땅을 돌려주실 겁니까.”"},{"t":"p","dlg":false,"html":"김춘추는 앞만 보고 말했습니다."},{"t":"p","dlg":true,"html":"“토끼가 간을 두고 왔더냐.”"},{"t":"p","dlg":false,"html":"한별은 그제야 알아들었습니다. 땅을 돌려주겠다는 글은 토끼의 간과 같은 말이었습니다. 나라의 땅은 신하가 마음대로 내줄 수 없다고 한 사람이 바로 그였습니다."},{"t":"p","dlg":false,"html":"이 걸음에서 김춘추가 얻은 것은 없었습니다. 다만 알아낸 것은 있었습니다. 군사를 빌리려면 무엇인가를 내주어야 한다는 것이었습니다."},{"t":"p","dlg":false,"html":"다섯 해 뒤, 그는 바다를 건넜습니다."},{"t":"p","dlg":false,"html":"배의 노를 잡은 사람이 돗대였습니다. 동쪽 <em class=\"hint\">포구</em>에서 나고 자라 바다를 저어 다니던 사람이었지요. 김춘추가 간 곳은 왜, 그러니까 그 무렵 일본 땅에 있던 나라였습니다."},{"t":"p","dlg":false,"html":"그 걸음을 적어 둔 것은 우리 책이 아니라 바다 건너의 책이었습니다. 그 책에는 신라에서 높은 사람이 왔는데 얼굴이 잘생기고 말솜씨가 좋았다고 적혀 있습니다. 얼마나 오래 머물렀는지, 무슨 말을 주고받았는지는 적혀 있지 않습니다."},{"t":"p","dlg":false,"html":"배가 돌아왔을 때 갑판에 실린 것은 예물뿐이었습니다. 군사를 보내겠다는 약속은 없었습니다."}]},{"heading":"옷을 바꾸어 입다","blocks":[{"t":"p","dlg":false,"html":"그 이듬해 겨울, 돗대는 다시 노를 잡았습니다. 이번에는 서쪽 바다였습니다."},{"t":"p","dlg":false,"html":"배에는 김춘추와 그의 아들이 함께 탔습니다. 한별도 탔습니다. 지난 다섯 해 동안 한별은 당의 말을 배웠습니다. 처음에는 글자부터 시작해서, 나중에는 눈을 감고도 그 말이 들리게 되었습니다."},{"t":"p","dlg":false,"html":"당은 그 무렵 서쪽에서 가장 큰 나라였습니다. 살수에서 크게 지고 무너진 나라의 자리에 선 나라였고, 흩어진 땅을 다시 하나로 묶은 지 서른 해쯤 되었지요. 황제는 그 나라의 두 번째 임금이었습니다."},{"t":"p","dlg":false,"html":"<em class=\"hint\">장안</em>의 궁궐에서 김춘추는 황제를 만났습니다. 당 태종이었습니다. 세 해 전 요동의 작은 성 하나 앞에서 끝내 발길을 돌렸던 바로 그 황제였습니다."},{"t":"p","dlg":false,"html":"김춘추는 먼저 나라의 학교를 보고 싶다고 청했습니다. 황제가 허락해서 그는 학생들이 옛 책을 소리 내어 읽는 것을 한나절 지켜보았습니다. 한별이 보기에 그것은 당의 배움을 높이 여긴다는 것을 황제에게 먼저 보여 주는 걸음이었습니다."},{"t":"p","dlg":false,"html":"그러고 나서 황제 앞에 나아가 이렇게 말했습니다."},{"t":"p","dlg":true,"html":"“신의 나라는 바다 모퉁이에 치우쳐 있습니다. 그런데 백제가 강하고 사나워서 해마다 쳐들어오고, 지난해에는 크게 밀고 들어와 성 수십 곳을 빼앗고 폐하께 오는 길까지 막았습니다. 폐하께서 군사를 빌려주지 않으시면, 저희 백성은 모두 사로잡히고 배와 수레가 다시는 이곳에 닿지 못할 것입니다.”"},{"t":"p","dlg":false,"html":"황제는 오래 생각하지 않았습니다. 군사를 내주겠다고 했습니다."},{"t":"p","dlg":false,"html":"한별은 그 말을 옮기다가 손끝이 떨렸습니다. 여섯 해를 걸어서 온 대답이었습니다. 황제가 왜 그렇게 쉽게 허락했는지도 알 것 같았습니다. 그 황제도 고구려에 갚을 것이 있는 사람이었습니다."},{"t":"p","dlg":false,"html":"그런데 김춘추가 물러나지 않고 한 가지를 더 청했습니다. 아무도 시키지 않은 청이었습니다."},{"t":"p","dlg":true,"html":"“저희 나라의 <em class=\"dot\">관복</em>과 관을 당의 것으로 고치게 해 주십시오.”"},{"t":"p","dlg":false,"html":"황제가 안쪽 창고에서 옷을 내오게 해 김춘추와 그를 따라온 사람들에게 나누어 주었습니다. 한별은 그 옷을 받아 들고 오래 내려다보았습니다. 이제 신라의 벼슬아치는 누구나 당의 벼슬아치와 같은 차림을 하게 될 것이었습니다. 신라가 당의 편에 서서 당의 법도를 따르겠다는 것을, 온 나라 벼슬아치의 몸으로 보여 주는 일이었습니다."},{"t":"spot","n":3,"size":"large","cap":"김춘추는 신라의 관복과 관을 당의 것으로 바꾸게 해 달라고 스스로 청했다","src":"img/web/ep045-spot-3.jpg?v=30ab50e9a5"},{"t":"p","dlg":false,"html":"돌아오기 전 김춘추는 황제에게 한 가지를 더 아뢰었습니다."},{"t":"p","dlg":true,"html":"“제 아들 하나를 이곳에 남겨, 폐하 곁에 머물며 폐하를 지키는 <em class=\"dot\">숙위</em>를 하게 하겠습니다.”"},{"t":"p","dlg":false,"html":"한별에게는 그것이, 제 아들을 큰 나라에 맡겨 두고라도 이 약속을 저버리지 않겠다는 다짐처럼 보였습니다."},{"t":"p","dlg":false,"html":"이렇게 해서 신라와 당은 함께 싸우기로 약속했습니다. 두 나라 사이에 <em class=\"dot\">동맹</em>이 맺어진 것입니다."},{"t":"p","dlg":false,"html":"돌아오는 배는 서해 한가운데에서 고구려의 순찰선을 만났습니다."},{"t":"p","dlg":false,"html":"바다 위에는 숨을 곳이 없었습니다. 그때 함께 간 신하 하나가 김춘추의 높은 관과 큰 옷을 벗겨 제가 입었습니다. 그러고는 큰 배의 뱃전에 올라앉아 멀리서도 보이게 했습니다."},{"t":"p","dlg":false,"html":"김춘추는 작은 배로 옮겨 탔습니다. 노를 잡은 사람은 돗대였습니다."},{"t":"illust","n":3,"cap":"돌아오는 배에서 한 사람이 남의 옷을 입고 뱃전에 앉았습니다","src":"img/web/ep045-plate-3.jpg?v=586d978b74"},{"t":"p","dlg":false,"html":"고구려 군사들은 뱃전에 앉은 사람을 김춘추로 알고 붙잡아 갔고, 그는 돌아오지 못했습니다. 작은 배는 그사이에 안개 속으로 빠져나갔습니다."},{"t":"p","dlg":false,"html":"금성에 닿은 날 밤, 한별이 물었습니다."},{"t":"p","dlg":true,"html":"“어른께서 여섯 해 동안 얻으신 것이 무엇입니까.”"},{"t":"p","dlg":false,"html":"김춘추는 한참 있다가 대답했습니다."},{"t":"p","dlg":true,"html":"“동무 하나다.”"},{"t":"p","dlg":true,"html":"“내주신 것은요.”"},{"t":"p","dlg":false,"html":"김춘추는 대답하지 않았습니다. 한별도 더 묻지 않았습니다. 뱃전에 대신 앉았던 그 사람의 얼굴이 떠올랐기 때문입니다."},{"t":"p","dlg":false,"html":"그날 배 위에서 그가 얻은 것과 내준 것을 사람들은 오래도록 저울에 올려놓습니다. 얻은 것은 군사였습니다. 그 군사가 오지 않았다면 신라가 그 뒤 스무 해를 버티지 못했으리라고 보는 사람이 많습니다. 내준 것은 옷과 관이었고, 아들이었고, 얼마 뒤에는 제 나라가 스스로 붙이던 해의 이름이었습니다. 그리고 훨씬 뒤에는, 자기가 부른 손님을 제 손으로 돌려보내야 하는 일이 남아 있었습니다."},{"t":"p","dlg":false,"html":"어느 쪽을 더 크게 보느냐에 따라 오늘도 사람들의 말이 갈립니다."}]}],"words":[{"w":"사신","d":"나라를 대표해 남의 나라에 보내는 사람"},{"w":"죽령","d":"경상북도 영주와 충청북도 단양 사이에 있는 큰 고개. 이 무렵 신라와 고구려의 국경이었다"},{"w":"별관","d":"손님을 묵게 하려고 궁궐 밖에 따로 지어 둔 집"},{"w":"청포","d":"푸른 물을 들인 베"},{"w":"관복","d":"벼슬아치가 나랏일을 볼 때 입던 옷"},{"w":"숙위","d":"황제 곁에 머물며 그를 지키는 일. 신하 나라가 제 나라 사람을 보내 이 일을 맡기기도 했다"},{"w":"동맹","d":"두 나라가 힘을 합쳐 함께 싸우기로 맺는 약속"}],"hints":[{"w":"금성","d":"신라 사람들이 도읍 서라벌을 달리 부르던 이름"},{"w":"공","d":"상대를 높여 부르는 말"},{"w":"기약","d":"때를 정해 두고 한 약속"},{"w":"노자","d":"먼 길을 오가는 데 드는 돈이나 물건"},{"w":"오장","d":"몸속에 있는 간·심장·허파 같은 다섯 가지 기관"},{"w":"포구","d":"배가 드나드는 강이나 바다의 어귀"},{"w":"장안","d":"당의 도읍. 오늘날 중국의 시안"}],"after":{"title":"옷을 갈아입은 나라","html":["이듬해 정월부터 신라의 벼슬아치들은 당의 옷을 입기 시작했습니다. 그다음 해에는 제 나라가 스스로 쓰던 해의 이름을 버리고 당이 쓰는 이름을 함께 썼습니다. 법흥왕 때부터 백열네 해 동안 이어 온 것이었지요. 김춘추는 654년에 신라의 임금이 되었고, 뒷날 태종 무열왕이라 불립니다. 660년 백제의 도읍이 무너지는 것을 보고 이듬해 세상을 떠났습니다. 당의 군사를 이 땅으로 부른 사람이 그였고, 그 군사를 이 땅에서 다시 내보내는 일은 그의 아들 대에 남겨졌습니다."]},"ifme":{"q":"나라를 지키려고 우리 것 하나를 내놓아야 한다면, 나는 무엇까지 내놓을 수 있을까?","html":["김춘추는 고구려에서 땅을 내놓으라는 말을 듣고 “그것은 안 됩니다”라고 했습니다. 그런데 당에서는 아무도 시키지 않았는데 스스로 옷과 관을 바꾸겠다고 했지요. 그에게 땅과 옷은 서로 다른 것이었던 모양입니다. 옷은 그저 옷일까요, 아니면 옷도 그 나라의 무엇일까요. 여러분이라면 무엇은 내줄 수 있고 무엇은 절대 안 된다고 하겠어요? 그렇게 나눈 기준까지 말해 보세요. 정답은 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 김춘추와 김유신, 고구려의 신하 선도해, 그리고 당 태종은 모두 실제로 있었던 사람이에요. 642년에 김춘추가 고구려로 가서 갇혔다가 돌아온 일, 떠나기 전에 김유신과 예순 날을 두고 맹세한 일, 648년에 당으로 건너가 군사를 얻고 옷과 관을 고치기를 스스로 청한 일은 모두 『삼국사기』에 적혀 있지요. 거북과 토끼 이야기도 지어낸 것이 아니라 그 책 김유신 열전에 그대로 실려 있어요. 오늘날 우리가 아는 『별주부전』이 바로 이 이야기에서 자라난 것이랍니다. 돌아오는 배에서 김춘추 대신 옷을 바꾸어 입고 붙잡힌 신하가 있었다는 것도 같은 책에 적혀 있습니다. 다만 선도해가 정말 그런 뜻으로 이야기를 했는지까지는 아무도 확인할 수 없어요. 왜에 건너간 일은 우리 책에 한 줄도 없고 바다 건너의 책에만 적혀 있고요. 돗대와 한별은 지어낸 사람입니다."]},"quiz":[{"n":1,"kind":"사실 확인","q":"김춘추가 고구려로 떠나기 전에 김유신과 나눈 약속은 무엇이었나요?","opts":["김춘추가 돌아올 때까지 김유신이 임금 곁을 지키기로 한 것","예순 날이 지나도 돌아오지 않으면 김유신이 군사를 몰고 오기로 한 것","고구려에서 빌려 온 군사를 김유신이 이끌기로 한 것","두 사람이 함께 고구려로 들어가기로 한 것"],"answer":1,"why":{"0":"김유신이 그해에 맡은 것은 임금 곁이 아니라 서쪽 국경의 군사였습니다.","2":"고구려에서 군사를 빌려 오는 일은 이루어지지 않았습니다.","3":"김유신은 금성에서 십 리쯤 나온 자리까지만 배웅하고 돌아섰습니다."},"ref":"공이 예순 날 안에 돌아오지 않으면, 내 말발굽이 고구려와 백제 두 임금의 뜰을 밟을 것입니다.","more":"『삼국사기』 김유신 열전에 그대로 있는 말이에요. <b>「我之馬跡 必踐於麗濟兩君之庭」</b>(내 말발굽이 반드시 고구려와 백제 두 임금의 뜰을 밟으리라). 예순 날을 댄 것은 김춘추 쪽이고요. <b>「吾計日六旬乃還」</b>. 그런데 김유신이 실제로 이끈 군사의 수는 같은 책 안에서도 다르게 적혀 있어요. 신라본기는 결사대 <b>일만 명</b>이라 하고 김유신 열전은 용사 <b>삼천 명</b>이라고 합니다. 한 권의 책 안에서도 숫자가 어긋나는 자리가 이렇게 있답니다."},{"n":2,"kind":"사실 확인","q":"고구려 임금은 군사를 빌려주는 대신 무엇을 요구했나요?","opts":["김춘추의 아들을 고구려에 두고 갈 것","해마다 신라의 곡식과 쇠를 고구려에 보낼 것","신라가 백제와 맺은 약속을 먼저 깨뜨릴 것","죽령 서북쪽 땅을 신라가 돌려줄 것"],"answer":3,"why":{"0":"김춘추가 아들을 남긴 것은 고구려가 아니라 훨씬 뒤의 당에서였습니다.","1":"곡식이나 쇠를 해마다 보내라는 말은 나오지 않습니다.","2":"이 무렵 신라와 백제는 손잡은 사이가 아니라 서로 성을 빼앗는 사이였습니다."},"ref":"죽령 서북쪽 땅은 본래 우리 나라의 것이니, 그 땅을 돌려주면 군사를 내주겠다.","more":"『삼국사기』 원문은 고개를 둘 댑니다. <b>「麻木峴與竹嶺 本我國地」</b>(마목현과 죽령은 본래 우리 나라 땅이다). 마목현은 오늘날의 문경새재로 보는 견해가 많아요. 그 고개 너머 땅은 백 년쯤 전 진흥왕 때 신라가 차지한 곳이지요. 29회에서 신라가 한강을 얻던 그 일 말이에요. 고구려로서는 「빌려주는 값」이 아니라 「돌려받는 것」이라고 말한 셈입니다."},{"n":3,"kind":"추론","q":"선도해는 왜 “땅을 돌려주겠다고 하십시오”라고 곧바로 일러 주지 않고, 거북과 토끼 이야기를 들려주었을까요?","opts":["김춘추가 고구려 말을 알아듣지 못해서 이야기로 풀어야 했기 때문에","김춘추가 술에 취해 있어서 곧바로 말해도 알아듣지 못했기 때문에","고구려 신하가 신라 사신을 돕는 것이 드러나면 자기도 위험해지기 때문에","거북과 토끼 이야기가 고구려에서 손님에게 꼭 들려주는 인사말이었기 때문에"],"answer":2,"why":{"0":"임금의 말도 김춘추가 그대로 알아들어서 한별이 통역을 멈칫했습니다.","1":"술이 얼근했던 것은 맞지만, 김춘추는 그 이야기를 두 번 되짚어 보고 뜻을 알아냈습니다.","3":"그런 인사말이라는 이야기는 어디에도 나오지 않습니다."},"ref":"나라 이야기도 군사 이야기도 하지 않았습니다.","more":"이 이야기는 『삼국사기』 김유신 열전에 <b>「子亦嘗聞龜兎之說乎」</b>(그대도 거북과 토끼 이야기를 들어 보았는가)로 시작해서 실려 있어요. 학자들은 더 거슬러 올라가 인도의 불경에 비슷한 이야기가 있다고 봅니다. 그러니까 인도에서 출발한 이야기가 천삼백 년 전 평양의 술자리를 거쳐, 조선 시대에 판소리 〈수궁가〉와 소설 『별주부전』이 된 셈이지요. 『별주부전』에서 거북이 자라로 바뀐 것도 그 사이의 일이랍니다."},{"n":4,"kind":"낱말·표현","q":"본문에 나온 '숙위'는 무엇을 뜻하는 말인가요?","opts":["싸우던 두 나라가 다투기를 그치고 사이좋게 지내기로 하는 것","나라를 대표해 남의 나라에 보내는 사람","남의 나라 궁궐을 지키는 군사를 통째로 빌려 오는 일","황제 곁에 머물며 그를 지키는 일"],"answer":3,"why":{"0":"그것은 화친이라고 합니다.","1":"그것은 사신입니다.","2":"군사를 빌려 오는 일은 김춘추가 청한 것이고, 숙위는 사람을 남겨 두는 일입니다."},"ref":"제 아들 하나를 이곳에 남겨, 폐하 곁에 머물며 폐하를 지키는 숙위를 하게 하겠습니다.","more":"이때 장안에 남은 아들의 이름은 <b>문왕</b>이에요. 「지킨다」는 좋은 말이 붙어 있지만, 실은 신하 나라가 제 나라 사람을 큰 나라에 두고 오는 일이라 볼모와 닮은 데가 있지요. 돌아오는 길의 일도 『삼국사기』에 적혀 있습니다. 고구려 순찰선을 만나자 종자 <b>온군해</b>가 김춘추의 높은 관과 큰 옷을 입고 뱃전에 앉았고, 군사들이 그를 김춘추로 알고 붙잡아 죽였어요. 임금은 그에게 대아찬이라는 벼슬을 내려 주었습니다."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 김춘추가 당과 맺은 이 약속을 두고 오늘날 사람들의 말이 갈리는 까닭은 무엇일까요?","opts":["그 동맹 덕분에 신라는 살아남았지만 큰 값도 함께 치렀기 때문에","김춘추가 당에 간 일이 우리 책에는 적혀 있지 않기 때문에","그 약속을 적어 둔 기록이 한 줄도 남아 있지 않기 때문에","당이 끝내 군사를 한 명도 보내지 않았기 때문에"],"answer":0,"why":{"1":"우리 책에 없는 것은 당에 간 일이 아니라 왜에 건너간 일입니다.","2":"김춘추가 당에서 한 말과 청한 일은 『삼국사기』에 자세히 적혀 있습니다.","3":"황제는 군사를 내주겠다고 했고, 뒤에 그 군사가 실제로 왔습니다."},"ref":"그날 배 위에서 그가 얻은 것과 내준 것을 사람들은 오래도록 저울에 올려놓습니다.","more":"660년에 당은 약속대로 군사를 보냈어요. 그런데 세 나라가 다 무너진 뒤 당은 옛 고구려 땅과 옛 백제 땅에 제 관청을 세웠고, 신라 땅에까지 손을 뻗으려 했습니다. 그래서 신라는 제가 부른 군대와 다시 싸워야 했지요. 그 이야기는 50회와 3장에서 만나게 됩니다. 교과서는 이 약속에 「나당 동맹」이라는 이름을 붙이지 않고 <b>「신라는 당과 동맹을 맺고」</b>라고만 적는답니다."}],"summary":["642년, 대야성에서 딸과 사위를 잃은 김춘추는 군사를 모으는 대신 원수의 나라 고구려로 가서 군사를 빌려 달라고 했어요. 고구려가 땅을 내놓으라고 하자 그는 갇혔지요.","고구려의 신하 선도해가 들려준 거북과 토끼 이야기에서 실마리를 얻어 김춘추는 풀려났어요. 그 이야기가 뒷날 『별주부전』으로 자라났답니다.","왜에서는 아무 약속도 얻지 못했지만, 648년 당에서는 군사를 얻었어요. 대신 신라는 관복과 관을 당의 것으로 고치고 아들을 황제 곁에 남겼답니다."],"bait":["그가 밖에서 동무를 구하는 동안, 안에서 칼을 쥐고 기다린 사람이 있었습니다. 손가락을 깨물어 함께 피를 나누어 마신 그 사람이지요. 가야 임금의 후손이라는 이유로 오래 밀려나 있던 사람이기도 했고요. 그는 어느 새벽 <span class=\"blur\">제 말의 목을 벱니다</span>. 왜 자기 말을 죽였을까요……"]};

;
(window.EPS ||= {})[46] = {"no":46,"chapter":"2장 세 나라의 시대","when":"595~660년","read":"읽기 15~17분","ago":"약 1,400년 전","title":"그는 왜 자기 말의 목을 베었을까","subtitle":"밖에서 동무를 구하는 사람이 있었고, 안에서 예순 날을 세는 사람이 있었습니다","intro":"오늘 이야기의 무대는 <b>신라</b>예요. 신라에는 태어날 때부터 정해지는 신분이 있었어요. 어느 자리까지 오를 수 있는지가 그 신분으로 미리 정해졌지요. 그런데 백 년쯤 전, 낙동강이 바다로 드는 자리에 있던 나라 하나가 통째로 신라 안으로 들어왔어요. 그 나라 임금의 자손들도 신라 사람이 되었고요. 밖에서 들어온 집안의 사람은 신라 안에서 어디쯤에 설 수 있었을까요? 그 집안에서 난 한 사람이 어떻게 나라의 한복판까지 걸어 들어갔는지, 말 한 마리의 목을 벤 사람을 따라가며 알아볼까요?","acts":[{"heading":"예순 날을 세는 사람","blocks":[{"t":"p","dlg":false,"html":"그해 겨울, 신라 서쪽 국경의 진영에서 한 사람이 날마다 나무쪽에 금을 하나씩 그었습니다."},{"t":"p","dlg":false,"html":"김유신이었습니다. 그해에 그 지방의 군사를 맡은 <em class=\"dot\">군주</em>였지요."},{"t":"p","dlg":false,"html":"금이 스물을 넘던 날 아침, 말굽이 물었습니다."},{"t":"p","dlg":true,"html":"“몇까지 세십니까.”"},{"t":"p","dlg":true,"html":"“예순.”"},{"t":"p","dlg":false,"html":"말굽은 그 진영의 말을 돌보는 사람이었습니다. 발굽을 손질하고 <em class=\"hint\">여물</em>을 먹이고 안장을 얹는 것이 그의 일이었지요. 김유신이 타는 밤색 말은 여덟 해째 말굽의 손을 거치고 있었습니다."},{"t":"spot","n":1,"size":"normal","cut":true,"width":511,"height":640,"cap":"말굽은 김유신의 밤색 말을 여덟 해째 돌보며, 여물을 먹이고 안장을 얹었다","src":"img/web/ep046-spot-1.png?v=ec9e3a3d04"},{"t":"p","dlg":false,"html":"금을 긋기 시작한 첫날, 김유신은 도읍에서 십 리쯤 나온 자리에서 한 사람과 손가락을 깨물어 피를 내고 서로 나누어 마셨습니다. 김춘추였습니다."},{"t":"p","dlg":false,"html":"그 사람은 지금 고구려에 있었습니다. 지난가을에 딸과 사위를 한꺼번에 잃고, 군사를 빌리러 원수의 나라 안으로 걸어 들어간 것이었지요."},{"t":"p","dlg":false,"html":"예순 날이 지나도 돌아오지 않으면 김유신이 국경을 넘기로 되어 있었습니다. 군사는 이미 뽑아 두었습니다."},{"t":"p","dlg":true,"html":"“사람 하나 때문에 나라끼리 붙는 겁니다.”"},{"t":"p","dlg":false,"html":"말굽이 낮게 말했습니다. 김유신은 나무쪽을 내려놓았습니다."},{"t":"p","dlg":true,"html":"“내가 잡을 손이 저 하나다. 이 도읍에서 나를 믿고 손을 내민 사람이 저 사람이다. 그 손을 놓을 수는 없다.”"},{"t":"p","dlg":false,"html":"말굽은 그 말을 오래 곱씹었습니다. 한 지방의 군사를 맡은 장수가 도읍에 믿을 사람이 하나뿐이라고 말하는 것이, 말굽에게는 이상하게 들렸습니다."},{"t":"p","dlg":false,"html":"김유신의 집안은 신라에서 오래된 집안이 아니었습니다."},{"t":"p","dlg":false,"html":"백열 해 전, 낙동강이 바다로 드는 자리에 있던 나라 하나가 스스로 걸어 들어와 신라에 나라를 넘겼습니다. 쇠가 넘치던 나라였지요. 싸움은 없었습니다. 그 나라의 임금은 왕비와 세 아들을 데리고 왔고, 신라는 그를 예로 맞아 높은 자리를 주었습니다."},{"t":"p","dlg":false,"html":"그 임금의 막내아들이 신라의 장수가 되었습니다. 김유신의 할아버지였습니다. 그리고 그 아들이 김서현이었지요."},{"t":"p","dlg":false,"html":"신라는 이 집안을 <em class=\"dot\">진골</em>로 대접했습니다. 신분으로 보면 나라에서 손꼽히는 자리였습니다. 그런데 그 자리와 별개로, 도읍 사람들은 이 집안을 “남쪽에서 들어온 집”이라고 불렀습니다. 신분은 높아도 본디 신라 사람은 아니라는 말이었습니다."},{"t":"p","dlg":false,"html":"그 말이 무슨 뜻이었는지가 가장 또렷하게 드러난 것은 김유신이 태어나기도 전의 일이었습니다."},{"t":"p","dlg":false,"html":"김서현이 만명이라는 여인과 혼인하려 했을 때 만명의 아버지가 반대했습니다. 만명은 왕족이었습니다. 아버지는 딸을 별채에 가두고 사람을 시켜 지키게 했습니다."},{"t":"p","dlg":false,"html":"그날 밤 벼락이 문간을 때렸고, 지키던 사람이 놀라 흩어진 사이에 만명이 담 구멍으로 빠져나갔습니다."},{"t":"illust","n":1,"cap":"벼락이 문간을 때린 밤에 그 집 딸이 담 구멍으로 빠져나갔습니다","src":"img/web/ep046-plate-1.jpg?v=580cc35b3c"},{"t":"p","dlg":false,"html":"두 사람은 그길로 도읍을 떠나 <em class=\"dot\">만노군</em>으로 갔습니다. 김서현이 그 고을을 맡아 다스리게 된 참이었지요."},{"t":"p","dlg":false,"html":"595년, 김유신은 그 고을에서 태어났습니다. 도읍에서 아주 먼 곳이었습니다."}]},{"heading":"무엇을 끊었을까","blocks":[{"t":"p","dlg":false,"html":"김유신이 열다섯이 되던 해에 <em class=\"dot\">화랑</em>이 되었습니다."},{"t":"p","dlg":false,"html":"화랑은 싸우는 법만 배우는 자리가 아니었습니다. 무리를 지어 노래하고 먼 산과 강을 찾아다니고 서로 사귀는 것이 먼저였지요. 싸움터로 나가는 것은 그렇게 자란 다음의 일이었습니다. 그가 이끈 무리에는 이름이 있었습니다. 용화향도라고 했습니다."},{"t":"spot","n":2,"size":"large","cap":"화랑의 무리는 싸움에 나서기 전에, 함께 노래하고 먼 산과 강을 찾아다녔다","src":"img/web/ep046-spot-2.jpg?v=760a464ca5"},{"t":"p","dlg":false,"html":"소나기는 그 무리에서 가장 어린 아이였습니다. 그해에 열셋이었지요."},{"t":"p","dlg":false,"html":"무리 안에서 소나기는 아무도 소리 내어 말하지 않는 것을 하나 알아차렸습니다. 나이 든 <em class=\"hint\">낭도</em>들이 김유신을 부를 때 잠깐 뜸을 들인다는 것이었습니다. 도읍의 오래된 집안에서 온 아이들일수록 그랬습니다. 남쪽에서 들어온 집 아들을 우두머리로 부르는 것이 아직 입에 붙지 않은 것이었습니다."},{"t":"p","dlg":false,"html":"열일곱이 되던 해에 그가 무리에서 사라졌습니다."},{"t":"p","dlg":false,"html":"고구려와 백제와 <em class=\"hint\">말갈</em>이 번갈아 국경을 넘어오던 때였습니다. 그는 혼자 산으로 들어가 굴 하나를 찾아 들어앉았습니다. 나흘 동안 나오지 않았습니다."},{"t":"p","dlg":false,"html":"굴 안에서 무엇을 했는지는 그 자신만 알았습니다. 옛 책은 그가 하늘에 대고 빌었다고 적었습니다. 나흘째 되던 날 어떤 노인이 굴 앞에 나타나 그에게 무엇인가를 일러 주고 갔다고도 적었지요."},{"t":"p","dlg":false,"html":"소나기는 그 나흘 동안 골짜기 어귀에 앉아 있었습니다. 아무도 따라 들어가지 못하게 되어 있었거든요."},{"t":"p","dlg":false,"html":"나흘째 저녁에 김유신이 내려왔습니다. 옷이 젖어 있었고 얼굴이 여위어 있었습니다."},{"t":"p","dlg":true,"html":"“무엇을 얻으셨습니까.”"},{"t":"p","dlg":false,"html":"김유신은 걸음을 멈추지 않았습니다."},{"t":"p","dlg":true,"html":"“얻으러 간 것이 아니다.”"},{"t":"p","dlg":true,"html":"“그럼 무엇 하러 가셨습니까.”"},{"t":"p","dlg":true,"html":"“내가 무엇을 걸 수 있는 사람인지 알아보러 갔다.”"},{"t":"p","dlg":false,"html":"소나기는 그 말을 그때는 알아듣지 못했습니다."},{"t":"p","dlg":false,"html":"그 무렵 무리 안에 이런 이야기가 돌았습니다."},{"t":"p","dlg":false,"html":"유신이 자주 드나들던 집이 있었는데 어머니가 그것을 알고 크게 꾸짖었다는 것이었습니다. 다시는 그 문 앞을 지나지 않겠다고 그는 어머니 앞에서 맹세했다지요. 그런데 어느 날 술에 취해 말 위에서 졸다가 눈을 떠 보니, 말이 늘 다니던 길로 저 혼자 걸어 그 집 앞에 서 있더랍니다."},{"t":"p","dlg":false,"html":"그는 말에서 내려 칼을 뽑아 말의 목을 베고, 안장을 그 자리에 버려둔 채 걸어서 돌아갔다고 했습니다. 어머니와 한 맹세를 지키려고, 저를 그 집 앞으로 데려간 말까지 끊어 버렸다는 이야기였습니다."},{"t":"p","dlg":false,"html":"소나기는 그 이야기를 여러 번 들었습니다. 들을 때마다 조금씩 달랐습니다. 어느 날은 어머니가 울었다고 했고, 어느 날은 그 집 사람이 노래를 지었다고 했습니다."},{"t":"p","dlg":false,"html":"소나기가 김유신에게 그 이야기가 정말이냐고 물어본 적이 있습니다. 그는 대답하지 않았습니다."},{"t":"p","dlg":false,"html":"그가 서른다섯이 되던 해 가을, 신라가 고구려의 성 하나를 쳤습니다. 낭비성이었습니다."},{"t":"p","dlg":false,"html":"첫 싸움에서 신라가 크게 밀렸습니다. 죽은 사람이 많았고 남은 군사들은 싸울 마음을 잃었습니다."},{"t":"p","dlg":false,"html":"김서현이 그 싸움에 부장으로 나와 있었습니다. 유신이 아버지 앞에 나아가 투구를 벗고 말했습니다."},{"t":"p","dlg":true,"html":"“제가 옷깃과 <em class=\"hint\">벼리</em>가 되겠습니다.”"},{"t":"p","dlg":false,"html":"옷깃을 잡아 올리면 <em class=\"hint\">갖옷</em>이 반듯해지고, 벼리를 당기면 그물이 활짝 펴집니다. 옷깃 하나를 잡으면 옷 전체가, 벼리 하나를 당기면 그물 전체가 따라오지요. 제가 먼저 나서서 흩어진 군사들의 마음을 한데 끌어 올리겠다는 말이었습니다."},{"t":"p","dlg":false,"html":"그는 말에 올라 홀로 적진으로 들어갔습니다. 그리고 적의 장수를 베고 그 깃발을 뽑아 돌아왔습니다. 그것을 본 신라 군사들이 함성을 지르며 뒤따라 나갔고, 그날 낭비성이 열렸습니다."},{"t":"illust","n":2,"cap":"그는 홀로 말을 몰아 적진으로 들어갔습니다","src":"img/web/ep046-plate-2.jpg?v=3ab389a73d"},{"t":"p","dlg":false,"html":"소나기도 그 벌판에 있었습니다. 그때 서른셋이었지요."},{"t":"p","dlg":false,"html":"돌아오는 길에 소나기가 물었습니다."},{"t":"p","dlg":true,"html":"“어찌 혼자 들어가셨습니까.”"},{"t":"p","dlg":false,"html":"김유신은 앞만 보고 갔습니다. 소나기는 그제야 굴에서 내려오던 날의 말을 알아들었습니다. 제 목숨까지 걸 수 있는 사람인지 알아보러 갔다는 말이었습니다. 그리고 이날 그는 정말로 목숨을 걸었습니다."},{"t":"p","dlg":false,"html":"그 뒤로 도읍에서 그의 집안을 “남쪽에서 들어온 집”이라고 부르는 소리가 눈에 띄게 줄었습니다."}]},{"heading":"별이 떨어진 밤","blocks":[{"t":"p","dlg":false,"html":"김춘추는 예순 날이 조금 지나 돌아왔습니다. 김유신은 군사를 이끌고 한강을 건너 고구려 땅으로 들어섰다가 그 소식을 듣고 되돌아섰습니다."},{"t":"p","dlg":false,"html":"그 뒤 네 해 동안 신라는 서쪽에서 계속 밀렸습니다. 그동안 김유신은 국경을 오르내렸고 김춘추는 바다를 건너다녔습니다."},{"t":"p","dlg":false,"html":"647년 정월이었습니다."},{"t":"p","dlg":false,"html":"나라에서 벼슬아치 가운데 가장 높은 자리에 있던 사람이 군사를 일으켰습니다. 비담이었습니다. 그가 <em class=\"dot\">상대등</em>에 오른 것은 그 두 해 전이었지요."},{"t":"p","dlg":false,"html":"여자 임금은 나라를 잘 다스릴 수 없다는 것이 그가 내건 말이었습니다."},{"t":"p","dlg":false,"html":"비담의 군사는 도읍 동쪽 명활성에 진을 쳤고 임금의 군사는 <em class=\"hint\">월성</em>에 진을 쳤습니다. 두 진영이 열흘을 싸웠지만 끝이 나지 않았습니다."},{"t":"p","dlg":false,"html":"열흘째 되던 밤, 큰 별 하나가 월성 쪽으로 떨어졌습니다."},{"t":"p","dlg":false,"html":"명활성 쪽에서 함성이 올랐습니다. 별이 떨어진 자리에는 반드시 피가 흐르는 법이니 이는 여자 임금이 질 조짐이라는 것이었습니다. 그 소리가 월성 안까지 들렸습니다. 임금의 군사들이 흔들렸습니다."},{"t":"p","dlg":false,"html":"김유신이 임금 앞으로 나아갔습니다."},{"t":"p","dlg":true,"html":"“<em class=\"dot\">길흉</em>은 정해져 있는 것이 아니라 사람이 부르는 것입니다.”"},{"t":"p","dlg":false,"html":"그날 밤 그는 허수아비를 만들어 불을 붙이고 연에 매달아 띄웠습니다. 불덩이가 어둠 속에서 천천히 하늘로 올라갔습니다."},{"t":"illust","n":3,"cap":"불덩이 하나가 어둠 속에서 천천히 하늘로 올라갔습니다","src":"img/web/ep046-plate-3.jpg?v=9326edbc24"},{"t":"p","dlg":false,"html":"이튿날 아침, 어젯밤 떨어졌던 별이 도로 올라갔다는 말이 도읍에 퍼졌습니다. 김유신은 흰 말을 잡아 별이 떨어진 자리에서 제사를 지냈습니다. 이번에는 명활성 쪽이 술렁였습니다."},{"t":"p","dlg":false,"html":"말굽이 그 말을 끌고 갔습니다. 끌고 가면서 아무 말도 하지 않았습니다. 말을 돌보는 사람에게 말을 잡으러 끌고 가는 길은 가벼운 길이 아니었습니다."},{"t":"p","dlg":false,"html":"싸움이 끝나기 전에 임금이 세상을 떠났습니다. 새 임금이 섰는데, 새 임금도 여자 임금이었습니다. 그리고 며칠 뒤 <em class=\"dot\">반란</em>은 끝났습니다. 비담과 그를 따르던 사람들이 죽었습니다."},{"t":"p","dlg":false,"html":"그 뒤 말굽이 물었습니다."},{"t":"p","dlg":true,"html":"“별이 정말 올라갔습니까.”"},{"t":"p","dlg":true,"html":"“사람들이 그렇게 보았다.”"},{"t":"p","dlg":true,"html":"“보게 만드신 거지요.”"},{"t":"p","dlg":false,"html":"김유신은 대답하지 않았습니다."},{"t":"p","dlg":false,"html":"그해 봄, 김유신은 김춘추의 집 마당에서 그와 마주 앉았습니다. 손가락을 깨물던 그 겨울에서 네 해가 지나 있었습니다."},{"t":"p","dlg":true,"html":"“칼은 제가 쥐겠습니다.”"},{"t":"p","dlg":true,"html":"“바깥의 동무는 제가 구해 오지요.”"},{"t":"p","dlg":false,"html":"말굽은 마당 끝에서 고삐를 매만지며 그 말을 등으로 들었습니다. 그날따라 두 집 말이 한 나무에 나란히 매여 있었습니다. 예순 날을 세던 그 겨울의 약속이, 이제 나라의 일을 함께 나누어 지는 약속이 된 것이었습니다."},{"t":"p","dlg":false,"html":"그때부터 신라의 일은 두 사람의 손에 들어왔습니다. 하나는 밖에서 동무를 구해 오는 사람이었고 하나는 안에서 군사를 쥔 사람이었지요. 654년에 김춘추가 신라의 임금이 되었습니다. 뒷날 사람들은 이 임금을 태종 무열왕이라고 부릅니다. 여섯 해 뒤 김유신은 비담이 앉았던 그 자리, 곧 벼슬아치 가운데 가장 높은 자리에 올랐습니다."},{"t":"p","dlg":false,"html":"말굽은 그가 말의 목을 베었다는 이야기를 오래 생각했습니다. 그것이 정말 있었던 일인지는 끝내 알 수 없었지요. 다만 말굽이 아는 것이 하나 있었습니다. 그 사람은 살아오는 동안 여러 번 무엇인가를 끊었다는 것입니다. 남쪽에서 들어온 집안의 아들이 신라의 한복판에 서기까지, 놓아야 하는 것이 그만큼 많았던 것이지요."},{"t":"spot","n":3,"size":"normal","cap":"김춘추와 김유신은 바깥에서 동무를 구하고, 안에서 군사를 쥐는 일을 나눴다","src":"img/web/ep046-spot-3.jpg?v=61a2bb0fac"},{"t":"p","dlg":false,"html":"660년 여름, 그가 오만 군사를 이끌고 서쪽으로 떠났습니다. 말굽이 그의 말을 끌고 나갔습니다. 예순 날을 세던 그 겨울에서 열여덟 해가 지나 있었습니다."}]}],"words":[{"w":"군주","d":"신라에서 한 지방의 군사를 맡아 다스리던 벼슬"},{"w":"진골","d":"신라의 신분 가운데 성골 다음으로 높았던 신분"},{"w":"만노군","d":"지금의 충청북도 진천 자리. 신라가 북쪽 국경을 지키려고 둔 고을이었다"},{"w":"화랑","d":"신라에서 젊은이의 무리를 이끌던 우두머리, 또는 그 무리"},{"w":"상대등","d":"신라에서 벼슬아치 가운데 가장 높은 자리"},{"w":"길흉","d":"좋은 일과 나쁜 일"},{"w":"반란","d":"나라나 임금에 맞서 군사를 일으키는 일"}],"hints":[{"w":"여물","d":"말이나 소에게 먹이는 마른 풀"},{"w":"낭도","d":"화랑을 따르며 함께 배우던 무리"},{"w":"말갈","d":"고구려 북쪽에 살던 사람들"},{"w":"벼리","d":"그물 위쪽에 꿰어 그물을 펴고 오므리는 굵은 줄"},{"w":"갖옷","d":"짐승의 털가죽으로 지은 옷"},{"w":"월성","d":"서라벌에 있던 신라 임금의 궁성"}],"after":{"title":"임금이 아닌 사람에게 붙은 이름","html":["김유신은 673년에 일흔아홉으로 세상을 떠났습니다. 그리고 백오십 해쯤 지난 뒤, 신라의 한 임금이 그를 흥무대왕이라 높여 불렀습니다. 임금이 아니었던 사람에게 「대왕」을 붙인 일은 우리 역사에서 아주 드뭅니다. 지금 경주에는 「경주 김유신묘」라는 이름으로 지정된 무덤이 하나 있는데, 봉분을 두른 돌에 열두 띠 동물이 새겨져 있습니다. 임금의 무덤에나 쓰던 꾸밈이지요. 다만 그 무덤이 정말 그의 것인지를 두고는 지금도 학자들의 말이 갈립니다."]},"ifme":{"q":"어딘가에 제대로 들어가려고 무언가를 끊어야 한다면, 나는 어디까지 끊을 수 있을까?","html":["김유신이 벤 것이 정말 말이었는지는 알 수 없습니다. 그래도 그가 살아오는 동안 여러 번 무엇인가를 놓아야 했다는 것은 분명해 보이지요. 그런데 세상에는 놓지 않아도 되는 것까지 놓아 버리는 사람도 있습니다. 여러분이라면 어디까지 놓을 수 있고, 무엇은 무슨 일이 있어도 놓지 않겠어요? 그렇게 금을 그은 기준까지 함께 말해 보세요. 정답은 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 김유신·김서현·만명·비담은 실제로 있었던 사람이에요. 부모의 혼인을 집안이 반대한 일도, 벼락이 친 밤의 일도, 열다섯에 화랑이 된 일도, 낭비성에서 홀로 적진에 들어간 일도, 647년의 별과 연 이야기도 모두 『삼국사기』 김유신 열전에 적혀 있지요. 그런데 그 열전이 좀 이상합니다. 임금의 일은 「본기」에 적고 임금이 아닌 사람들의 일생은 「열전」에 적는데, 『삼국사기』의 열전은 모두 열 권이고 그 가운데 세 권이 김유신 한 사람이에요. 을지문덕도 계백도 한 권을 여러 사람과 나누어 썼는데 말이지요. 왜 그럴까요. 그 책을 엮은 사람이 까닭을 스스로 적어 두었습니다. 김유신의 사대손이 지은 『행록』 열 권을 바탕으로 삼았는데, 지어 넣은 말이 많아 덜어 내고 썼다는 것이었어요. 반대로 말의 목을 벤 이야기는 『삼국사기』에 아예 없습니다. 말굽도 소나기도 지어낸 사람이에요."]},"quiz":[{"n":1,"kind":"사실 확인","q":"김서현과 만명이 혼인하기까지 어떤 일이 있었나요?","opts":["임금이 두 사람의 혼인을 명하여 집안이 그 뜻을 따랐습니다","만명의 아버지가 딸을 별채에 가두었지만, 벼락이 친 밤에 만명이 빠져나가 김서현에게 갔습니다","두 집안이 오래 가깝게 지내 어른들이 나서서 혼인을 맺어 주었습니다","김서현이 만명의 아버지를 여러 해 설득한 끝에 허락을 받았습니다"],"answer":1,"why":{"0":"임금이 나섰다는 이야기는 어디에도 나오지 않습니다.","2":"만명의 아버지는 이 혼인을 반대했습니다.","3":"두 사람은 허락을 받은 것이 아니라 도읍을 떠나 버렸습니다."},"ref":"그날 밤 벼락이 문간을 때렸고, 지키던 사람이 놀라 흩어진 사이에 만명이 담 구멍으로 빠져나갔습니다.","more":"『삼국사기』 김유신 열전에 그대로 있는 대목이에요. <b>「忽有雷震屋門 守者驚亂 萬明從竇而出」</b>(갑자기 벼락이 집 문간을 때리자 지키던 사람들이 놀라 어지러워졌고, 만명이 구멍으로 빠져나왔다). 만명의 아버지는 숙흘종이라는 왕족이었고, 김서현은 그때 만노군을 맡아 나가는 길이었지요. 같은 열전은 김유신이 어머니 배 속에 스무 달을 있다가 태어났다고 적고, 이름을 지은 내력도 적어 두었어요. 아버지가 경진일 밤 꿈에 별 둘이 내려오는 것을 보아 아이 이름을 「경진」이라 하려다, 날 이름을 사람 이름으로 삼는 것은 예가 아니라 하여 소리가 비슷한 「유신」으로 고쳤다고요."},{"n":2,"kind":"사실 확인","q":"별이 떨어진 뒤에 김유신이 한 일은 무엇이었나요?","opts":["허수아비에 불을 붙여 연에 매달아 하늘로 띄웠습니다","별이 떨어진 자리를 파서 무엇이 떨어졌는지 찾아보았습니다","명활성으로 사람을 보내 싸움을 그만두자고 청했습니다","성문을 열고 밤사이에 군사를 모두 물렸습니다"],"answer":0,"why":{"1":"그 자리를 판 것이 아니라 흰 말을 잡아 제사를 지냈습니다.","2":"싸움을 그만두자고 청한 쪽은 어느 편에도 없었습니다.","3":"그날 밤 월성의 군사는 물러나지 않았습니다."},"ref":"그날 밤 그는 허수아비를 만들어 불을 붙이고 연에 매달아 띄웠습니다.","more":"『삼국사기』는 이렇게 적었어요. <b>「乃造偶人 抱火載於風鳶而颺之 若上天然」</b>(허수아비를 만들어 불을 안기고 연에 실어 띄우니 마치 하늘로 올라가는 것 같았다). 이튿날 「어젯밤 떨어진 별이 도로 올라갔다」는 말을 퍼뜨리게 하여 적의 군사들이 흔들리게 했고, 흰 말을 잡아 별이 떨어진 자리에서 제사를 지냈다는 것도 같은 대목에 있습니다. 연을 이렇게 쓴 기록으로는 우리 역사에서 가장 이른 축에 든답니다."},{"n":3,"kind":"추론","q":"김유신이 불붙인 허수아비를 하늘로 띄워 정말로 바꾸려 한 것은 무엇이었을까요?","opts":["별이 떨어진 자리를 군사들에게 정확히 알려 주는 것","밤에도 앞이 보이도록 싸움터를 밝히는 것","하늘에서 일어난 일이 아니라 그것을 본 사람들의 마음","명활성 쪽 군사들에게 임금의 명령을 알리는 것"],"answer":2,"why":{"0":"별이 어디에 떨어졌는지는 두 진영이 이미 다 보고 있었습니다.","1":"불덩이 하나로 싸움터가 밝아지지도 않을뿐더러, 그는 그날 밤에 싸우려 하지 않았습니다.","3":"명령을 알리려면 사람을 보내면 되지 굳이 불을 하늘에 띄울 까닭이 없습니다."},"ref":"길흉은 정해져 있는 것이 아니라 사람이 부르는 것입니다.","more":"이 말도 『삼국사기』에 그대로 있어요. <b>「吉凶無常 惟人所召」</b>(길흉은 정해진 것이 없고 오직 사람이 부르는 것이다). 김유신은 임금 앞에서 이 말을 하기 전에 옛 중국의 일을 여럿 들었다고 합니다. 나쁜 조짐이 나타났는데도 나라가 잘된 일, 좋은 조짐이 나타났는데도 무너진 일 말이지요. 다만 그가 정말 이렇게 말했는지, 아니면 뒷사람이 이 대목을 다듬어 넣은 것인지는 확인할 길이 없습니다."},{"n":4,"kind":"낱말·표현","q":"본문에 나온 '상대등'은 무엇을 뜻하는 말인가요?","opts":["신라에서 젊은이의 무리를 이끌던 우두머리","신라에서 벼슬아치 가운데 가장 높은 자리","신라의 신분 가운데 성골 다음으로 높았던 신분","신라에서 한 지방의 군사를 맡아 다스리던 벼슬"],"answer":1,"why":{"0":"그것은 화랑입니다.","2":"그것은 진골입니다.","3":"그것은 군주입니다."},"ref":"나라에서 벼슬아치 가운데 가장 높은 자리에 있던 사람이 군사를 일으켰습니다.","more":"상대등은 법흥왕 때인 531년에 처음 둔 자리로, 신라에서 임금 다음가는 자리였어요. 비담이 여기에 오른 것은 645년 겨울이고 군사를 일으킨 것은 그 이듬해 정월이니 한 해 남짓 만의 일이지요. 나라에서 가장 높은 자리에 오른 사람이 왜 군사를 일으켰는지, 그 진짜 까닭은 옛 책에 적혀 있지 않습니다. 학자들은 그 무렵 밖에서 밀리던 신라 안에서 여러 세력이 부딪친 것으로 봅니다."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 『삼국사기』 열전 열 권 가운데 세 권이 김유신 한 사람에게 돌아간 까닭은 무엇일까요?","opts":["『삼국사기』를 엮은 사람이 김유신의 먼 자손이었기 때문에","김유신 말고는 열전에 실을 만한 사람이 남아 있지 않았기 때문에","신라 임금들의 이야기가 열전에 실리지 못했기 때문에","김유신의 집안이 남긴 『행록』 열 권이 그 세 권의 바탕이 되었기 때문에"],"answer":3,"why":{"0":"두 사람이 한집안이라는 이야기는 어디에도 없습니다.","1":"을지문덕과 계백을 비롯해 여러 사람이 나머지 일곱 권에 실려 있습니다.","2":"임금의 일은 본기에 따로 실렸습니다. 열전은 본디 임금이 아닌 사람을 적는 곳입니다."},"ref":"김유신의 사대손이 지은 『행록』 열 권을 바탕으로 삼았는데, 지어 넣은 말이 많아 덜어 내고 썼다는 것이었어요.","more":"『삼국사기』를 엮은 김부식이 김유신 열전 끝에 이렇게 적었어요. <b>「庾信玄孫新羅執事郞長淸 作行錄十卷 行於世 頗多釀辭 故刪落之 取其可書者 爲之傳」</b>(유신의 현손인 신라 집사랑 장청이 『행록』 열 권을 지어 세상에 퍼졌는데, 지어 넣은 말이 자못 많으므로 그것을 깎아 내고 쓸 만한 것만 취해 전을 지었다). 「현손」은 사대손, 그러니까 고손자예요. 『행록』 열 권은 지금 남아 있지 않습니다. 반대로 이 편의 제목이 된 말 이야기는 『삼국사기』에도 『삼국유사』에도 없어요. 그 이야기가 글로 남은 것은 조선 시대에 엮은 지리책 『신증동국여지승람』의 경주 천관사 항목이고, 김유신이 죽고 팔백 해도 더 지난 뒤랍니다. 그 사이 팔백 년 동안 이 이야기가 어디서 생겨났는지는 아무도 모릅니다. 그러니 「지어낸 것이다」라고도 「있었던 일이다」라고도 말할 수 없어요. <b>「모른다」가 가장 정직한 답</b>인 자리가 이렇게 있답니다."}],"summary":["김유신은 백여 년 전 신라에 들어온 남쪽 나라 임금의 후손이었어요. 아버지 김서현과 어머니 만명은 집안의 반대를 무릅쓰고 도읍을 떠났고, 595년 김유신은 그 먼 고을에서 태어났답니다.","열다섯에 화랑이 되었고 서른다섯에 낭비성 싸움에서 홀로 적진에 들어가 이름을 얻었어요. 그가 자기 말의 목을 베었다는 이야기는 훨씬 뒷날의 책에만 나온답니다.","647년 비담이 여자 임금은 나라를 잘 다스릴 수 없다며 군사를 일으켰을 때, 김유신은 불붙인 허수아비를 연에 매달아 띄워 떨어진 별이 도로 올라간 것처럼 보이게 했어요."],"bait":["두 사람이 손을 잡자 신라가 움직였습니다. 당의 배가 서해를 건너오고 신라의 오만이 동쪽에서 넘어옵니다. 그 사이 벌판에 <span class=\"blur\">오천 명</span>이 서 있었지요. 그 오천은 무엇을 하려던 것이었을까요……"]};

;
(window.EPS ||= {})[47] = {"no":47,"chapter":"2장 세 나라의 시대","when":"660년","read":"읽기 16~18분","ago":"약 1,360년 전","title":"오천 명은 무엇을 하려고 벌판에 섰을까","subtitle":"이길 수 있는 수가 아니었습니다. 그런데도 오천은 그 벌판에 섰습니다","intro":"오늘 이야기의 무대는 <b>백제</b>예요. 한강 가에서 일어나 웅진과 사비로 도읍을 옮겨 가며 육백 년 넘게 이어 온 나라였지요. 660년 여름, 그 나라에 군사가 두 갈래로 밀려들었어요. 서쪽 바다로는 <b>당</b>의 배가 들어오고 동쪽 고개로는 <b>신라</b>의 군사가 넘어왔지요. 그 사이 벌판에 오천 명이 섰습니다. 오천으로는 막을 수 없는 싸움이었어요. 그렇다면 그 오천은 무엇을 하려고 거기 섰을까요? 그 가운데 한 사람을 따라가며 알아볼까요?","acts":[{"heading":"막을 곳은 두 군데였다","blocks":[{"t":"p","dlg":false,"html":"그해 여름, 사비의 궁궐 마당에 신하들이 모였습니다."},{"t":"p","dlg":false,"html":"사비는 백제의 도읍이었습니다. <em class=\"hint\">사비하</em>가 성을 크게 감아 돌았고, 그 물길로 바다에서 배가 드나들었습니다."},{"t":"p","dlg":false,"html":"임금은 의자왕이었습니다. 젊을 적에 사람들은 그를 「해동증자」라고 불렀습니다. 바다 동쪽의 증자라는 뜻인데, 증자는 아주 먼 옛날 중국에서 효성으로 이름났던 사람입니다. 어버이를 정성으로 섬기고 형제와 사이가 좋다고 해서 붙은 이름이었지요. 임금이 된 뒤에는 몸소 군사를 이끌고 나가 신라의 성 마흔 곳을 빼앗기도 했습니다. 열여덟 해 전 일이었습니다."},{"t":"p","dlg":false,"html":"그러니 그해 여름 마당에 모인 사람들이 겁을 먹은 것은 임금이 약해서가 아니었습니다. 오는 군사가 너무 많아서였습니다."},{"t":"p","dlg":false,"html":"옛 책은 서쪽 바다로 온 당의 군사를 십삼만이라고 적었습니다. 동쪽에서 넘어온 신라의 군사는 오만이라고 적었고요."},{"t":"p","dlg":false,"html":"신하들의 말이 갈렸습니다. 당과 먼저 싸우자는 사람이 있었고, 당의 길을 막아 두고 신라부터 치자는 사람이 있었습니다. 임금은 어느 쪽도 고르지 못했습니다."},{"t":"p","dlg":false,"html":"그때 누가 흥수의 이름을 꺼냈습니다."},{"t":"p","dlg":false,"html":"흥수는 <em class=\"hint\">좌평</em>을 지낸 사람인데, 죄를 얻어 먼 고을로 <em class=\"dot\">유배</em>를 가 있었습니다."},{"t":"p","dlg":false,"html":"사람을 보내 묻자 흥수가 답을 보내왔습니다."},{"t":"p","dlg":true,"html":"“백강과 탄현은 우리나라의 목입니다. 한 사람이 창을 들고 서면 만 사람이 지나지 못하는 곳이지요.”"},{"t":"p","dlg":false,"html":"바다에서 들어오는 물길과 동쪽에서 넘어오는 고갯길이 거기서 좁아졌습니다. 목을 잡히면 몸이 꼼짝 못 하듯, 나라가 반드시 지켜야 할 <em class=\"dot\">요충지</em>라는 말이었습니다."},{"t":"p","dlg":true,"html":"“그 두 곳을 막고 성문을 굳게 닫으십시오. 저들의 <em class=\"hint\">양식</em>이 떨어지고 군사가 지친 뒤에 치면 됩니다.”"},{"t":"p","dlg":false,"html":"마당의 신하들은 그 말을 믿지 않았습니다."},{"t":"p","dlg":true,"html":"“오래 갇혀 있던 사람입니다. 임금을 원망하고 있을 터인데 그 말을 어찌 쓰겠습니까.”"},{"t":"p","dlg":false,"html":"말이 오가는 동안 날이 갔습니다. 그러다 소식이 들어왔습니다. 당의 배는 이미 백강을 지났고, 신라의 군사는 이미 탄현을 넘었다는 것이었습니다."},{"t":"p","dlg":false,"html":"막을 곳 두 군데를 다 지나 보낸 뒤였습니다. 이제 두 나라의 군사는 막아서는 것 없이 사비를 향해 오고 있었습니다."},{"t":"spot","n":1,"size":"large","cap":"당의 배와 신라 군사가 좁은 물길과 고개를 지나자, 사비로 오는 길이 열렸다","src":"img/web/ep047-spot-1.jpg?v=e3393c02eb"},{"t":"p","dlg":false,"html":"임금이 사람을 불렀습니다. 계백이었습니다."},{"t":"p","dlg":false,"html":"계백은 <em class=\"dot\">달솔</em>이라는 벼슬에 있었습니다. 옛 책은 그의 아버지가 누구인지도, 그가 어디서 났는지도 적어 두지 않았습니다. 그가 마지막 여름에 무엇을 했는지만 적어 두었지요."},{"t":"p","dlg":false,"html":"계백에게 준 군사는 오천이었습니다."},{"t":"p","dlg":false,"html":"들메는 그 오천 가운데 하나였습니다. 사비에서 하루쯤 걸어 올라간 마을에서 왔고, 논 몇 <em class=\"hint\">뙈기</em>와 늙은 어머니를 두고 왔습니다. 창을 잡아 본 것은 처음이 아니었지만 이렇게 적은 수로 나가 보기는 처음이었습니다."},{"t":"spot","n":2,"size":"normal","cut":true,"width":720,"height":900,"cap":"들메는 논과 늙은 어머니를 두고, 급히 모인 백제 군사 오천 가운데 하나가 되었다","src":"img/web/ep047-spot-2.png?v=10e576b7fa"},{"t":"p","dlg":true,"html":"“우리가 몇입니까.” 들메가 물었습니다."},{"t":"p","dlg":true,"html":"“오천이다. 이렇게 급하게 모을 수 있는 것이 이만큼이었다.”"},{"t":"p","dlg":true,"html":"“저쪽은요.”"},{"t":"p","dlg":false,"html":"대답이 없었습니다. 저쪽이 열 배라는 것을 다들 알았지만 아무도 입 밖에 내지 않았습니다. 그래도 돌아서는 사람은 없었습니다. 처음부터 목숨을 내놓고 나선 <em class=\"dot\">결사대</em>였습니다. 옛 책도 계백이 죽을 각오를 한 군사 오천을 골라 뽑았다고 적었습니다."},{"t":"p","dlg":false,"html":"떠나기 전에 계백에게 있었던 일을 옛 책은 아주 짧게 적어 두었습니다. 그는 제 <em class=\"hint\">처자</em>를 제 손으로 죽였습니다. 살아서 남의 종이 되게 하느니 그편이 낫다고 여겼다는 것입니다."},{"t":"p","dlg":false,"html":"그때 사람들은 그 일을 나라를 위한 일로 여겼습니다. 그러나 오늘 우리는 어떤 까닭으로도 그것을 옳다고 하지 않습니다. 지키려던 것이 무엇이었든, 죽인 것은 죽인 것입니다."},{"t":"p","dlg":false,"html":"들메는 그 이야기를 길에서 들었습니다. 아무도 두 번 말하지 않았습니다. 군사들은 그 이야기를, 장군이 이 싸움에서 살아 돌아올 생각이 없다는 뜻으로 알아들었습니다."}]},{"heading":"네 번 물러난 군대","blocks":[{"t":"p","dlg":false,"html":"곰소는 황산벌 마을의 아이였습니다."},{"t":"p","dlg":false,"html":"열한 살이었고 벌판 끝자락 마을에 살았습니다. 여름이면 콩밭에 물을 대고 가을이면 새를 쫓았습니다."},{"t":"p","dlg":false,"html":"그해 칠월, 콩밭 너머로 사람들이 왔습니다."},{"t":"p","dlg":false,"html":"먼저 온 것은 백제 군사였습니다. 험한 자리를 골라 세 군데에 나누어 <em class=\"dot\">진영</em>을 쳤습니다."},{"t":"p","dlg":false,"html":"곰소는 그 진영을 세어 보았습니다. 하나, 둘, 셋. 그것이 전부였습니다."},{"t":"p","dlg":true,"html":"“저리 험한 데를 골라 앉았으니, 수가 많아도 한꺼번에는 못 덤비지.”"},{"t":"p","dlg":false,"html":"마을 어른 하나가 중얼거렸습니다."},{"t":"p","dlg":false,"html":"이튿날 아침에는 동쪽 산을 넘어 신라 군사가 들어왔습니다. 곰소는 세다가 그만두었습니다."},{"t":"illust","n":1,"cap":"오천 명이 벌판에 세 군데로 나뉘어 진을 쳤습니다","src":"img/web/ep047-plate-1.jpg?v=b8868daaad"},{"t":"p","dlg":false,"html":"가온도 그 안에 있었습니다."},{"t":"p","dlg":false,"html":"가온은 스물여덟이었습니다. 열여덟 해 전 대야성이 무너지던 밤, 어머니가 등을 밀어 성 밖으로 내보낸 아이였지요. 어머니는 성에 남았습니다. 그 성에서 붙들린 사람들이 백제 땅 여러 고을로 옮겨졌다는 말만 들었고, 그 뒤로는 아무 소식도 없었습니다."},{"t":"p","dlg":false,"html":"가온은 백제라는 말을 들으면 다른 생각을 하지 못하는 사람으로 자랐습니다. 그래서 창을 잡았고, 그래서 이 벌판까지 왔습니다."},{"t":"p","dlg":false,"html":"신라 군사를 이끈 사람은 김유신이었습니다. 그해 예순여섯이었습니다."},{"t":"p","dlg":false,"html":"싸움이 시작되었습니다."},{"t":"p","dlg":false,"html":"신라 군사가 밀고 들어갔다가 물러났습니다. 다시 들어갔다가 또 물러났습니다. 세 번째도 그랬고 네 번째도 그랬습니다."},{"t":"p","dlg":false,"html":"곰소는 그것을 마을 뒷등성이에서 보았습니다. 벌판 가운데의 작은 덩어리가 자꾸 커다란 덩어리를 밀어냈습니다."},{"t":"p","dlg":false,"html":"가온은 그 큰 덩어리 안에 있었습니다. 물러날 때마다 곁의 사람이 줄었습니다."},{"t":"p","dlg":false,"html":"신라가 당의 대장군과 만나기로 한 날은 칠월 열흘이었습니다. 두 나라 군사가 만나 함께 사비를 치기로 한 날이었습니다. 그날이 하루밖에 남지 않았는데 벌판은 아직 열리지 않았습니다. 늦으면 신라가 당의 대장군 앞에서 약속을 어긴 꼴이 될 판이었습니다."},{"t":"p","dlg":false,"html":"그날 신라 진영에서 한 장군이 제 아들을 불렀습니다. 아들은 말에 올라 혼자 백제 진영으로 달려 들어갔고, 돌아오지 못했습니다."},{"t":"p","dlg":false,"html":"그다음에 불려 나온 것이 관창이었습니다. 또 다른 장군의 아들이었습니다."},{"t":"p","dlg":false,"html":"관창은 열여섯 살이었습니다. 어려서부터 <em class=\"dot\">화랑</em>의 무리에서 몸과 마음을 닦아 온 소년이었습니다."},{"t":"p","dlg":false,"html":"아버지가 말했습니다."},{"t":"p","dlg":true,"html":"“너는 나이가 어리지만 뜻이 굳다. 오늘이 이름을 세울 때다. 어찌 용기가 없겠느냐.”"},{"t":"p","dlg":false,"html":"관창이 대답했습니다."},{"t":"p","dlg":true,"html":"“예.”"},{"t":"p","dlg":false,"html":"그러고는 말에 올라 창을 비껴들고 백제 진영으로 달려 들어갔습니다."},{"t":"p","dlg":false,"html":"가온은 그것을 보았습니다. 아이가 지나간 자리로 흙먼지가 길게 일었습니다."},{"t":"p","dlg":false,"html":"관창은 사로잡혀 계백 앞으로 끌려갔습니다."},{"t":"p","dlg":false,"html":"계백이 투구를 벗겨 보라고 했습니다. 아이 얼굴이 나왔습니다."},{"t":"p","dlg":false,"html":"계백은 한참 있다가 말했습니다."},{"t":"p","dlg":true,"html":"“신라에는 기이한 사람이 많구나. 소년이 이러한데 하물며 <em class=\"hint\">장사</em>들이야.”"},{"t":"p","dlg":false,"html":"그러고는 관창을 살려서 돌려보냈습니다. 어리고 굳센 것이 아까워 차마 해치지 못한 것이었습니다."},{"t":"p","dlg":false,"html":"관창은 제 진영으로 돌아왔습니다. 그리고 우물가로 가서 두 손으로 물을 움켜 마셨습니다."},{"t":"p","dlg":true,"html":"“아까는 장수도 베지 못하고 깃발도 빼앗지 못했습니다. 다시 들어가면 됩니다.”"},{"t":"p","dlg":false,"html":"아무도 그를 붙잡지 않았습니다."},{"t":"illust","n":2,"cap":"열여섯 살 화랑이 다시 말에 오르고 있습니다","src":"img/web/ep047-plate-2.jpg?v=c0f068110a"},{"t":"p","dlg":false,"html":"관창은 다시 말에 올랐고, 그 벌판에서 돌아오지 못했습니다."},{"t":"p","dlg":false,"html":"그다음에 벌어진 일을 옛 책은 이렇게 적었습니다. 온 군사가 그것을 보고 죽기를 마음먹고 북을 치며 나아가니 백제가 크게 졌다고요. 가온도 그 북소리에 섞여 달려 나갔습니다."},{"t":"p","dlg":false,"html":"오천은 그때까지 네 번을 이겼습니다. 다섯 번째에 무너졌습니다."},{"t":"p","dlg":false,"html":"계백은 그 벌판에서 죽었습니다. 들메도 돌아오지 못했습니다."},{"t":"p","dlg":false,"html":"이튿날 아침에 곰소가 등성이에서 내려왔을 때 벌판에는 아무도 없었습니다. 군사들은 서쪽으로 갔습니다. 사비 쪽이었습니다."}]},{"heading":"배가 떠나던 날","blocks":[{"t":"p","dlg":false,"html":"벌판이 열린 것은 칠월 아흐렛날이었습니다."},{"t":"p","dlg":false,"html":"같은 날 당의 배도 강어귀에서 백제 군사를 밀어냈습니다."},{"t":"p","dlg":false,"html":"그런데 신라 군사가 당의 진영에 닿았을 때는 만나기로 한 날이 지나 있었습니다. 신라 군사가 늦은 것은 황산벌에서 오천에게 발이 묶였기 때문이었습니다. 그러나 당의 대장군은 약속에 늦었다며 신라 장수 하나의 목을 베려 했습니다."},{"t":"p","dlg":false,"html":"김유신이 제 군사들을 돌아보며 말했습니다."},{"t":"p","dlg":true,"html":"“저 사람은 황산의 싸움을 보지 않았소. 날 늦은 것만 죄로 삼는구려. 죄 없이 욕을 볼 수는 없소.”"},{"t":"p","dlg":false,"html":"그러고는 도끼를 들고 <em class=\"hint\">군문</em> 앞에 가서 섰습니다. 곁에 있던 당의 장수 하나가 대장군에게 신라 군사가 변을 일으키려 한다고 일러 주었고, 대장군은 그제야 신라 장수의 죄를 풀어 주었습니다."},{"t":"p","dlg":false,"html":"계백이 무엇을 하려고 그 벌판에 섰는지는 옛 책이 적어 두지 않았습니다. 다만 오천이 한 일은 남았습니다. 오천은 이기지 못했습니다. 대신 하루를 벌었고, 그 하루가 손을 잡고 온 두 나라를 서로 칼을 겨누게 할 뻔했습니다."},{"t":"p","dlg":false,"html":"두 군대는 곧 사비 성문 앞에서 만났습니다."},{"t":"p","dlg":false,"html":"임금은 밤에 성을 나가 웅진으로 갔습니다. 백제가 예전에 한 번 도읍으로 삼았던 성이었습니다."},{"t":"p","dlg":false,"html":"사비에 남은 사람들이 성문을 열었습니다. 열여드렛날에는 임금도 웅진에서 나와 항복했습니다."},{"t":"p","dlg":false,"html":"백제가 한강 가에 처음 섰다고 전해 오는 해로부터 육백일흔 해가 넘은 뒤였습니다."},{"t":"p","dlg":false,"html":"당은 백제 땅을 다섯으로 나누어 제 관청을 두었습니다. 나라 하나가 있던 자리에 남의 관청 다섯이 선 것이지요."},{"t":"spot","n":3,"size":"normal","cap":"백제가 무너진 뒤 당은 그 땅을 다섯으로 나누고, 제 관청을 두어 다스렸다","src":"img/web/ep047-spot-3.jpg?v=b660830b9b"},{"t":"p","dlg":false,"html":"가을에 배가 떴습니다."},{"t":"p","dlg":false,"html":"당의 대장군은 의자왕과 왕자들과 벼슬아치들을 배에 태웠습니다. 백성들도 함께 태웠습니다. 옛 책은 그 백성의 수를 만 이천여 명이라고 적었습니다. 싸움에 진 나라의 임금과 백성이 <em class=\"dot\">포로</em>가 되어 남의 나라로 끌려가는 것이었습니다."},{"t":"p","dlg":false,"html":"가온은 그 나루에 서 있었습니다."},{"t":"p","dlg":false,"html":"지키러 간 것이 아니었습니다. 줄을 보러 간 것이었습니다."},{"t":"p","dlg":false,"html":"열여덟 해 전 대야성에서 붙들린 사람들이 백제 땅 여러 고을로 옮겨졌다고 했으니, 그 사람들이 아직 이 땅 어디엔가 있을 것이었습니다. 그 가운데 어머니가 있을지도 몰랐습니다."},{"t":"p","dlg":false,"html":"가온은 줄을 따라 걸으며 얼굴을 하나씩 보았습니다. 아침부터 해가 기울 때까지 보았습니다."},{"t":"illust","n":3,"cap":"사비의 나루에서 배가 사람들을 싣고 떠납니다","src":"img/web/ep047-plate-3.jpg?v=c4a6a346fe"},{"t":"p","dlg":false,"html":"찾지 못했습니다."},{"t":"p","dlg":false,"html":"줄에 선 사람들은 짐을 이고 아이를 업고 있었습니다. 우는 사람도 있었고 아무 소리도 내지 않는 사람도 있었습니다. 가온은 그 줄이 어디서 본 줄인지 알았습니다. 열여덟 해 전, 제 어머니도 저런 줄에 섰을 것이었습니다."},{"t":"p","dlg":false,"html":"그날 가온은 처음으로 백제 사람의 얼굴을 하나하나 보았습니다."},{"t":"p","dlg":false,"html":"곰소도 그 나루에 있었습니다. 마을이 비어 어른들을 따라 강가까지 내려온 참이었습니다."},{"t":"p","dlg":false,"html":"곰소는 배가 강을 내려가는 것을 끝까지 보았습니다. 배는 작아지다가 보이지 않게 되었습니다."},{"t":"p","dlg":true,"html":"“저 사람들은 어디로 가요?”"},{"t":"p","dlg":false,"html":"곁에 선 어른이 대답했습니다."},{"t":"p","dlg":true,"html":"“바다 건너.”"},{"t":"p","dlg":true,"html":"“언제 와요?”"},{"t":"p","dlg":false,"html":"어른은 대답하지 않았습니다. 돌아온다고 말해 줄 수 없었기 때문입니다."},{"t":"p","dlg":false,"html":"나라가 없어진다는 것은 그런 것이었습니다. 성이 무너지고 임금이 붙들리는 데는 열흘이 걸리지 않았습니다. 그런데 배에 오른 사람들이 그 뒤 어떻게 되었는지는 옛 책에 한 줄도 없습니다. 만 이천여 명이라고 수는 적어 두었으면서, 이름은 임금과 그 아들들 것만 적어 두었지요."},{"t":"p","dlg":false,"html":"가온은 서라벌로 돌아갔습니다. 백제라는 말을 들으면 여전히 가슴이 뜨거워졌습니다. 다만 이제는 그 말 뒤에 얼굴들이 따라왔습니다. 나루에서 본 얼굴들이었습니다."}]}],"words":[{"w":"유배","d":"죄를 지은 사람을 먼 곳으로 보내 지내게 하던 벌"},{"w":"요충지","d":"싸움에서 반드시 지켜야 하는 중요한 길목"},{"w":"달솔","d":"백제의 벼슬 이름. 가장 높은 좌평 바로 다음가는 자리였다"},{"w":"결사대","d":"죽기를 각오하고 싸우려고 뽑은 군사"},{"w":"진영","d":"군사들이 머물며 지키는 자리"},{"w":"화랑","d":"신라에서 젊은이들을 모아 몸과 마음을 닦게 하던 무리. 또는 그 무리의 우두머리"},{"w":"포로","d":"싸움에서 사로잡혀 끌려가는 사람"}],"hints":[{"w":"사비하","d":"사비를 감아 흐르는 강. 오늘날 백마강이라 부르는 금강의 한 부분"},{"w":"좌평","d":"백제에서 가장 높은 벼슬"},{"w":"양식","d":"먹고 살 곡식"},{"w":"뙈기","d":"논밭을 나눈 작은 구역"},{"w":"처자","d":"아내와 자식"},{"w":"장사","d":"힘이 세고 용감한 사람"},{"w":"군문","d":"군대 진영의 문"}],"after":{"title":"남의 땅에 묻힌 임금","html":["의자왕은 그해 가을 배에서 내려 당의 서울에 닿았고, 얼마 지나지 않아 병으로 세상을 떠났습니다. 당의 황제는 그에게 벼슬을 내려 주고 옛 백제 신하들이 가서 곡하는 것을 허락했습니다. 그러고는 손호와 진숙보의 무덤 곁에 묻고 비를 세우게 했지요. 손호와 진숙보는 둘 다 나라를 잃은 임금이었습니다. 나라를 잃은 임금들끼리 나란히 눕힌 셈입니다. 그 무덤이 어디인지는 오늘까지도 찾지 못했습니다. 다만 함께 끌려간 아들 부여융의 무덤에서 나온 돌에 글이 새겨져 있어서, 이 집안이 그 뒤 어떻게 살았는지를 조금 알려 줍니다."]},"ifme":{"q":"어른들이 열여섯 살에게 앞장서라고 할 때, 그 아이는 무엇을 할 수 있었을까요?","html":["관창은 “예”라고 대답했습니다. 그 자리에는 아버지가 있었고 장군들이 있었고 네 번을 물러난 군사 오만이 있었습니다. 거기서 “싫습니다”라고 말할 수 있었을까요. 오늘 우리는 열여섯 살을 어른이라고 부르지 않습니다. 그런데 그 벌판에서는 열여섯 살이 맨 앞에 섰지요. 그렇다면 이 이야기를 읽고 물어야 할 것은 “관창이 용감했는가”가 아니라 “어른들은 왜 아이를 보냈는가”일지도 모릅니다. 여러분이 그 진영에 선 어른 가운데 하나였다면 무엇을 했을까요? 정답은 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 계백과 의자왕, 김유신과 관창은 모두 실제로 있었던 사람이에요. 660년에 당과 신라가 함께 백제를 친 일, 계백이 오천을 이끌고 황산벌에서 네 번을 이겼다가 다섯 번째에 무너진 일, 사비성이 열리고 임금이 배에 실려 간 일은 모두 『삼국사기』에 적혀 있지요. 계백이 떠나기 전에 제 처자를 죽였다는 대목도 그 책 계백 열전에 그대로 있어요. 다만 옛 책에 적혀 있다는 것과 그 일이 옳다는 것은 서로 다른 이야기랍니다. 그리고 어디선가 들었을 「삼천궁녀」는 어느 옛 책에도 없어요. 『삼국유사』는 궁녀들이 바위에서 떨어졌다는 이야기를 적으면서 곧바로 항간의 말이 잘못 전해진 것이라 밝히고, 임금은 당에서 죽었다고 못 박습니다. 그 나라가 왜 무너졌는지를 두고 학자들의 풀이는 오늘도 하나로 모이지 않습니다. 들메와 곰소, 가온은 지어낸 사람이에요."]},"quiz":[{"n":1,"kind":"사실 확인","q":"먼 고을에 가 있던 흥수가 백제 조정에 일러 준 것은 무엇이었나요?","opts":["신라와 먼저 화해하고 당을 함께 막아야 한다는 것","도읍을 사비에서 웅진으로 서둘러 옮겨야 한다는 것","백강과 탄현을 막고 성문을 굳게 닫은 채 기다려야 한다는 것","당에 사신을 보내 군사를 물려 달라고 빌어야 한다는 것"],"answer":2,"why":{"0":"신하들의 말은 당과 신라 가운데 어느 쪽과 먼저 싸울지를 두고 갈렸지, 화해를 말한 사람은 없었습니다.","1":"임금이 웅진으로 간 것은 사비성이 열리기 직전이었고, 흥수가 권한 일이 아닙니다.","3":"흥수가 말한 것은 사신이 아니라 두 길목을 지키는 일이었습니다."},"ref":"그 두 곳을 막고 성문을 굳게 닫으십시오.","more":"『삼국사기』 백제본기 의자왕 20년 조에 흥수의 말이 그대로 있어요. <b>「백강과 탄현은 우리나라의 요충지라, 한 사람이 창 하나를 들면 만 사람이 당해 내지 못합니다(白江炭峴 我國之要路也 一夫單槍 萬人莫當)」</b>. 그런데 신하들은 <b>「흥수는 오래 갇혀 있어 임금을 원망하고 나라를 아끼지 않으니 그 말을 쓸 수 없다」</b>고 했지요. 넉 해 전에도 성충이라는 신하가 옥에서 거의 같은 말을 글로 올린 적이 있었어요. 성문이 열리던 날 임금이 <b>「성충의 말을 쓰지 않아 이 지경에 이르렀구나」</b> 하고 뉘우쳤다는 대목도 같은 책에 적혀 있답니다."},{"n":2,"kind":"사실 확인","q":"사로잡혀 끌려온 관창을 보고 계백은 어떻게 했나요?","opts":["아이 얼굴을 보고는 살려서 돌려보냈습니다","신라 군사에게 항복을 권하는 글을 들려 보냈습니다","신라 진영에 사람을 보내 곡식과 바꾸자고 했습니다","백제 진영에 남겨 두고 말을 돌보게 했습니다"],"answer":0,"why":{"1":"계백이 관창 편에 보낸 것은 글이 아니라 감탄하는 말 한마디뿐이었습니다.","2":"사람과 곡식을 바꾸자는 말은 이 이야기에 나오지 않습니다.","3":"관창은 백제 진영에 남지 않고 제 진영으로 돌아와 우물물을 마셨습니다."},"ref":"그러고는 관창을 살려서 돌려보냈습니다.","more":"『삼국사기』 관창 열전은 계백이 투구를 벗기게 하고 그 어리고 용감함을 아껴 차마 해치지 못했다고 적으면서 그의 말을 남겼어요. <b>「신라에는 기이한 선비가 많구나. 소년이 오히려 이러한데 하물며 장사들이랴(新羅多奇士 少年尙如此 況壯士乎)」</b>. 그런데 같은 책 신라본기에는 계백의 말이 조금 다르게 <b>「신라를 대적할 수 없겠구나」</b>로 적혀 있어요. 한 권의 책 안에서도 같은 순간이 두 가지로 적히는 자리가 이렇게 있답니다. 관창보다 먼저 적진으로 들어간 소년의 이름은 반굴이고, 그 아버지도 그 자리에 있던 장군이었어요."},{"n":3,"kind":"추론","q":"신라 어른들이 열여섯 살 아이를 두 번이나 적진으로 들여보낸 데서, 그때 신라 군사의 형편을 어떻게 짐작할 수 있을까요?","opts":["신라에 싸울 어른이 남아 있지 않아 아이들만 있었다는 것","네 번을 싸우고도 벌판을 열지 못해 신라 군사들이 지쳐 있었다는 것","신라가 백제 군사보다 수가 적어 몰래 기습할 수밖에 없었다는 것","백제 군사가 아이를 보면 싸움을 그만두는 관습이 있었다는 것"],"answer":1,"why":{"0":"신라 군사는 오만이었고, 관창을 보낸 것도 어른 장군들이었습니다.","2":"수가 적은 쪽은 오천이었던 백제였습니다.","3":"계백이 관창을 돌려보낸 것은 관습 때문이 아니라 그가 어리고 용감했기 때문입니다."},"ref":"그날이 하루밖에 남지 않았는데 벌판은 아직 열리지 않았습니다.","more":"『삼국사기』 신라본기는 군문 앞의 그 장면을 꽤 자세히 적어 두었어요. 김부식은 김유신이 도끼를 잡고 서자 <b>「성난 머리털이 곧추서고 허리에 찬 보검이 저절로 칼집에서 튀어나왔다(怒髮如植 腰間寶劒 自躍出鞘)」</b>고 썼습니다. 그러자 당의 부하 장수가 소정방의 발을 밟으며 신라 군사가 변을 일으키려 한다고 일러 주었고, 소정방이 곧 그 신라 장수의 죄를 풀어 주었다고 하지요. 옛 책이 사람의 성난 모습을 이렇게까지 적는 일은 드물어요. 그만큼 그 하루가 아슬아슬했다는 뜻이랍니다."},{"n":4,"kind":"낱말·표현","q":"본문에 나온 '결사대'는 무엇을 뜻하는 말인가요?","opts":["싸움에서 사로잡혀 끌려가는 사람","군사들이 머물며 지키는 자리","죽기를 각오하고 싸우려고 뽑은 군사","싸움에서 반드시 지켜야 하는 중요한 길목"],"answer":2,"why":{"0":"그것은 본문에서 포로라고 부른 것입니다.","1":"그것은 본문에서 진영이라고 부른 것입니다.","3":"그것은 본문에서 요충지라고 부른 것입니다."},"ref":"옛 책도 계백이 죽을 각오를 한 군사 오천을 골라 뽑았다고 적었습니다.","more":"『삼국사기』 계백 열전의 원문은 <b>「죽을 각오를 한 군사 오천 명을 골라 막았다(簡死士五千人以拒之)」</b>예요. 계백은 그 오천에게 이렇게 말했다고 합니다. <b>「옛날 구천은 오천 명으로 오나라 칠십만 군사를 깨뜨렸다(昔句踐以五千人 破吳七十萬衆)」</b>. 구천은 아주 먼 옛날 중국에서 적은 군사로 큰 나라를 이겼다는 임금이에요. 그리고 열전은 신라군과 <b>네 번 맞붙었다(四合)</b>고 적습니다. 다만 오천이 정확한 수인지는 아무도 모릅니다. 옛 책의 군사 수는 어림수이거나 부풀려진 때가 많거든요."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 백제가 무너진 까닭을 임금 한 사람의 잘못으로만 말할 수 없는 까닭은 무엇일까요?","opts":["백제가 실제로는 그 뒤로도 아무 일 없이 이어졌기 때문입니다","옛 책에 백제가 무너진 해가 적혀 있지 않기 때문입니다","의자왕이 그해 여름에 도읍에 없었기 때문입니다","여러 가지 일이 겹쳤고, 학자들의 풀이도 아직 하나로 모이지 않기 때문입니다"],"answer":3,"why":{"0":"사비성이 열리고 임금이 배에 실려 갔다는 것이 이 편의 이야기입니다.","1":"옛 책은 달과 날짜까지 적어 두었습니다.","2":"임금은 사비 궁궐에서 신하들과 의논하고 있었습니다."},"ref":"그 나라가 왜 무너졌는지를 두고 학자들의 풀이는 오늘도 하나로 모이지 않습니다.","more":"『삼국사기』 백제본기의 마지막 해에는 이상한 일들이 줄지어 적혀 있어요. 우물물이 핏빛이 되고, 두꺼비 수만 마리가 나무에 모이고, 귀신이 궁궐에 들어와 <b>「백제가 망한다」</b>고 외치고는 땅으로 들어갔다는 식이지요. 땅을 파니 거북이 나왔는데 등에 <b>「백제는 둥근 달과 같고 신라는 초승달과 같다(百濟同月輪 新羅如月新)」</b>고 적혀 있었다고도 합니다. 학자들은 이런 기사들을 <b>나라가 무너진 뒤에 덧붙여진 것으로 보기도 해요.</b> 이긴 쪽이 뒤늦게 적으면 무너질 나라에는 미리 나쁜 조짐이 있었던 것처럼 되기 쉽거든요."}],"summary":["660년, 당의 군사가 서쪽 바다로 들어오고 신라의 군사가 동쪽 고개를 넘자 백제는 계백에게 오천을 주어 황산벌로 보냈어요. 막았어야 할 두 길목은 이미 지나간 뒤였지요.","오천은 오만을 네 번 물리쳤어요. 신라 어른들이 열여섯 살 관창을 두 번이나 적진으로 보낸 뒤에야 벌판이 열렸답니다.","사비성이 열리고 의자왕은 당으로 끌려갔어요. 백성 만 이천여 명도 함께 배에 올랐는데, 그 사람들의 이름은 하나도 남지 않았어요."],"bait":["사비성이 열리고 임금이 끌려갔습니다. 나라가 없어진 것이지요. 그런데 그 뒤로도 <span class=\"blur\">삼 년이나 더</span> 싸움이 이어집니다. 나라가 이미 없어졌는데 누가 무엇을 위해 싸운 것일까요……"]};

;
(window.EPS ||= {})[48] = {"no":48,"chapter":"2장 세 나라의 시대","when":"660~663년","read":"읽기 15~17분","ago":"약 1,360년 전","title":"나라가 없어졌는데 누가 싸웠을까","subtitle":"임금도 도읍도 없어진 자리에서 삼 년을 더 싸운 사람들이 있었습니다","intro":"오늘 이야기의 무대는 <b>백제</b>예요. 정확히는 백제라는 나라가 사라진 뒤의 백제 땅이지요. 660년에 도읍인 사비성이 열리고 임금은 서쪽 나라 <b>당</b>으로 끌려갔어요. 보통은 여기서 한 나라의 역사가 끝나요. 그런데 이 땅에서는 그 뒤로도 삼 년 동안 싸움이 이어집니다. 나라가 이미 없어졌는데 누가, 무엇을 위해 싸운 것일까요? 전갈을 나르던 아이와 강어귀에서 살아남은 젊은이를 따라가며 알아볼까요?","acts":[{"heading":"열흘 사이에 삼만","blocks":[{"t":"p","dlg":false,"html":"그해 여름, 사비성의 문이 열렸습니다."},{"t":"p","dlg":false,"html":"백제의 임금은 배에 실려 서쪽 바다를 건너갔습니다. 함께 끌려간 사람이 만 명이 넘었다고 합니다. 왕자들도 있었고 벼슬아치들도 있었고 손끝이 좋은 장인들도 그 배에 있었습니다."},{"t":"p","dlg":false,"html":"재넘이는 그때 열여섯이었습니다. 사비에서 북쪽으로 <em class=\"hint\">한나절</em> 걸리는 마을에 살았지요."},{"t":"p","dlg":false,"html":"성이 열렸다는 소식이 마을에 닿은 날, 어른들은 별말을 하지 않았습니다. 논은 그대로였고 우물도 그대로였습니다. 아침이면 해가 뜨고 저녁이면 밥을 지었습니다. 달라진 것은 딱 하나, 고을 관청에 다른 나라 사람이 앉은 것이었습니다."},{"t":"p","dlg":false,"html":"당은 사비에 <em class=\"dot\">도독부</em>를 두고 백제 땅을 다스리기로 했습니다. 이긴 나라가 진 나라의 땅을 제 관청으로 다스리겠다는 것이었습니다."},{"t":"p","dlg":false,"html":"그런데 그해 팔월, 서쪽 산에서 연기가 올랐습니다."},{"t":"p","dlg":false,"html":"임존성이었습니다. 산꼭대기를 빙 둘러 쌓은 성이었지요. 그 성에 흑치상지라는 사람이 있었습니다. 백제 서쪽 지방 사람이었고 키가 일곱 <em class=\"hint\">자</em>가 넘었다고 합니다. 스무 살이 되기 전에 아버지의 자리를 이어 달솔이라는 높은 벼슬에 올랐고, 풍달군이라는 고을을 맡아 다스리던 사람이었습니다."},{"t":"p","dlg":false,"html":"사비성이 열리던 날, 그는 제가 거느린 군사와 함께 당의 장수 앞에 나아가 항복했습니다. 나라가 없어졌으니 거기서 끝이라고 생각했지요."},{"t":"p","dlg":false,"html":"그를 돌려세운 것은 그 뒤에 본 일이었습니다. 당의 군사들이 늙은 임금을 가두어 놓고 성안에 풀려나 마음대로 빼앗고 다녔거든요. 흑치상지는 곁에 있던 우두머리 열몇 사람과 함께 그 자리를 빠져나왔습니다."},{"t":"p","dlg":false,"html":"그가 임존성에 들어가 사람을 부르자 열흘이 못 되어 삼만 명이 모였습니다."},{"t":"illust","n":1,"cap":"나라가 없어진 뒤, 산꼭대기의 성으로 사람들이 줄지어 올라왔습니다","src":"img/web/ep048-plate-1.jpg?v=a8564f3dea"},{"t":"p","dlg":false,"html":"같은 무렵, 남쪽의 주류성에서도 사람이 모이고 있었습니다."},{"t":"p","dlg":false,"html":"그곳을 이끈 것은 두 사람이었습니다. 한 사람은 복신이었습니다. 끌려간 임금과 사촌 사이였고 오래 군사를 거느려 본 사람이었지요. 다른 한 사람은 절에서 수행하던 <em class=\"dot\">승려</em> 도침이었습니다. 나라가 무너지자 절을 나와 사람들 앞에 선 것입니다."},{"t":"p","dlg":false,"html":"두 사람은 성을 지키기만 한 것이 아니었습니다. 군사를 나누어 <em class=\"hint\">사방</em>으로 보냈고, 백제 땅의 성들이 하나씩 되돌아왔습니다. 한때는 이백 곳이 넘었습니다."},{"t":"p","dlg":false,"html":"재넘이가 <em class=\"dot\">전령</em>이 된 것이 그 무렵이었습니다. 발이 빨랐고 산길을 알았거든요. 그는 임존성과 주류성 사이를 오갔습니다. 걸어서 이틀 길이었습니다."},{"t":"spot","n":1,"size":"normal","cut":true,"width":640,"height":800,"cap":"발 빠르고 산길을 알던 재넘이는, 걸어서 이틀 걸리는 두 성 사이를 오갔다","src":"img/web/ep048-spot-1.png?v=80e70e1d92"},{"t":"p","dlg":false,"html":"다만 그 사람들에게 없는 것이 하나 있었습니다. 임금이었습니다. 흩어진 성과 사람들을 한데 묶으려면 모두가 「우리 임금」이라 부를 사람이 있어야 한다고들 했습니다."},{"t":"p","dlg":false,"html":"백제의 임금은 바다 건너로 끌려갔고 왕자들도 함께 갔습니다. 그런데 딱 한 사람, 바다 건너 왜에 가 있는 왕자가 있었습니다. 부여풍이었습니다. 그는 여러 해 전에 <em class=\"dot\">볼모</em>로 건너가 그곳에서 살고 있었지요."},{"t":"p","dlg":false,"html":"백제와 왜 사이에는 오래전부터 배가 끊이지 않았습니다. 이백오십 해도 더 전에 백제의 <em class=\"dot\">태자</em>가 볼모로 바다를 건너갔다가, 아버지가 세상을 떠나자 왜 군사 백 명의 호위를 받으며 돌아와 임금이 된 일도 있었습니다. 이번에도 바다 건너에 백제 임금의 핏줄이 한 사람 남아 있었던 것입니다."},{"t":"p","dlg":false,"html":"이듬해, 부여풍은 왜의 배를 타고 돌아왔습니다. 사람들은 그를 임금으로 세웠습니다."},{"t":"p","dlg":false,"html":"재넘이는 그 배가 닿는 것을 멀리서 보았습니다. 성도 되찾았고 사람도 모였고 이제 임금까지 생겼습니다. 나라를 다시 세우는 일은 다 된 것 같았습니다."}]},{"heading":"편지가 달라졌다","blocks":[{"t":"p","dlg":false,"html":"처음에 재넘이가 나른 편지에는 이런 것이 적혀 있었습니다. 어느 고개에 군사를 보내라. 어느 마을에서 곡식을 걷어라. 사비의 관청을 에워싸는 데 사람이 얼마나 더 있어야 한다."},{"t":"p","dlg":false,"html":"한 해가 지나자 편지가 달라졌습니다."},{"t":"p","dlg":false,"html":"누구를 믿지 마라. 어느 장수가 무슨 말을 하고 다니는지 적어 보내라. 이쪽 군사가 몇인지 저쪽에 알리지 마라."},{"t":"p","dlg":false,"html":"「저쪽」은 당의 관청이 아니었습니다. 같은 편의 다른 성이었습니다. 편지가 겨누는 곳이 바깥에서 안쪽으로 바뀌어 가고 있었습니다."},{"t":"p","dlg":false,"html":"주류성 안에서는 두 사람이 저마다 제 이름 앞에 장군 <em class=\"hint\">칭호</em>를 붙였습니다. 도침은 스스로 영군장군이라 했고 복신은 스스로 상잠장군이라 했습니다. 저마다 제 힘을 내세운 것이었습니다. 사람은 더 모였고 세력도 더 커졌습니다."},{"t":"p","dlg":false,"html":"그러다 복신이 도침을 죽였습니다. 그리고 도침이 거느리던 사람들까지 제 밑에 두었습니다. 복신이 왜 도침을 죽였는지는 옛 책이 적어 두지 않았습니다."},{"t":"p","dlg":false,"html":"임금인 부여풍은 그것을 막지 못했습니다. 그 뒤로 그가 하는 일은 제사를 지내는 것뿐이었습니다. 이름은 임금이었지만, 군사와 나랏일은 모두 복신이 쥐었습니다."},{"t":"p","dlg":false,"html":"재넘이는 그 일이 있기 사흘 전에 편지 한 장을 날랐습니다. 겉에 적힌 것은 늘 보던 글자였습니다. 안에 무엇이 적혔는지는 몰랐습니다. 전령은 편지를 읽지 않으니까요."},{"t":"illust","n":2,"cap":"전령은 제가 나른 편지에 무엇이 적혔는지 몰랐습니다","src":"img/web/ep048-plate-2.jpg?v=b7c1e342d1"},{"t":"p","dlg":false,"html":"소식을 듣고 그는 제가 나른 것이 무엇이었을까 생각했습니다. 혹시 그 편지가 도침을 어디로 불러내는 편지였을까. 알아낼 방법은 없었습니다."},{"t":"p","dlg":false,"html":"그해 가을, 주류성 마당에서 재넘이는 물살을 만났습니다. 강어귀 마을에서 온 젊은이였고 열아홉이었습니다. 배를 저을 줄 알아 곡식 나르는 일을 맡고 있었지요."},{"t":"p","dlg":true,"html":"“너는 왜 왔어?” 재넘이가 물었습니다."},{"t":"p","dlg":false,"html":"물살은 한참 있다가 대답했습니다."},{"t":"p","dlg":true,"html":"“우리 아버지가 관청에 곡식을 두 번 냈어. 여름에 한 번, 가을에 또 한 번. 같은 논에서.”"},{"t":"p","dlg":false,"html":"그게 다였습니다. 나라를 되세운다는 말도, 임금을 모신다는 말도 하지 않았습니다."},{"t":"p","dlg":false,"html":"사비성이 열린 지 세 해가 지난 여름이었습니다."},{"t":"spot","n":2,"size":"large","cap":"물살의 아버지는 같은 논에서 난 곡식을, 여름과 가을에 두 번 관청에 내야 했다","src":"img/web/ep048-spot-2.jpg?v=e776adcdbc"},{"t":"p","dlg":false,"html":"복신이 병이 났다고 했습니다. 그는 땅을 파서 만든 방인 <em class=\"dot\">굴실</em>에 자리를 펴고 누웠습니다."},{"t":"p","dlg":false,"html":"재넘이가 나른 마지막 전갈이 그것이었습니다. 장군이 몹시 편찮으니 임금께서 몸소 와 주십사 하는 말이었습니다."},{"t":"p","dlg":false,"html":"부여풍은 그 전갈을 받고 사람을 보내 안을 살펴보게 했습니다. 그러고는 가까운 이들만 거느리고 굴실로 갔습니다. 그날 복신이 죽었습니다. 병을 핑계로 임금을 불러들여 붙잡으려 한 것을 부여풍이 먼저 알고, 그 자리에서 복신을 죽인 것이었습니다. 바다 건너에서 임금을 모셔 와 세운 사람을, 그 임금이 죽인 것입니다."},{"t":"p","dlg":false,"html":"그날 저녁 물살이 재넘이에게 물었습니다."},{"t":"p","dlg":true,"html":"“우리는 지금 누구랑 싸우는 거야?”"},{"t":"p","dlg":false,"html":"재넘이는 대답하지 못했습니다."},{"t":"p","dlg":false,"html":"그 뒤로 성을 떠나는 사람이 늘었습니다. 밤에 성벽 아래 도랑으로 빠져나가 돌아오지 않는 사람들이었지요. 아무도 잡으러 가지 않았습니다."},{"t":"spot","n":3,"size":"normal","cap":"같은 편끼리 싸운 뒤에는, 밤에 성벽 아래 도랑으로 빠져나가 떠나는 사람이 늘었다","src":"img/web/ep048-spot-3.jpg?v=450deeee8e"},{"t":"p","dlg":false,"html":"남은 사람들에게 왜 남았느냐고 물으면 대답이 저마다 달랐습니다. 빼앗긴 논을 되찾겠다는 사람이 있었습니다. 여기서 나가면 갈 데가 없다는 사람도 있었고요. 성문 앞에서 죽은 아우 이야기를 하다가 그만두는 사람도 있었습니다. 임금을 말하는 사람은 뜻밖에 몇 되지 않았습니다."},{"t":"p","dlg":false,"html":"물살은 그 말들을 옆에서 듣기만 했습니다."},{"t":"p","dlg":false,"html":"부여풍은 바다 건너 왜와 북쪽 고구려에 사람을 보내 군사를 청했습니다. 고구려는 오지 않았습니다. 왜는 왔습니다."}]},{"heading":"강어귀","blocks":[{"t":"p","dlg":false,"html":"물살은 그해 여름 스물이 되었습니다."},{"t":"p","dlg":false,"html":"팔월 스무이레, 그는 곡식을 실은 작은 배의 노를 잡고 백강 <em class=\"dot\">어귀</em>에 있었습니다."},{"t":"p","dlg":false,"html":"바다 쪽에서 배가 들어왔습니다. 왜에서 온 배였습니다. 돛이 강폭을 메웠습니다. 물살은 그렇게 많은 배를 한자리에서 본 적이 없었습니다."},{"t":"p","dlg":false,"html":"강어귀에는 이미 다른 배들이 늘어서 있었습니다. 당의 배였습니다. 며칠 전부터 뱃머리를 강 쪽으로 돌리고 기다리고 있었지요."},{"t":"p","dlg":false,"html":"첫날 싸움에서 왜의 배가 밀려났습니다."},{"t":"p","dlg":false,"html":"이튿날 아침, 왜의 배들이 한꺼번에 밀고 들어갔습니다. 당의 배는 물러서지 않았습니다. 좌우로 갈라져 왜의 배를 사이에 끼고 에워쌌습니다."},{"t":"p","dlg":false,"html":"물살이 탄 배는 뒤쪽에 있었습니다. 싸우는 배가 아니라 곡식을 싣는 배였으니까요. 불이 붙은 것은 앞쪽부터였습니다. 불은 배에서 배로 옮겨붙었고, 뒤로 물러서려던 배들끼리 뱃머리가 엉켰습니다."},{"t":"p","dlg":false,"html":"물살이 탄 배도 기울었습니다. 그는 물에 빠졌다가 갈대밭 쪽으로 헤엄쳤습니다."},{"t":"p","dlg":false,"html":"갈대밭에 올라서서 뒤를 돌아보았을 때, 강어귀는 이미 온통 연기였습니다. 낮인데 해가 보이지 않았습니다. 저녁도 아닌데 물이 붉었습니다."},{"t":"illust","n":3,"cap":"갈대밭에 올라선 젊은이가 멀리 강어귀를 보고 있습니다","src":"img/web/ep048-plate-3.jpg?v=692b32635f"},{"t":"p","dlg":false,"html":"물살은 배를 세지 않았습니다. 셀 수 있는 것이 아니었습니다."},{"t":"p","dlg":false,"html":"그 배들이 불탄 지 열흘쯤 뒤에 주류성이 열렸습니다."},{"t":"p","dlg":false,"html":"부여풍은 임금이 된 지 두 해 만에 배를 타고 달아났습니다. 재넘이는 전갈 하나를 들고 북쪽으로 떠났고, 물살은 그를 다시 보지 못했습니다."},{"t":"p","dlg":false,"html":"이제 남은 것은 임존성 하나였습니다. 처음에 삼만이 모였던 그 산성이지요."},{"t":"p","dlg":false,"html":"그런데 성을 치러 온 군사들 앞에 선 사람이 흑치상지였습니다. 그는 그해에 당의 부름을 받고 항복했고, 당에서 갑옷과 무기와 곡식을 받아 제가 삼 년 동안 지킨 성으로 갔습니다. 그가 무슨 마음으로 다시 항복했는지는 옛 책이 적어 두지 않았습니다. 성은 그해가 다 가기 전에 열렸습니다. 끝까지 남아 있던 장수는 처자를 버려두고 북쪽 고구려로 달아났습니다."},{"t":"p","dlg":false,"html":"백제를 다시 세우려던 싸움은 그렇게 끝났습니다."},{"t":"p","dlg":false,"html":"그 뒤로 이 싸움을 적어 둔 책이 둘 있습니다."},{"t":"p","dlg":false,"html":"우리 책 『삼국사기』는 아주 짧게 적었습니다. 백강 어귀에서 왜인을 만나 네 번 싸워 모두 이기고 그 배 사백 <em class=\"hint\">척</em>을 불태우니, 연기와 불꽃이 하늘을 태우고 바닷물이 붉게 되었다고요. 그런데 이 문장은 본래 우리가 쓴 것이 아닙니다. 이긴 쪽인 당이 적어 둔 것을 우리 책이 옮긴 것이지요. 그러니까 배를 세어 적은 사람은 이긴 쪽이었습니다. 이긴 쪽이 센 수가 얼마나 정확한지는 따져 볼 일입니다."},{"t":"p","dlg":false,"html":"다른 한 권은 바다 건너 왜가 적은 책입니다. 그 책에는 그날 일이 훨씬 자세합니다. 당의 배가 백일흔 척이었다는 것, 이틀에 걸쳐 싸웠다는 것, 둘째 날 아침에 왜의 장수들이 “우리가 앞을 다투면 저들이 스스로 물러날 것이다”라고 말하고 줄도 맞추지 않은 채 밀고 들어갔다는 것까지 적혀 있지요. 그런데 그 책에는 배 사백 척이라는 숫자가 없습니다."},{"t":"p","dlg":false,"html":"같은 이틀을 두고 한 책은 숫자를 적었고 다른 책은 그날 아침에 오간 말을 적었습니다. 어느 쪽도 저 혼자로는 그날의 전부가 아닙니다."},{"t":"p","dlg":false,"html":"달아난 부여풍도 두 책이 다르게 적었습니다. 우리 책은 그가 몸을 빼 달아났는데 간 곳을 모른다고 적고, 고구려로 갔다는 말도 있다고 덧붙였습니다. 바다 건너 책은 배를 타고 고구려로 갔다고 딱 잘라 적었습니다."},{"t":"p","dlg":false,"html":"물살은 갈대밭에서 이틀을 있다가 걸어 나왔습니다."},{"t":"p","dlg":false,"html":"돌아갈 마을은 있었습니다. 논도 그대로였고 우물도 그대로였지요. 다만 그 논에서 나는 곡식을 어디에 내야 하는지가 또 달라져 있었습니다."},{"t":"p","dlg":false,"html":"그는 마을에 들르지 않고 북쪽으로 걸었습니다. 나라를 잃고 떠도는 <em class=\"dot\">유민</em>이 된 것입니다."},{"t":"p","dlg":false,"html":"어디로 가는지는 몰랐습니다. 다만 걸을 수는 있었습니다."}]}],"words":[{"w":"도독부","d":"남의 땅을 차지한 뒤 그 땅을 다스리려고 세운 관청"},{"w":"승려","d":"절에서 부처의 가르침을 따르며 수행하는 사람"},{"w":"전령","d":"싸움터에서 소식과 명령을 전하러 다니는 사람"},{"w":"볼모","d":"약속을 지키겠다는 표시로 남의 나라에 보내 두는 사람"},{"w":"태자","d":"임금의 뒤를 이을 아들"},{"w":"굴실","d":"땅을 파서 만든 방"},{"w":"어귀","d":"강물이 바다로 흘러드는 곳"},{"w":"유민","d":"나라를 잃거나 살던 곳을 떠나 떠도는 백성"}],"hints":[{"w":"한나절","d":"하루 낮의 절반쯤 되는 동안"},{"w":"자","d":"길이를 재는 옛 단위. 한 자는 한 뼘 반쯤"},{"w":"사방","d":"동서남북 네 방향. 곧 모든 곳"},{"w":"칭호","d":"어떤 뜻을 담아 부르는 이름"},{"w":"척","d":"배를 세는 단위"}],"after":{"title":"무덤에 함께 묻은 돌","html":["흑치상지는 당으로 건너가 그 나라의 장수가 되었습니다. 서쪽과 북쪽 국경에서 여러 번 싸워 공을 세웠고 높은 벼슬과 작위를 받았지요. 그러다 689년, 반역을 꾀했다는 모함을 받고 옥에 갇혀 목을 매어 죽었습니다. 예순 살이었습니다. 아홉 해가 지나서야 죄가 없었음이 밝혀져 이름이 되돌려졌고요. 『삼국사기』는 그의 열전을 이렇게 맺습니다. 받은 상을 늘 부하들에게 나누어 주어 남긴 재물이 없었고, 그가 죽자 사람들이 모두 그 억울함을 슬퍼했다고요. 1929년 중국 낙양의 한 언덕에서 그의 무덤에 함께 묻혔던 돌이 아들의 것과 나란히 나왔습니다. 천육백 자가 넘게 새겨진 그 돌 덕분에 우리는 그가 언제 태어나 무슨 일을 했는지 훨씬 자세히 알게 되었습니다."]},"ifme":{"q":"모두가 같은 것을 바라는데도 서로를 믿지 못하게 될 때, 나는 무엇을 할 수 있을까?","html":["복신도 도침도 부여풍도 백제를 다시 세우려고 모인 사람들이었습니다. 바라는 것이 같았지요. 그런데 세 해를 못 넘기고 서로를 죽였습니다. 왜 그랬는지 옛 책은 알려 주지 않습니다. 다만 힘이 한 사람에게 몰렸다는 것, 그리고 그것을 나누는 방법을 아무도 미리 정해 두지 않았다는 것만 읽어 낼 수 있지요. 모둠 활동이든 놀이든, 같은 것을 바라는 사람들끼리 어긋나 본 적이 있나요? 그때 무엇이 미리 있었더라면 좋았을지 이야기해 보세요. 정답은 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 복신과 도침, 흑치상지와 부여풍은 모두 실제로 있었던 사람이에요. 나라가 무너진 뒤 임존성과 주류성에서 삼 년을 싸운 일, 열흘이 못 되어 삼만 명이 모인 일, 복신이 도침을 죽이고 부여풍이 복신을 죽인 일, 663년 백강 어귀에서 배 사백 척이 불탄 일은 모두 『삼국사기』에 적혀 있습니다. 다만 사백 척이라는 숫자는 우리가 센 것이 아니라 이긴 쪽인 당이 적어 둔 것을 우리 책이 옮긴 것이고, 그날 싸움의 자세한 모습은 바다 건너 왜가 적은 책에만 있어요. 그래서 이 편은 어느 한 책만 믿지 않고 둘을 나란히 놓았습니다. 흑치상지를 두고는 오늘도 말이 갈립니다. 끝까지 싸우지 않고 돌아섰다고 보는 사람도 있고, 나라가 없어진 자리에서 살아남아야 했던 사람이라고 보는 사람도 있지요. 재넘이와 물살은 지어낸 사람입니다."]},"quiz":[{"n":1,"kind":"사실 확인","q":"항복했던 흑치상지가 다시 돌아선 까닭은 무엇이었나요?","opts":["바다 건너에서 왕자가 돌아온다는 소식을 들었기 때문에","당의 군사들이 늙은 임금을 가두어 놓고 마음대로 빼앗고 다녔기 때문에","그가 맡아 다스리던 고을이 불에 탔기 때문에","왜가 군사를 보내 주겠다는 약속을 해 왔기 때문에"],"answer":1,"why":{"0":"부여풍이 돌아온 것은 그로부터 한 해 뒤의 일입니다.","2":"그가 다스리던 고을이 불에 탔다는 이야기는 나오지 않습니다.","3":"왜의 배가 온 것은 그로부터 세 해나 뒤였습니다."},"ref":"당의 군사들이 늙은 임금을 가두어 놓고 성안에 풀려나 마음대로 빼앗고 다녔거든요.","more":"『삼국사기』 흑치상지 열전이 그 까닭을 그대로 적어 두었어요. <b>「定方囚老王 縱兵大掠」</b>(정방이 늙은 왕을 가두고 군사를 풀어 크게 노략질하였다). 그 뒤에 <b>「常之懼 與左右酋長十餘人遯去」</b>(상지가 두려워 좌우의 우두머리 십여 명과 함께 달아났다)가 이어집니다. 그를 움직인 것은 나라를 잃었다는 생각보다 눈앞에서 벌어진 일이었던 셈이지요."},{"n":2,"kind":"사실 확인","q":"복신이 도침을 죽인 뒤, 임금인 부여풍의 자리는 어떻게 되었나요?","opts":["그 뒤로 그가 하는 일은 제사를 지내는 것뿐이었습니다","임존성으로 옮겨 가 흑치상지와 함께 싸웠습니다","바다 건너 왜로 되돌아갔습니다","두 사람을 말리고 군사를 다시 나누어 주었습니다"],"answer":0,"why":{"1":"부여풍이 있던 곳은 주류성이었고, 임존성으로 옮겨 갔다는 이야기는 없습니다.","2":"그가 배를 타고 달아난 것은 그로부터 두 해 뒤 백강 싸움에 진 다음입니다.","3":"도침은 이미 죽었고 그 사람들까지 복신 밑으로 들어간 뒤였습니다."},"ref":"그 뒤로 그가 하는 일은 제사를 지내는 것뿐이었습니다.","more":"『삼국사기』 백제본기의 원문은 이렇습니다. <b>「尋而福信殺道琛 幷其衆 豊不能制 但主祭而已」</b>(얼마 뒤 복신이 도침을 죽이고 그 무리를 아우르니, 풍은 막지 못하고 다만 제사만 주관할 뿐이었다). 임금으로 모셔 온 사람이 임금 노릇을 못 하게 된 것이지요. 두 해 뒤 복신이 병을 핑계로 굴실에 누운 것을 두고 원문은 <b>「欲俟豊問疾 執殺之」</b>(풍이 문병 오기를 기다렸다가 붙잡아 죽이려 했다)라고 적었고, 부여풍이 먼저 움직였다고 이어 적습니다."},{"n":3,"kind":"추론","q":"마을 관청에 앉은 사람이 달라졌다는 것과 물살이 한 말을 함께 놓고 보면, 백제 땅 사람들이 싸움에 나선 까닭을 어떻게 짐작할 수 있을까요?","opts":["끌려간 임금이 돌아오기를 기다리는 마음 하나 때문이었습니다","나라가 없어진 일이 관청에 곡식을 내는 일로 날마다 닥쳐왔기 때문입니다","싸움에 나가면 곡식을 나누어 준다는 약속이 있었기 때문입니다","바다 건너 왜가 백제 사람에게 벼슬을 준다고 했기 때문입니다"],"answer":1,"why":{"0":"물살은 임금 이야기도 나라를 되세운다는 말도 하지 않았습니다.","2":"곡식을 나누어 준다는 약속은 이야기 어디에도 나오지 않습니다.","3":"왜의 배는 군사를 싣고 왔지 벼슬을 가지고 온 것이 아닙니다."},"ref":"우리 아버지가 관청에 곡식을 두 번 냈어. 여름에 한 번, 가을에 또 한 번. 같은 논에서.","more":"옛 책은 보통 사람이 왜 싸움에 나섰는지를 적어 두지 않았어요. 『삼국사기』에 적힌 것은 장수들의 이름과 성의 이름뿐이지요. 다만 백제 땅에서 이백 곳이 넘는 성이 되돌아섰다는 기록은, 싸운 사람이 장수 몇 명이 아니라 아주 많았다는 뜻이랍니다. 오늘날 학자들은 이렇게 무너진 나라를 다시 일으켜 세우려 한 싸움을 <b>부흥 운동</b>이라고 부릅니다. 초등학교 사회 교과서에는 나오지 않는 말이에요."},{"n":4,"kind":"낱말·표현","q":"본문에 나온 '굴실'은 무엇을 뜻하는 말인가요?","opts":["절 안에서 부처를 모시는 방","성벽 안쪽에 곡식을 쌓아 두던 창고","배를 숨겨 두려고 강가에 뚫은 굴","땅을 파서 만든 방"],"answer":3,"why":{"0":"절과 관계된 말이 아니고, 그곳에 누운 사람도 승려가 아니었습니다.","1":"곡식을 쌓아 두는 곳이라면 병든 사람이 자리를 펴고 누울 수 없습니다.","2":"복신이 누운 곳은 강가가 아니라 성안이었습니다."},"ref":"그는 땅을 파서 만든 방인 굴실에 자리를 펴고 누웠습니다.","more":"원문의 글자는 <b>「窟室」</b>입니다. 굴 굴 자에 방 실 자예요. 옛 기록에는 이런 방이 더러 나오는데, 여름에 시원하고 겨울에 덜 추워서 병든 사람이 눕기도 했고 남의 눈을 피하기도 좋았습니다. 복신이 하필 그 방에 누웠다고 적힌 것을 두고, 오늘날 학자들은 그가 정말 아팠는지 아니면 처음부터 사람을 부르려고 그랬는지를 두고 의견이 갈린답니다."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 흑치상지를 오늘날 어떻게 말하는 것이 알맞을까요?","opts":["남은 기록이 없어서 어떤 사람이었는지 알 길이 없습니다","나라를 배신한 사람이라고 한마디로 잘라 말하면 됩니다","보는 자리에 따라 평가가 갈리는 사람이라 한쪽으로만 말하기 어렵습니다","당에서 큰 공을 세웠으니 훌륭한 사람이라고만 하면 됩니다"],"answer":2,"why":{"0":"『삼국사기』에 그의 열전이 실려 있고, 무덤에 함께 묻힌 돌에도 그의 삶이 천육백 자 넘게 새겨져 있습니다.","1":"그는 나라가 무너진 뒤 가장 먼저 사람을 모아 삼 년을 싸운 사람이기도 합니다.","3":"그가 앞장서서 친 임존성은 제가 삼 년 동안 지킨 성이었습니다."},"ref":"끝까지 싸우지 않고 돌아섰다고 보는 사람도 있고, 나라가 없어진 자리에서 살아남아야 했던 사람이라고 보는 사람도 있지요.","more":"국사편찬위원회는 흑치상지를 두고 오늘날의 평가가 크게 셋으로 갈린다고 정리합니다. 백제를 등지고 부흥 운동을 끝내는 데 앞장섰다며 박하게 보는 쪽, 남의 나라에 건너가 제 힘으로 자리를 얻어 낸 사람으로 보는 쪽, 그리고 나라를 되세우려다 실패하고 끝내 모함으로 죽은 사람으로 보는 쪽이지요. 하나로 정해진 답이 없다는 것 자체가, 오늘날 이 사람을 읽는 방법이랍니다."}],"summary":["660년에 사비성이 열리고 임금이 끌려간 뒤에도 백제 땅에서는 삼 년 동안 싸움이 이어졌어요. 흑치상지가 임존성에서 사람을 부르자 열흘이 못 되어 삼만 명이 모였답니다.","그런데 함께 싸우던 사람들이 서로를 죽였어요. 복신이 도침을 죽였고, 왜에서 돌아와 임금이 된 부여풍이 복신을 죽였지요.","663년 백강 어귀에서 배 사백 척이 불타면서 그 싸움은 끝났어요. 흑치상지는 당에 항복해 제가 삼 년 동안 지킨 임존성을 치는 앞장에 섰답니다."],"bait":["백강에서 배 사백 척이 불탔고 백제를 되세우려던 싸움도 끝났습니다. 남은 것은 고구려 하나였지요. 그런데 고구려를 무너뜨린 것은 <span class=\"blur\">바깥의 군대가 아니었습니다</span>. 성문을 연 사람은 이번에도 안에 있었지요……"]};

;
(window.EPS ||= {})[49] = {"no":49,"chapter":"2장 세 나라의 시대","when":"666~668년","read":"읽기 15~17분","ago":"약 1,360년 전","title":"평양성 문을 연 사람은 누구였을까","subtitle":"밖에서 오는 것은 쉰 해를 막아 냈습니다. 막지 못한 것은 밖에서 오지 않았습니다","intro":"오늘 이야기의 무대는 <b>고구려</b>의 도읍 <b>평양성</b>이에요. 세 나라의 시대가 끝나는 자리지요. 백제가 무너지고 여덟 해가 지나, 서쪽의 큰 나라 앞에 남은 것은 이제 고구려 하나였어요. 고구려는 지난 쉰 해 남짓 동안 서쪽에서 온 두 황제를 돌려보낸 나라입니다. 성벽이 튼튼해서 밖에서 오는 것에는 좀처럼 열리지 않았거든요. 그런데 그 나라가 몇 해 만에 사라집니다. 도읍의 문을 연 사람은 누구였을까요? 그 문을 지키던 문지기와 성안에서 굶던 아이를 따라가며 알아볼까요?","acts":[{"heading":"문설주의 금","blocks":[{"t":"p","dlg":false,"html":"백강에서 배가 불탔다는 소식이 평양에 닿은 지 세 해가 지났습니다. 남쪽에서 백제를 되세우려던 싸움이 그것으로 끝났고, 서쪽의 큰 나라 앞에 남은 것은 고구려 하나였습니다."},{"t":"p","dlg":false,"html":"그해 정월, 평양성 큰 문 앞에 눈이 얕게 깔렸습니다."},{"t":"p","dlg":false,"html":"높새는 마흔넷이었습니다. 스무 해가 넘도록 이 문을 여닫아 온 사람이었지요. 문을 한 번 열 때마다 그는 <em class=\"hint\">문설주</em> 안쪽에 손톱만 한 금을 하나씩 그었습니다. 금은 벌써 문설주를 세 뼘이나 덮고 있었습니다."},{"t":"p","dlg":false,"html":"문지기가 하는 일은 여는 것만이 아니었습니다. 닫는 일이 더 중요했지요. 문 위쪽 성벽에는 <em class=\"dot\">성가퀴</em>가 죽 이어져 있었습니다. 높새는 하루에 두 번 그 낮은 담 뒤를 걸으며, 몸을 숨긴 채 밖을 내다보았습니다."},{"t":"spot","n":1,"size":"large","cap":"성벽 위 낮은 담인 성가퀴 뒤에서는, 몸을 숨긴 채 성 밖을 살펴볼 수 있었다","src":"img/web/ep049-spot-1.jpg?v=c00a7a30dc"},{"t":"p","dlg":false,"html":"높새의 아버지는 서쪽 강가에서 돌아온 사람이었습니다. 서쪽의 큰 나라가 헤아릴 수 없이 많은 군사를 보냈다가 거의 다 잃고 물러간 그 싸움 말입니다. 높새가 스물세 살이던 해에는 그다음 나라의 황제가 몸소 왔습니다. 요동의 작은 성 하나가 그 황제를 석 달 가까이 붙들었고, 황제는 끝내 돌아갔지요. 그해에도 평양성의 이 문은 한 번도 닫히지 않았습니다. 싸움이 요동에서 끝나, 적이 평양까지 오지 못했기 때문입니다."},{"t":"p","dlg":false,"html":"검단은 그 문 옆 골목에 살았습니다. 열 살이었고, 아침마다 문이 열리기를 기다리는 아이였습니다. 검단의 집 밭이 성 밖에 있었거든요."},{"t":"p","dlg":false,"html":"검단은 세는 아이였습니다. 문으로 들어오는 소달구지를 세고, 밭에서 이고 오는 <em class=\"hint\">조</em> 자루를 세고, 겨울에 남은 날을 셌습니다."},{"t":"p","dlg":true,"html":"“아저씨, 그 금 몇 개예요?”"},{"t":"p","dlg":true,"html":"“세어 본 적 없다.”"},{"t":"p","dlg":true,"html":"“저는 셀 수 있는데요.”"},{"t":"p","dlg":true,"html":"“세면 뭐가 달라지느냐.”"},{"t":"p","dlg":false,"html":"검단은 대답을 못 했습니다. 그래도 그날부터 검단은 그 금을 몇 번이나 세다 말다 했습니다."},{"t":"p","dlg":false,"html":"그 정월에 나라의 일을 도맡아 보던 사람이 죽었습니다. 스물네 해 전에 임금을 갈아 치우고 나라를 손에 쥐었던 사람이었지요. 그가 앉아 있던 <em class=\"dot\">막리지</em> 자리를 맏아들 연남생이 이었습니다. 고구려의 군사와 벼슬아치가 이제 그 맏아들의 말을 따라야 했습니다."},{"t":"p","dlg":false,"html":"남생에게는 아우가 둘 있었습니다. 남건과, 그 아래로 하나였습니다."},{"t":"p","dlg":false,"html":"봄이 되자 남생은 지방의 여러 성을 돌아보러 떠나기로 했습니다. 새로 나라의 일을 맡은 사람이 여러 성을 한 번 둘러보는 걸음이었지요. 도읍의 일은 두 아우에게 맡겼습니다."},{"t":"p","dlg":false,"html":"떠나는 아침, 높새가 문을 열었습니다. 그날의 금이 문설주에 하나 늘었습니다."},{"t":"illust","n":1,"cap":"막리지의 행렬이 평양성 큰 문을 나서던 봄 아침","src":"img/web/ep049-plate-1.jpg?v=2aaef22b86"},{"t":"p","dlg":false,"html":"<em class=\"hint\">행렬</em>이 다 나가고 나서 검단이 물었습니다."},{"t":"p","dlg":true,"html":"“저 사람 언제 와요?”"},{"t":"p","dlg":true,"html":"“가을에는 오겠지.”"},{"t":"p","dlg":false,"html":"높새는 그렇게 대답했습니다. 그리고 그 사람은 다시는 이 문으로 들어오지 못했습니다."}]},{"heading":"돌아오지 못한 형","blocks":[{"t":"p","dlg":false,"html":"남생이 떠나고 얼마 지나지 않아 도읍에 말이 돌기 시작했습니다."},{"t":"p","dlg":false,"html":"누군가 두 아우에게 말했습니다. “형이 너희가 제 자리를 <em class=\"hint\">넘본다고</em> 여겨 없애려 한다. 먼저 손을 쓰는 편이 낫다.”"},{"t":"p","dlg":false,"html":"또 누군가 남생에게 말했습니다. “아우들이 형이 돌아와 그 자리를 도로 가져갈까 두려워하여, 문을 막고 들이지 않으려 한다.”"},{"t":"p","dlg":false,"html":"그 누군가가 누구였는지는 옛 책에 적혀 있지 않습니다. 적혀 있는 것은 형도 아우도 결국 그 말을 믿었다는 것뿐입니다."},{"t":"p","dlg":false,"html":"높새는 문 앞을 오가는 말들을 들으며 생각했습니다. 형은 도읍 밖에 있고 아우들은 도읍 안에 있으니, 서로 얼굴을 볼 수 없는 사이로 말만 오가고 있었습니다."},{"t":"p","dlg":false,"html":"남생은 사람을 하나 골라 몰래 평양으로 들여보냈습니다. 아우들이 정말 그러는지 알아보려는 것이었지요. 형이 아우들에게 <em class=\"dot\">첩자</em>를 보낸 것입니다."},{"t":"p","dlg":false,"html":"그 첩자가 성안에서 붙잡혔습니다. 형이 아우들을 몰래 살피고 있었다는 것이 그 첩자와 함께 드러난 것입니다. 아우들에게는 옮겨 온 말이 참말이라는 증거처럼 보였습니다."},{"t":"spot","n":2,"size":"normal","cap":"연남생이 아우들의 사정을 알아보려고 보낸 첩자는, 평양성 안에서 붙잡혔다","src":"img/web/ep049-spot-2.jpg?v=47fd519cbe"},{"t":"p","dlg":false,"html":"그날부터 일이 빨리 굴러갔습니다. 임금의 이름으로 남생을 부르는 글이 북쪽으로 갔지만 남생은 오지 않았습니다. 남건이 스스로 막리지가 되어 군사를 이끌고 형을 쳤습니다. 남생은 더 북쪽으로 밀려나, 오래전 고구려의 도읍이던 성에 들어가 문을 걸었습니다."},{"t":"p","dlg":false,"html":"그리고 남건은 성안에 남아 있던 형의 아들을 죽였습니다."},{"t":"p","dlg":false,"html":"높새는 그 소식을 문 앞에서 들었습니다. 그날 저녁 그는 문설주의 금을 한참 들여다보았습니다. 그 가운데 하나는 남생이 떠나던 봄 아침에 그은 금이었습니다."},{"t":"p","dlg":false,"html":"옛 도읍에 갇힌 남생은 남은 아들 하나를 서쪽으로 보냈습니다. 서쪽의 큰 나라 당에 군사를 빌리러 간 것이었습니다. 쉰 해 동안 서쪽에서 오는 군대를 막아 온 고구려에서 막리지였던 사람이, 이제 그 서쪽에 군사를 청한 것입니다."},{"t":"p","dlg":false,"html":"이듬해, 서쪽에서 군대가 왔습니다."},{"t":"p","dlg":false,"html":"그 군대 앞에 남생이 서 있었습니다."},{"t":"p","dlg":false,"html":"고구려의 성이 어디에 있고 어느 골짜기로 사람이 넘어 다니는지, 어느 성에 곡식이 얼마나 쌓여 있는지를 그보다 잘 아는 사람은 없었습니다. 지난 쉰 해 동안 서쪽에서 온 군대들은 그것을 아무도 알려 주지 않는 땅에서 싸웠습니다."},{"t":"p","dlg":false,"html":"성들이 차례로 열렸습니다. 해가 바뀌고 이월, 북쪽의 큰 성 하나가 열리자 그 둘레의 성 마흔 곳이 함께 문을 열었습니다. 한 해가 다 가기 전에 나라의 서쪽이 통째로 없어졌습니다."},{"t":"p","dlg":false,"html":"그 가을, 군대가 평양성을 빙 둘러쌌습니다. 성은 <em class=\"dot\">포위</em>되어, 아무도 드나들 수 없게 되었습니다."},{"t":"p","dlg":false,"html":"높새는 문을 닫았습니다. 그리고 그날부터 금을 긋지 않았습니다."},{"t":"p","dlg":false,"html":"검단의 집 밭은 문 밖에 있었습니다. 조가 여물어 가는 밭이었지요. 그해 그 밭에서는 한 알도 성안으로 들어오지 못했습니다."},{"t":"p","dlg":false,"html":"성안에 있던 것으로만 살아야 했습니다. 처음 열흘은 견딜 만했습니다. 스무 날이 지나자 골목의 아이들이 뛰지 않았습니다. 한 달이 지나자 소금이 없어졌습니다. 그때부터 검단은 세는 것을 바꾸었습니다. 소달구지 대신 날을 셌습니다."},{"t":"illust","n":2,"cap":"한 달이 넘도록 그 문은 열리지 않았습니다","src":"img/web/ep049-plate-2.jpg?v=603b90704b"},{"t":"p","dlg":true,"html":"“아저씨, 오늘이 서른이레예요.”"},{"t":"p","dlg":true,"html":"“세지 마라.”"},{"t":"p","dlg":true,"html":"“세면 뭐가 달라지느냐고 하셨잖아요.”"},{"t":"p","dlg":true,"html":"“그래서 세지 말라는 거다.”"},{"t":"p","dlg":false,"html":"세어 봐야 달라지는 것은 없고, 굶은 날만 또렷해진다는 말이었습니다."},{"t":"p","dlg":false,"html":"한 달이 넘는 동안 성벽은 제자리에 그대로 있었습니다. 밖에서 오는 것은 이번에도 이 문을 열지 못했습니다."}]},{"heading":"닷새","blocks":[{"t":"p","dlg":false,"html":"구월이었습니다."},{"t":"p","dlg":false,"html":"어느 날 아침, 궁궐 쪽에서 사람들이 걸어 나왔습니다. 고을과 성을 맡아 다스리던 <em class=\"dot\">수령</em> 아흔여덟 명이었습니다. 그 아흔여덟 사람이 흰 깃발을 들고 문 쪽으로 왔습니다. 흰 깃발을 들고 나가는 것은 이제 싸우지 않겠다는 뜻이었습니다. 맨 앞에 선 사람은 막리지의 막내아우였습니다. 임금이 보낸 사람들이었지요."},{"t":"p","dlg":false,"html":"높새는 문을 조금 열었습니다. 아흔여덟 사람이 나가고 나자 문은 곧 다시 닫혔습니다. 그날의 금은 긋지 않았습니다."},{"t":"p","dlg":false,"html":"임금은 스스로 임금이 된 사람이 아니었습니다. 스물여섯 해 전, 막리지의 아버지가 앞의 임금을 죽이던 그때 그 손에 이끌려 자리에 앉혀진 사람, 바로 그 임금의 조카였지요. 그 뒤로 그가 제 뜻으로 정한 일이 무엇이었는지는 옛 책에도 거의 적혀 있지 않습니다. 그날 아침 그가 한 일은 막리지의 막내아우를 불러 흰 깃발과 함께 내보낸 것이었습니다. 그리고 그것이 그가 임금으로서 한 마지막 일이었습니다."},{"t":"p","dlg":false,"html":"임금이 항복했는데도 싸움은 끝나지 않았습니다. 남건이 항복하지 않았기 때문입니다. 그는 성문을 닫아걸고 날마다 군사를 내어 싸웠습니다. 그러나 이기지 못했습니다."},{"t":"p","dlg":false,"html":"그러다 남건은 성안의 군사를 사람 하나에게 통째로 맡겼습니다. 칼을 든 장수가 아니라 절에서 지내던 <em class=\"dot\">승려</em> 신성이었습니다."},{"t":"p","dlg":false,"html":"왜 승려에게 맡겼는지는 어느 책에도 적혀 있지 않습니다. 남건이 오래 믿어 온 사람이었으리라는 것까지만 짐작할 수 있을 뿐입니다."},{"t":"p","dlg":false,"html":"군사를 맡은 지 얼마 되지 않아 신성은 성 밖으로 사람을 몰래 내보냈습니다. 신성이 밖으로 보낸 말은 짧았습니다. 닷새 뒤에 문을 열겠다는 것이었습니다."},{"t":"p","dlg":false,"html":"성 안에 있으면서 몰래 밖의 적과 통해 안에서 돕겠다는 것이니, 옛 책은 그가 <em class=\"dot\">내응</em>을 청했다고 적었습니다. 성을 지키라고 맡긴 군사가, 성을 여는 군사가 된 것입니다."},{"t":"p","dlg":false,"html":"검단은 그 밤에 잠이 오지 않아 골목 끝까지 나갔다가, 작은 옆문으로 사람 셋이 빠져나가는 것을 보았습니다. 검단은 그날부터 다시 날을 세기 시작했습니다. 무엇을 세는지는 저도 몰랐습니다."},{"t":"spot","n":3,"size":"normal","cap":"잠 못 든 밤 검단은 골목 끝에서, 작은 옆문으로 사람 셋이 빠져나가는 것을 보았다","src":"img/web/ep049-spot-3.jpg?v=d123baddc8"},{"t":"p","dlg":false,"html":"첫날에는 비가 왔습니다. 둘째 날에는 골목의 늙은이 하나가 죽었습니다. 셋째 날에는 성가퀴 위를 오가는 군사가 부쩍 늘었습니다. 넷째 날은 아무 일도 없었습니다."},{"t":"p","dlg":false,"html":"다섯째 날 아침, 검단이 높새를 찾아가 말했습니다."},{"t":"p","dlg":true,"html":"“아저씨, 오늘이 닷새째예요.”"},{"t":"p","dlg":true,"html":"“무슨 닷새냐.”"},{"t":"p","dlg":true,"html":"“몰라요. 그냥 닷새예요.”"},{"t":"p","dlg":false,"html":"그날 성문이 열렸습니다."},{"t":"p","dlg":false,"html":"문을 연 것은 신성의 군사들이었습니다. 높새는 옆으로 밀려나 서서 그 문이 열리는 것을 보았습니다. 스무 해가 넘도록 그 문을 여닫아 온 사람이 마지막으로 그 문을 열지 못했습니다."},{"t":"p","dlg":false,"html":"밖에 있던 군대가 성벽에 올라 북을 쳤습니다. 성의 네 귀퉁이에서 연기가 올랐습니다. 문설주는 타지 않았습니다."},{"t":"p","dlg":false,"html":"668년 구월이었습니다. 세 나라의 시대가 그날로 끝났습니다."},{"t":"p","dlg":false,"html":"임금과 남건은 붙잡혀 서쪽으로 갔습니다. 함께 끌려간 사람도 아주 많았는데, 얼마나 많았는지는 책마다 다르게 적혀 있습니다."},{"t":"p","dlg":false,"html":"이듬해 봄, 강가에 사람들이 모였습니다. 배를 기다리는 사람들이었습니다. 서쪽 나라가 고구려 사람 수만 호를 뽑아 제 나라의 빈 땅으로 옮기기로 한 것이었지요. 한 집에 사는 사람들을 한 호로 세었으니 옮겨 간 사람은 그보다 훨씬 많았습니다. 나라가 없어진 뒤에 남은 고구려의 <em class=\"dot\">유민</em>이 제 땅을 떠나 남의 나라 빈 땅으로 가는 것이었습니다."},{"t":"p","dlg":false,"html":"검단의 집도 그 가운데 있었습니다. 높새는 강가까지 따라 나갔습니다."},{"t":"illust","n":3,"cap":"이듬해 봄, 강가에서 배를 기다리는 사람들","src":"img/web/ep049-plate-3.jpg?v=33a9f7687d"},{"t":"p","dlg":true,"html":"“아저씨, 그 문 누가 열었어요?”"},{"t":"p","dlg":true,"html":"“나는 아니다.”"},{"t":"p","dlg":true,"html":"“그럼 누구요?”"},{"t":"p","dlg":false,"html":"높새가 이름을 댔습니다. 검단은 처음 듣는 이름이었습니다."},{"t":"p","dlg":true,"html":"“왜 열었대요?”"},{"t":"p","dlg":false,"html":"높새는 대답하지 못했습니다. 옛 책에도 그 까닭은 적혀 있지 않습니다. 적혀 있는 것은 그가 문을 열었다는 것과, 그해 겨울 서쪽 나라에서 그가 벼슬 하나를 받았다는 것뿐입니다."},{"t":"p","dlg":true,"html":"“성은 밖에서 안 무너지는구나.” 높새가 말했습니다. “안에서 열리는 거지.”"},{"t":"p","dlg":true,"html":"“아저씨는 알고 계셨어요?”"},{"t":"p","dlg":true,"html":"“몰랐다. 오늘 알았다.”"},{"t":"p","dlg":false,"html":"배가 떠난 뒤에 높새는 성으로 돌아갔습니다. 문은 여닫을 것이 없어 그냥 열려 있었습니다."},{"t":"p","dlg":false,"html":"높새는 문설주 앞에 서서, 처음으로 금을 세기 시작했습니다. 이제 그 금들만이, 이 문이 고구려의 문이던 날들을 기억하고 있었습니다."}]}],"words":[{"w":"성가퀴","d":"성벽 위에 낮게 덧쌓아 몸을 숨기고 내다보는 담"},{"w":"막리지","d":"군사와 벼슬아치를 함께 거느리던 고구려의 가장 높은 자리"},{"w":"첩자","d":"남의 나라나 남의 편에 몰래 들어가 사정을 살펴 알려 주는 사람"},{"w":"포위","d":"둘레를 빙 둘러싸서 드나들지 못하게 막는 일"},{"w":"수령","d":"한 고을이나 한 성을 맡아 다스리던 우두머리"},{"w":"승려","d":"절에서 부처의 가르침을 따르며 사는 사람"},{"w":"내응","d":"성 안에 있으면서 몰래 밖의 적과 통해 안에서 돕는 일"},{"w":"유민","d":"나라가 없어진 뒤에 남은 그 나라 사람들"}],"hints":[{"w":"문설주","d":"문짝을 달려고 문 양쪽에 세운 기둥"},{"w":"조","d":"좁쌀이 열리는 곡식"},{"w":"행렬","d":"여럿이 줄지어 가는 것"},{"w":"넘본다고","d":"차지하려고 넘겨다본다고"}],"after":{"title":"고른 적 없는 자리","html":["보장왕은 스스로 임금이 되겠다고 한 적이 없는 사람입니다. 스물여섯 해 전, 아버지의 자리를 이은 신하가 앞의 임금을 죽이고 그를 그 자리에 앉혔지요. 성이 열린 뒤 그는 서쪽으로 끌려가 당의 벼슬 하나를 받았습니다. 아홉 해 뒤 당은 그를 다시 요동으로 돌려보냈어요. 남아 있는 고구려 사람들을 다독이라는 것이었지요. 그런데 요동에 이른 그는 몰래 말갈과 손을 잡으려 했습니다. 살아서 처음으로 제 뜻대로 해 본 일이었는지도 모릅니다. 일은 곧 드러났고, 그는 멀리 남쪽 땅으로 옮겨져 그곳에서 죽었습니다."]},"ifme":{"q":"우리끼리 다투다가 밀려났을 때, 바깥 사람을 불러와도 될까요?","html":["남생은 처음부터 나라를 넘길 생각이었던 사람이 아닙니다. 아우가 그의 아들을 죽였고, 그는 옛 도읍에 갇혀 있었지요. 그 자리에서 그가 부른 것이 하필 서쪽의 큰 나라였을 뿐입니다. 그런데 그가 부른 것은 그를 도와준 뒤에도 돌아가지 않았습니다. 여러분도 형제나 친구와 다투다가 누군가를 부른 적이 있을 거예요. 부르지 않으면 내가 진다고 느낄 때, 누구까지 부를 수 있을까요? 그리고 부르기 전에 무엇을 미리 생각해 두어야 할까요? 이 질문에는 정답이 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 옛 책에 이름과 사건이 또렷이 적혀 있다는 뜻이에요. 연개소문의 세 아들이 갈라선 일, 남건이 형의 아들을 죽인 일, 남생이 서쪽에 군사를 청한 일, 임금이 아흔여덟 사람을 흰 깃발과 함께 내보낸 일, 그리고 남건이 군사를 맡긴 승려 신성이 닷새 뒤에 성문을 연 일은 모두 『삼국사기』 고구려본기와 중국 쪽 책에 적혀 있습니다. 높새와 검단은 지어낸 사람이에요. 평양성 문지기와 그 성에서 굶던 아이는 이름이 한 사람도 남아 있지 않거든요. 그리고 하나 더 있습니다. 연남생을 어떻게 볼 것인가는 지금도 갈려요. 『삼국사기』는 그를 나라를 저버린 사람이라 적었고, 당에서 만들어진 그의 무덤 속 글은 충성스럽고 효성스러운 사람이라 기렸습니다. 같은 사람을 두고 두 기록이 서로 다르게 적은 것이지요. 그러니 이 사람을 한 낱말로 부르기 전에, 두 기록이 왜 그렇게 적었는지를 먼저 보아야 합니다."]},"quiz":[{"n":1,"kind":"사실 확인","q":"연개소문이 죽은 뒤 남생과 두 아우 사이가 갈라지게 된 것은 무엇 때문이었나요?","opts":["남생이 아버지의 자리를 아우들과 나누어 갖지 않겠다고 못 박아서","임금이 세 아들 가운데 하나를 골라 그 자리를 주려고 해서","누군가가 형에게도 아우들에게도 서로 해치려 한다는 말을 옮겨서","아우들이 남생보다 먼저 서쪽 나라에 사람을 보내서"],"answer":2,"why":{"0":"남생은 떠나면서 오히려 도읍의 일을 두 아우에게 맡겼습니다.","1":"이 무렵 임금은 자리를 나누어 주는 쪽이 아니었고, 뒤에 남생을 부르는 글에 이름만 빌려주었습니다.","3":"서쪽 나라에 사람을 보낸 것은 아우들이 아니라 뒤에 밀려난 남생이었습니다."},"ref":"그 누군가가 누구였는지는 옛 책에 적혀 있지 않습니다.","more":"『삼국사기』 고구려본기 보장왕 조와 개소문 열전이 이 대목을 적는데, 말을 옮긴 사람을 두 번 다 <b>「어떤 사람(或)」</b>이라고만 적어요. 두 아우에게 간 말은 <b>「남생이 두 아우가 저를 핍박할까 미워하여 없애려 하니 먼저 도모하는 것만 못하다」</b>였고, 남생에게 간 말은 <b>「두 아우가 형이 돌아와 제 권력을 빼앗을까 두려워하여 형을 막고 들이지 않으려 한다」</b>였습니다. 누가 왜 그 말을 옮겼는지는 천삼백 년이 지난 지금도 아무도 모릅니다."},{"n":2,"kind":"사실 확인","q":"평양성 문은 결국 어떻게 열렸나요?","opts":["서쪽 군대가 성벽을 무너뜨리고 그 자리로 들어왔습니다","굶주림을 견디지 못한 성안 사람들이 다 함께 밀어서 열었습니다","임금이 몸소 걸어 나가 큰 문을 열고 항복했습니다","남건이 군사를 맡긴 승려 신성이 안에서 열었습니다"],"answer":3,"why":{"0":"성벽은 한 달이 넘도록 제자리에 그대로 있었습니다.","1":"성안 사람들은 문 안쪽에서 굶었을 뿐, 문을 여는 일에 끼지 못했습니다.","2":"임금이 내보낸 것은 아흔여덟 사람이었고, 그때 문은 조금 열렸다가 곧 다시 닫혔습니다."},"ref":"문을 연 것은 신성의 군사들이었습니다.","more":"『삼국사기』는 남건이 <b>군사의 일을 승려 신성에게 맡겼다</b>고 적고, 신성이 소장 <b>오사·요묘</b>와 함께 몰래 사람을 보내 내응하겠다고 청한 뒤 <b>닷새 만에 문을 열었다</b>고 적어요. 그리고 그해 십이월, 당의 황제는 신성에게 <b>은청광록대부</b>라는 벼슬을 주었습니다. 왜 문을 열었는지에 대해서는 어느 기록도 한 글자를 적지 않았어요. 남은 것은 그가 한 일과 그가 받은 것뿐입니다."},{"n":3,"kind":"추론","q":"서쪽에서 온 군대가 이번에는 고구려의 성들을 차례로 열 수 있었던 까닭은 무엇일까요?","opts":["고구려의 군사가 남쪽 싸움을 도우러 다 내려가 있었기 때문에","고구려의 성벽이 오랫동안 손보지 않아 낡아 있었기 때문에","고구려의 성을 가장 잘 아는 사람이 이번에는 그 군대 앞에 서 있었기 때문에","서쪽 나라가 전에 없이 많은 군사를 한꺼번에 보냈기 때문에"],"answer":2,"why":{"0":"남쪽 싸움은 세 해 전에 이미 끝났습니다.","1":"성벽이 낡았다는 이야기는 나오지 않고, 평양성의 성벽은 마지막까지 제자리에 있었습니다.","3":"군사가 많은 것으로 말하면 쉰 해 전에 온 군대가 훨씬 많았고, 그때는 성 하나를 못 열고 돌아갔습니다."},"ref":"그 군대 앞에 남생이 서 있었습니다.","more":"이야기가 곧바로 말해 주지 않는 대목이라 흩어진 조각을 이어야 보여요. ① 지난 쉰 해 동안 서쪽에서 온 군대는 고구려의 안을 아무도 알려 주지 않는 땅에서 싸웠다 ② 남생보다 고구려의 성을 잘 아는 사람은 없었다 ③ 그런 그가 이번에는 그 군대 앞에 있었다. 실제로 『삼국사기』와 중국 쪽 책은 남생이 당의 군대를 맞아들여 함께 움직였다고 적어요. 667년부터 성들이 열리기 시작했고, 668년 이월 북쪽의 큰 성 하나가 열리자 그 둘레 <b>마흔 곳이 넘는 성이 모두 항복</b>했습니다."},{"n":4,"kind":"낱말·표현","q":"본문에 나온 '내응'은 무엇을 뜻하는 말인가요?","opts":["둘레를 빙 둘러싸서 드나들지 못하게 막는 일","성 안에 있으면서 몰래 밖의 적과 통해 안에서 돕는 일","성 밖에서 성안으로 몰래 곡식을 들여보내는 일","성벽 위에 낮게 덧쌓아 몸을 숨기고 내다보는 담"],"answer":1,"why":{"0":"그것은 포위라고 합니다.","2":"포위된 동안 곡식은 한 알도 성안으로 들어오지 못했습니다.","3":"그것은 성가퀴라고 합니다."},"ref":"성 안에 있으면서 몰래 밖의 적과 통해 안에서 돕겠다는 것이니, 옛 책은 그가 내응을 청했다고 적었습니다.","more":"「내응」은 「안에서 응한다」는 뜻이에요. 성을 열려는 쪽에는 가장 값이 적게 드는 방법이고, 지키는 쪽에는 가장 무서운 것이지요. 성벽은 아무리 두꺼워도 안쪽을 향해서는 두껍지 않으니까요. 이 시리즈에서 이런 일이 처음은 아니에요. 9회에서 왕검성도 성벽이 멀쩡한 채로 안에서 열렸습니다. 칠백 년이 훌쩍 넘는 세월을 사이에 두고 두 이야기가 닮아 있는 셈이지요."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 연남생을 두고 오늘날까지 사람들의 말이 갈리는 까닭은 무엇일까요?","opts":["그를 적어 둔 두 기록이 서로 다른 자리에서 서로 다른 뜻으로 쓰였기 때문에","그런 사람이 실제로 있었는지 아직 밝혀지지 않았기 때문에","『삼국사기』에 그의 이름이 한 번도 나오지 않기 때문에","그가 뒤에 고구려로 돌아가 당과 다시 싸웠기 때문에"],"answer":0,"why":{"1":"그의 이름은 우리 책에도 중국 쪽 책에도 적혀 있고, 그의 무덤에서 나온 돌에도 새겨져 있습니다.","2":"『삼국사기』는 그의 아버지와 그를 함께 적어 두었습니다.","3":"그가 고구려로 돌아가 다시 싸웠다는 이야기는 나오지 않습니다."},"ref":"같은 사람을 두고 두 기록이 서로 다르게 적은 것이지요.","more":"남생이 죽자 당은 그의 무덤에 돌 하나를 넣었어요. 죽은 사람의 삶을 적어 무덤에 넣는 이런 돌을 <b>묘지명</b>이라고 합니다. 679년에 만들어진 그 돌은 그를 충성스럽고 효성스러운 사람으로 기리고, 그의 죽음을 제후에게나 쓰는 <b>「훙(薨)」</b>이라는 글자로 적었어요. 그런데 그 돌은 그를 기리려고 그의 무덤에 넣은 글입니다. 한편 『삼국사기』를 쓴 김부식은 오백 해 뒤 고려에서, 남생과 그 아들을 두고 <b>「당나라에서는 이름이 났으나 본국으로 말하면 반역자임을 면치 못한다」</b>고 적었어요. 기록이 갈리는 것은 사람에 대한 평만이 아니랍니다. 이듬해 서쪽으로 옮겨 간 고구려 사람의 수도 책마다 달라요. 『삼국사기』는 삼만 팔천삼백 호, 『자치통감』은 삼만 팔천이백 호, 『구당서』는 이만 팔천이백 호라고 적습니다."}],"summary":["연개소문이 죽고 맏아들 남생이 그 자리를 이었지만, 누군가 옮긴 말 때문에 형과 두 아우가 서로를 믿지 못하게 되었어요. 남건은 형의 아들을 죽였고, 남생은 서쪽의 당에 군사를 청했습니다.","남생이 앞장선 군대 앞에서 고구려의 성들이 차례로 열렸고, 668년 가을 평양성이 한 달 넘게 포위되었어요.","성벽은 끝내 무너지지 않았지만, 남건이 군사를 맡긴 승려 신성이 안에서 문을 열었습니다. 668년에 고구려가 없어지고 세 나라의 시대가 끝났어요."],"bait":["평양성이 열리고 세 나라의 시대가 끝났습니다. 그런데 이긴 신라 앞에 남은 것은 <span class=\"blur\">돌아가지 않는 당나라 군대</span>였습니다. 당은 옛 고구려 땅에도 옛 백제 땅에도 제 관청을 세웠고, 심지어 이긴 신라의 임금에게까지 제 나라의 벼슬을 내렸지요……"]};

;
(window.EPS ||= {})[50] = {"no":50,"chapter":"2장 세 나라의 시대","when":"668~670년","read":"읽기 15~17분","ago":"약 1,360년 전","title":"이긴 나라 앞에 남은 것은 무엇이었을까","subtitle":"싸움은 끝났는데 군대는 돌아가지 않았습니다. 이긴 나라의 임금은 남의 나라 벼슬을 하나 받아 두고 있었지요","intro":"오늘 이야기의 무대는 <b>세 나라가 모두 사라진 땅</b>이에요. 668년 평양성이 열리면서 칠백 년쯤 이어진 세 나라의 시대가 끝났지요. 그런데 싸움이 끝났다고 모든 것이 제자리로 돌아가지는 않았어요. 함께 싸운 당은 군사를 거두지 않았고, 이 땅 곳곳에 제 관청을 세웠거든요. 나라가 망해 살던 곳을 떠나 떠도는 백성을 <b>유민</b>이라고 하는데, 그 무렵 이 땅의 길에는 유민이 아주 많았답니다. 이긴 나라 앞에 남은 것은 무엇이었을까요? 북쪽에서 남쪽으로 걸어간 한 사람을 따라가며 알아볼까요?","acts":[{"heading":"이름을 적는 사람들","blocks":[{"t":"p","dlg":false,"html":"평양성 문이 열린 지 석 달이 지났습니다."},{"t":"p","dlg":false,"html":"성벽 위에서 나부끼는 깃발은 신라의 것이 아니었습니다. 함께 싸운 당의 깃발이었습니다. 성 아래 강가에는 걷지 않은 천막이 줄지어 서 있었지요. 여름에 이 성을 에워쌌던 군대가 겨울이 되도록 그대로 있었던 것입니다."},{"t":"p","dlg":false,"html":"검빛은 열두 살이었습니다. 성 아래 마을에서 나고 자랐고, 여름에 어머니를 잃었습니다. 남은 것은 아버지와 누나뿐이었습니다."},{"t":"p","dlg":false,"html":"성문 옆에는 <em class=\"hint\">널판</em>이 하나 서 있었습니다. 전에는 성을 드나들 때 지켜야 할 것들이 붙던 자리였는데, 가을부터 다른 것이 붙기 시작했습니다. 글자가 빽빽한 종이였습니다."},{"t":"p","dlg":false,"html":"검빛은 글자를 몰랐습니다. 그래서 날마다 그 앞에 서서 어른들이 하는 말을 들었습니다."},{"t":"illust","n":1,"cap":"성문 옆 널판에 이름이 적힌 종이가 붙었습니다","src":"img/web/ep050-plate-1.jpg?v=ea94eb691d"},{"t":"p","dlg":true,"html":"“또 늘었네.”"},{"t":"p","dlg":true,"html":"“우리 골목도 다 적혔다더라.”"},{"t":"p","dlg":false,"html":"당은 옛 고구려 땅을 다스리려고 평양에 안동<em class=\"dot\">도호부</em>라는 관청을 세웠습니다. 고구려에는 성이 백일흔여섯 곳 있었고, 집으로 세면 예순아홉만 <em class=\"dot\">호</em>쯤 되었습니다. 당은 그 성들을 아홉 자리로 나누고, 그 아홉을 이 관청 하나가 내려다보게 했지요."},{"t":"p","dlg":false,"html":"관리들이 집집마다 돌았습니다. 문을 두드리고, 방을 들여다보고, 사람 수를 세고, 나이를 물었습니다. 그러고는 손에 든 나무쪽에 무언가를 적었습니다. 한 집을 다 세고 나면 문설주에 먹으로 표를 하나 그렸지요."},{"t":"spot","n":1,"size":"large","cap":"당의 관리들은 집집마다 사람 수와 나이를 묻고, 나무쪽에 적어 두었다","src":"img/web/ep050-spot-1.jpg?v=4ec4fde52d"},{"t":"p","dlg":false,"html":"새터는 열아홉이었습니다. 성 밖 산기슭에서 숯을 구워 성안에 팔던 집의 아들이었습니다. 관리가 다녀간 날 저녁, 새터의 아버지가 말했습니다."},{"t":"p","dlg":true,"html":"“적히는 게 무어 나쁘냐. 이름이 있어야 사람이지.”"},{"t":"p","dlg":false,"html":"그 종이가 무엇이었는지는 이듬해 봄이 되어서야 알게 되었습니다."},{"t":"p","dlg":false,"html":"강으로 배가 들어왔습니다. 뭍으로는 수레가 왔고요. 널판에 적힌 집부터 차례로 짐을 싸라고 했습니다. 어디로 가느냐고 묻자 관리는 서쪽이라고만 했습니다."},{"t":"p","dlg":false,"html":"그해에 이 땅을 떠나 서쪽으로 옮겨진 집이 삼만 팔천삼백 호였습니다. 한 집안이 한 호이니, 사람으로 세면 몇십만이었지요."},{"t":"p","dlg":false,"html":"검빛의 아버지와 누나는 그 명단에 있었습니다. 새터의 집은 없었습니다."},{"t":"p","dlg":false,"html":"떠나는 날 아침, 검빛의 아버지가 아들의 등을 새터 쪽으로 밀었습니다."},{"t":"p","dlg":true,"html":"“너는 이 사람을 따라가라. 남쪽으로 가라.”"},{"t":"p","dlg":false,"html":"검빛은 발을 떼지 않았습니다."},{"t":"p","dlg":true,"html":"“여기 있겠습니다. 돌아오시면 아무도 없으면 안 되니까요.”"},{"t":"p","dlg":false,"html":"배가 강을 내려가는 것을 둘이 나란히 서서 보았습니다. 새터가 먼저 입을 열었습니다."},{"t":"p","dlg":true,"html":"“돌아오실 거야.”"},{"t":"p","dlg":true,"html":"“압니다.”"},{"t":"p","dlg":false,"html":"둘 다 그 말을 믿지 않았습니다."},{"t":"p","dlg":false,"html":"사흘 뒤 새터는 남쪽으로 걸었습니다. 숯을 살 사람이 성안에 남지 않았고, 산에는 아버지 혼자로 넉넉했으니까요. 그해 이 땅의 길에는 <em class=\"dot\">유민</em>이 많았고, 새터도 그 가운데 하나였습니다."},{"t":"spot","n":2,"size":"normal","cut":true,"width":640,"height":800,"cap":"숯을 살 사람이 성 안에 남지 않자, 열아홉 새터도 살 곳을 찾아 남쪽으로 걸었다","src":"img/web/ep050-spot-2.png?v=20235241c8"}]},{"heading":"흰 말의 피","blocks":[{"t":"p","dlg":false,"html":"강을 하나 건널 때마다 말씨가 조금씩 달라졌습니다. 새터는 강을 셋 건넜고 <em class=\"hint\">재</em>를 여럿 넘었습니다. 그러는 사이 여름이 가고 가을이 깊었습니다."},{"t":"p","dlg":false,"html":"가장 넓은 강을 건널 때 새터가 뱃사공에게 물었습니다."},{"t":"p","dlg":true,"html":"“이 강은 어느 나라 강입니까.”"},{"t":"p","dlg":true,"html":"“신라 강이오. 백스무 해쯤 됐지.”"},{"t":"p","dlg":false,"html":"그 앞에는 고구려 강이었고, 그보다 앞에는 백제 강이었습니다. 물은 그대로인데 <em class=\"hint\">임자</em>가 셋이나 지나간 것이지요."},{"t":"p","dlg":false,"html":"마침내 넓은 벌판이 나왔습니다. 새터가 밭에서 일하는 사람들에게 여기가 신라 땅이냐고 물었습니다. 사람들은 대답을 망설였습니다."},{"t":"p","dlg":true,"html":"“신라 땅이기도 하고, 아니기도 하오.”"},{"t":"p","dlg":false,"html":"신라가 이긴 땅인데, 그 땅을 다스리는 관청은 따로 있다는 말이었습니다."},{"t":"p","dlg":false,"html":"백제가 무너진 지 아홉 해가 지났는데, 옛 백제의 도읍 가까이에는 아직 당의 관청이 있었습니다. 웅진도독부라고 했습니다."},{"t":"p","dlg":false,"html":"거기서 새터는 물살을 만났습니다. 스물여섯 난 사내였습니다. 백강에서 배 사백 척이 불타던 날 살아남은 사람이었지요. 그 뒤로 한자리에 오래 머무는 법이 없었습니다."},{"t":"p","dlg":false,"html":"두 사람은 나루에서 짐을 져 나르며 겨울을 났습니다."},{"t":"spot","n":3,"size":"normal","cap":"새터와 물살은 나루에서 짐을 져 나르는 일을 하며, 함께 겨울을 났다","src":"img/web/ep050-spot-3.jpg?v=57013556db"},{"t":"p","dlg":false,"html":"어느 저녁 새터가 물었습니다."},{"t":"p","dlg":true,"html":"“이긴 나라는 어디 있습니까.”"},{"t":"p","dlg":false,"html":"물살이 강 건너 낮은 산을 가리켰습니다."},{"t":"p","dlg":true,"html":"“저 산에 왔었소. 다섯 해 전에.”"},{"t":"p","dlg":false,"html":"다섯 해 전 여름이었습니다. 그 산에 사람들이 모였고, 흰 말 한 마리가 끌려 올라갔습니다. 그 말을 잡아 피를 나누어 마시며 굳게 약속하는 <em class=\"dot\">회맹</em>을 하려는 것이었습니다."},{"t":"p","dlg":false,"html":"산 위에 두 사람이 나란히 섰습니다. 한 사람은 신라의 임금 문무왕이었습니다. 다른 한 사람은 무너진 백제의 마지막 임금의 맏아들이었지요. 당은 그를 데려다 옛 제 나라 땅을 다스리는 자리에 앉혀 두고 있었습니다."},{"t":"illust","n":2,"cap":"이긴 나라의 임금과 무너진 나라의 맏아들이 한자리에 나란히 섰습니다","src":"img/web/ep050-plate-2.jpg?v=ff3e0ad70b"},{"t":"p","dlg":false,"html":"두 사람 사이에 선 것은 당의 장수였습니다. 맹세하는 글도 당이 지었습니다. 앞으로 서로 싸우지 말고 사이좋게 지내라는 내용이었지요. 그 글은 쇠판에 새겨 신라의 <em class=\"hint\">사당</em>에 두었습니다."},{"t":"p","dlg":false,"html":"물살은 그날 산 아래에 있었습니다. 제사에 쓸 것을 져 나르는 사람으로요."},{"t":"p","dlg":true,"html":"“이긴 사람과 진 사람이 나란히 서서, 남이 지어 준 글에 대고 맹세했소. 당은 진 나라의 왕자를 세워 놓고 이긴 임금더러 그와 싸우지 말라고 한 거요. 신라가 백제 땅을 제 것으로 가져가지 못하게 하려는 게지.”"},{"t":"p","dlg":false,"html":"새터가 말했습니다."},{"t":"p","dlg":true,"html":"“그래도 이긴 나라의 임금 아닙니까.”"},{"t":"p","dlg":false,"html":"물살이 고개를 저었습니다."},{"t":"p","dlg":true,"html":"“그 임금에게도 벼슬이 하나 있소.”"},{"t":"p","dlg":false,"html":"백제가 무너지고 세 해째 되던 해에 당은 신라 땅에도 이름을 하나 붙였습니다. 계림대도독부라고 했지요. 관청 건물이 실제로 선 것은 아니었습니다. 다만 그 이름은 신라도 당이 다스리는 여러 고을 가운데 하나라는 뜻이었고, 신라의 임금에게는 계림주대도독이라는 벼슬이 함께 내려왔습니다."},{"t":"p","dlg":false,"html":"이긴 나라의 임금이 남의 나라 벼슬을 받아 두고 있었던 것입니다."},{"t":"p","dlg":false,"html":"옛 백제 땅에는 웅진도독부가 있었습니다. 옛 고구려 땅에는 안동도호부가 있었습니다. 그리고 신라에는 그 이름이 붙어 있었습니다. 세 나라를 다 이긴 자리에 남은 것이 그것이었습니다."}]},{"heading":"되세우려던 사람들","blocks":[{"t":"p","dlg":false,"html":"봄에 북쪽에서 소식이 내려왔습니다."},{"t":"p","dlg":false,"html":"수임성 사람 검모잠이라는 이가 흩어진 사람들을 모아 고구려의 <em class=\"dot\">부흥</em>을 꾀하고 있다는 것이었습니다."},{"t":"p","dlg":false,"html":"그는 사람들을 이끌고 대동강 남쪽까지 내려오면서 당이 보낸 관리들을 죽였습니다. 그리고 서해의 작은 섬에서 한 사람을 찾아냈습니다. 안승이었습니다. 고구려 왕실의 피를 이은 사람이었지요. 나라를 되세우려면 모두가 받들 임금이 있어야 했습니다."},{"t":"p","dlg":false,"html":"검모잠은 안승을 한성으로 데려가 임금으로 받들었습니다. 옛 백제의 도읍이던 한성과는 이름만 같은, 대동강 남쪽의 다른 성이었습니다. 나라가 없어진 지 두 해 만에 고구려에 다시 임금이 생긴 것이지요."},{"t":"p","dlg":false,"html":"그러고는 신라로 사람을 보냈습니다. 신라의 도읍은 금성이었습니다. 그 사람이 금성의 궁궐 마당에 엎드려 이렇게 말했습니다."},{"t":"p","dlg":true,"html":"“망한 나라를 일으켜 주고 끊어진 대를 이어 주는 것은 <em class=\"hint\">천하</em>의 옳은 일입니다. 저희를 거두어 주시면 울타리가 되어 길이 충성을 다하겠습니다.”"},{"t":"p","dlg":false,"html":"새터는 나루에서 그 소식을 들었습니다. 짐을 진 채로 그대로 주저앉았습니다."},{"t":"p","dlg":true,"html":"“돌아갈 수 있겠습니다. 평양으로요.”"},{"t":"p","dlg":false,"html":"물살은 아무 말도 하지 않았습니다. 여러 해 전 백제 사람들이 바다 건너 왕자를 모셔 왔을 때도, 다들 이제 다 되었다고 여겼던 것입니다."},{"t":"p","dlg":false,"html":"그런데 그해가 다 가기 전에 소식이 또 내려왔습니다."},{"t":"p","dlg":false,"html":"검모잠이 죽었습니다."},{"t":"p","dlg":false,"html":"죽인 사람은 당의 군사가 아니었습니다. 안승이 검모잠을 죽이고 사람들을 이끌어 신라로 넘어온 것입니다."},{"t":"p","dlg":false,"html":"왜 그랬는지는 어느 책에도 적혀 있지 않습니다."},{"t":"p","dlg":false,"html":"새터가 물살에게 물었습니다."},{"t":"p","dlg":true,"html":"“어떻게 이런 일이 있습니까.”"},{"t":"p","dlg":false,"html":"물살은 한참 뒤에 대답했습니다."},{"t":"p","dlg":true,"html":"“일곱 해 전에도 그랬소.”"},{"t":"p","dlg":false,"html":"백제를 되세우겠다고 모였던 사람들도 저희끼리 갈라섰다는 말이었습니다. 물살은 그 이야기를 더 하지 않았습니다."},{"t":"p","dlg":false,"html":"금성의 <em class=\"dot\">조정</em>에서는 말이 갈렸습니다."},{"t":"p","dlg":true,"html":"“어제까지 우리 성을 빼앗던 나라입니다. 그 나라 임금 자리를 우리가 만들어 준다는 말씀입니까.”"},{"t":"p","dlg":false,"html":"당의 군대는 아직 이 땅에 있었고, 고구려 사람들은 아직 무기를 들고 있었습니다."},{"t":"p","dlg":false,"html":"문무왕이 대답했습니다."},{"t":"p","dlg":true,"html":"“우리가 그 자리를 만들지 않으면 당이 만들 것이다.”"},{"t":"p","dlg":false,"html":"그러고는 한마디를 더했습니다."},{"t":"p","dlg":true,"html":"“갈 곳 없는 사람이 사천 호다.”"},{"t":"p","dlg":false,"html":"그해 팔월, 신라는 안승을 고구려왕으로 <em class=\"dot\">책봉</em>했습니다. 그리고 나라의 서쪽 <em class=\"dot\">금마저</em> 땅을 내주어 거기 살게 했지요."},{"t":"p","dlg":false,"html":"어제의 <em class=\"hint\">적국</em> 사람에게 땅을 주고 임금이라는 이름까지 붙여 준 것입니다."},{"t":"p","dlg":false,"html":"이 땅에서 그런 일이 처음은 아니었습니다. 아주 오래전, 서쪽에서 무리를 이끌고 강을 건너온 사람에게 고조선의 임금이 나라의 변두리 땅을 맡긴 일이 있었지요. 그때는 그 뒤가 좋지 않았습니다. 그렇다고 문을 닫는 것이 답이었느냐 하면, 그것도 아무도 대답하지 못했습니다."},{"t":"p","dlg":false,"html":"가을에 새터는 금마저로 갔습니다. 물살은 가지 않았습니다."},{"t":"p","dlg":true,"html":"“같이 갑시다.”"},{"t":"p","dlg":true,"html":"“거기는 그쪽 나라요.”"},{"t":"p","dlg":true,"html":"“백제 사람도 갈 데가 있어야지요.”"},{"t":"p","dlg":true,"html":"“없소.”"},{"t":"p","dlg":false,"html":"고구려 사람들에게는 받아 줄 임금과 땅이 생겼지만, 백제 사람들에게는 그런 자리가 없다는 말이었습니다. 물살은 나루에 남았습니다."},{"t":"p","dlg":false,"html":"금마저에는 벌써 집이 서고 있었습니다. 들판에 북쪽 말씨가 가득했습니다. 새터는 밭 한 자락을 얻었고, 겨울이 오기 전에 지붕을 얹었습니다."},{"t":"illust","n":3,"cap":"고구려에서 온 사람들이 남쪽 낯선 들에 집을 짓기 시작했습니다","src":"img/web/ep050-plate-3.jpg?v=9508287856"},{"t":"p","dlg":false,"html":"일하다가 낯선 말씨가 들리면 새터는 하던 것을 멈추고 물었습니다."},{"t":"p","dlg":true,"html":"“평양에서 오셨습니까.”"},{"t":"p","dlg":false,"html":"평양에서 온 사람은 없었습니다. 그 성의 사람들은 서쪽으로 실려 갔거나 그 자리에 남았고, 걸어서 남쪽까지 내려온 이들은 대개 그보다 아래 고을 사람이었습니다."},{"t":"p","dlg":false,"html":"첫눈이 내린 날, 새터는 밭머리에 서서 북쪽을 보았습니다. 거기에는 아직 걷지 않은 천막이 있을 것이고, 성문 옆 널판에는 여전히 종이가 붙어 있을 것이었습니다. 그 앞에 서 있는 아이도 있을 것이고요."},{"t":"p","dlg":false,"html":"세 나라는 하나도 남지 않았습니다. 그런데 세 나라가 하나로 합쳐진 그 자리에 남의 나라 관청이 함께 서 있었습니다. 그래서 이 무렵의 일을 두고 오늘날에도 사람들의 말이 갈립니다."}]}],"words":[{"w":"도호부","d":"당이 제 나라 바깥의 땅을 다스리려고 두던 관청. 그보다 작은 것은 도독부라고 했다"},{"w":"호","d":"집을 세는 단위. 한 집안이 한 호다"},{"w":"유민","d":"나라가 망해 살던 곳을 떠나 떠도는 백성"},{"w":"회맹","d":"여러 사람이 모여 짐승을 잡고 그 피를 나누어 마시며 굳게 약속하던 일"},{"w":"부흥","d":"무너진 것을 다시 일으켜 세우는 일"},{"w":"조정","d":"임금과 신하들이 모여 나랏일을 의논하고 정하던 자리. 그 사람들을 함께 이르기도 한다"},{"w":"책봉","d":"임금이 신하나 이웃 나라의 우두머리에게 벼슬이나 자리를 내려 주는 일"},{"w":"금마저","d":"오늘날 전라북도 익산 땅. 신라가 안승과 그를 따라온 사람들에게 내주었다"}],"hints":[{"w":"널판","d":"넓고 판판하게 켠 나무판"},{"w":"재","d":"높은 산의 고개"},{"w":"임자","d":"물건이나 땅의 주인"},{"w":"사당","d":"조상이나 신을 모시고 제사 지내는 집"},{"w":"천하","d":"하늘 아래 온 세상"},{"w":"적국","d":"싸우는 상대 나라"}],"after":{"title":"고구려왕이라는 이름의 끝","html":["신라는 네 해 뒤 안승을 보덕왕이라 고쳐 불렀고, 그다음에는 임금의 누이를 그에게 시집보냈습니다. 안승이 신라에 온 지 열세 해가 지나자 그를 신라의 서울로 불러들여 벼슬과 김씨 성을 주었지요. 임금 자리는 그렇게 조용히 없어졌습니다. 금마저에 남은 사람들이 이듬해 들고일어났다가 흩어지면서 고구려왕이라는 이름도 끝났습니다. 한편 서쪽으로 옮겨진 사람들은 낯선 땅에서 삼십 년을 살았습니다. 그 사람들 가운데 한 집안의 아들이 뒷날 무리를 이끌고 동쪽으로 걸어가 새 나라를 세우게 됩니다."]},"ifme":{"q":"어제까지 싸우던 나라의 사람들을 받아들인다면, 나는 그들에게 무엇을 주고 무엇을 함께 정해 두겠어요?","html":["신라는 안승에게 땅을 주고 「고구려왕」이라는 이름을 주었습니다. 그 사람들은 신라 땅에 살면서도 신라 사람이 되지 않아도 되었지요. 그런데 열몇 해 뒤 그 이름이 없어지자 금마저 사람들이 들고일어났습니다. 주기만 해서는 모자랐던 모양이에요. 아주 오래전 고조선의 임금도 강을 건너온 무리에게 나라의 변두리 땅을 맡긴 일이 있었는데, 그때 두 쪽이 무엇을 함께 정해 두었는지는 기록이 말해 주지 않습니다. 여러분이라면 무엇을 주고, 무엇을 함께 정해 두겠어요? 그렇게 고른 까닭까지 말해 보세요. 정답은 없습니다."]},"truth":{"title":"이 이야기의 정체","verdict":"기록","html":["오늘 이야기의 도장은 <b>기록</b>입니다. 검모잠과 안승, 그리고 신라의 임금 문무왕은 모두 실제로 있었던 사람이에요. 당이 평양에 안동도호부를 두고 옛 백제 땅에 웅진도독부를 둔 일, 신라를 계림대도독부라 부르고 그 임금에게 계림주대도독이라는 벼슬을 내린 일, 665년에 두 사람이 흰 말을 잡고 맹세한 일은 모두 『삼국사기』와 중국 책에 적혀 있어요. 670년에 검모잠이 사람들을 모아 안승을 임금으로 세운 일, 그 안승이 검모잠을 죽이고 신라로 간 일, 신라가 안승을 고구려왕으로 삼아 금마저에 살게 한 일도 그대로 적혀 있고요. 다만 안승이 왜 검모잠을 죽였는지는 어느 책에도 한 줄이 없습니다. 안승이 누구의 아들인지조차 책마다 다르게 적혀 있고요. 다만 문무왕이 조정에서 한 두 마디는 지어낸 것이에요. 학자들이 짐작하는 신라의 셈을 임금의 말로 옮긴 것이지요. 새터도 검빛도 물살도 지어낸 사람입니다."]},"quiz":[{"n":1,"kind":"사실 확인","q":"당이 옛 고구려 땅을 다스리려고 평양에 세운 관청은 무엇인가요?","opts":["신라가 안승에게 내준 땅인 금마저","옛 고구려 땅 평양에 두었던 안동도호부","옛 백제 땅에 두었던 웅진도독부","신라 땅에 붙인 이름인 계림대도독부"],"answer":1,"why":{"0":"금마저는 관청이 아니라 신라가 안승과 그 사람들에게 내준 땅입니다.","2":"웅진도독부는 옛 백제의 도읍 가까이에 있던 관청입니다.","3":"계림대도독부는 신라에 붙은 이름이고, 관청 건물이 실제로 선 것도 아니었습니다."},"ref":"당은 옛 고구려 땅을 다스리려고 평양에 안동도호부라는 관청을 세웠습니다.","more":"『삼국사기』와 중국 책은 당이 고구려의 성 <b>백일흔여섯 곳</b>을 <b>아홉 도독부와 마흔두 주와 백 현</b>으로 다시 나누고 평양에 안동도호부를 두었다고 적습니다. 첫 도호가 된 사람은 당의 이름난 장수 <b>설인귀</b>였어요. 그런데 이 관청은 오래 평양에 있지 못합니다. 여섯 해 뒤 요동으로 옮겨 가는데, 왜 옮겨야 했는지는 3장에서 만나게 됩니다."},{"n":2,"kind":"사실 확인","q":"검모잠이 임금으로 받든 안승은 그 뒤 무슨 일을 했나요?","opts":["당에 항복하고 평양의 관청에서 벼슬을 받았다","검모잠과 함께 평양성을 되찾고 고구려를 다시 세웠다","임금 자리를 내놓고 서해의 섬으로 돌아갔다","그를 죽이고 사람들을 이끌어 신라로 넘어갔다"],"answer":3,"why":{"0":"안승이 간 곳은 평양의 관청이 아니라 신라였습니다.","1":"평양성은 되찾지 못했고, 그 성에는 당의 관청이 그대로 있었습니다.","2":"서해의 섬은 검모잠이 안승을 찾아낸 곳이지 그가 돌아간 곳이 아닙니다."},"ref":"안승이 검모잠을 죽이고 사람들을 이끌어 신라로 넘어온 것입니다.","more":"안승이 누구인지부터 기록이 어긋납니다. 『삼국사기』 신라본기는 <b>고구려의 대신 연정토의 아들</b>이라 하고, 같은 책 고구려본기는 <b>보장왕의 서자</b>라고 적어요. 중국의 옛 책들과 『삼국유사』는 또 <b>보장왕의 외손</b>이라고 하고요. 검모잠을 죽인 까닭은 어느 책에도 한 글자가 없어서, 학자들은 되세운 고구려를 어떻게 이끌지를 두고 두 사람의 생각이 갈렸으리라고 짐작할 뿐입니다. 죽인 때가 언제인지도 670년으로 보는 쪽과 몇 해 뒤로 보는 쪽이 갈린답니다."},{"n":3,"kind":"추론","q":"신라는 왜 어제까지 싸우던 나라의 사람들을 받아들여 안승에게 「고구려왕」이라는 이름까지 주었을까요?","opts":["이 땅에 아직 남아 있는 당과 맞서려면 고구려 사람들이 필요했기 때문에","당이 안승을 고구려왕으로 삼으라고 시켰기 때문에","옛 고구려 땅을 모두 안승에게 돌려주기로 약속했기 때문에","안승이 신라 왕실과 가까운 핏줄이어서 남처럼 여기지 않았기 때문에"],"answer":0,"why":{"1":"안승은 당이 보낸 관리들을 죽인 무리와 함께 온 사람이라, 당이 시켜서 될 일이 아니었습니다.","2":"신라가 내준 것은 옛 고구려 땅이 아니라 나라의 서쪽 금마저 땅이었습니다.","3":"안승은 고구려 왕실의 피를 이은 사람이지 신라 왕실과 이어진 사람이 아닙니다."},"ref":"당의 군대는 아직 이 땅에 있었고, 고구려 사람들은 아직 무기를 들고 있었습니다.","more":"검모잠이 신라로 보낸 사람이 한 말은 『삼국사기』에 그대로 실려 있어요. <b>「興滅國 繼絶世 天下之公義」</b>(망한 나라를 일으켜 주고 끊어진 대를 이어 주는 것은 천하의 옳은 일이다). 그러면서 <b>울타리(藩屛)가 되어 길이 충성을 다하겠다</b>고 했지요. 「울타리가 되겠다」는 말은 신라 앞을 대신 막아 주겠다는 뜻이기도 합니다. 청하는 쪽과 받는 쪽이 서로 다른 것을 얻은 셈이에요."},{"n":4,"kind":"낱말·표현","q":"본문에 나온 '도호부'는 무엇을 뜻하는 말인가요?","opts":["나라가 망해 살던 곳을 떠나 떠도는 백성","여러 사람이 모여 짐승을 잡고 그 피를 나누어 마시며 굳게 약속하던 일","당이 제 나라 바깥의 땅을 다스리려고 두던 관청","임금이 이웃 나라의 우두머리에게 벼슬이나 자리를 내려 주는 일"],"answer":2,"why":{"0":"그것은 유민입니다.","1":"그것은 회맹입니다.","3":"그것은 책봉입니다."},"ref":"당은 옛 고구려 땅을 다스리려고 평양에 안동도호부라는 관청을 세웠습니다.","more":"교과서는 「유민」을 <b>「망한 나라의 백성」</b>이라고 풀이합니다. 668년 뒤 이 땅에는 그런 사람이 아주 많았어요. 이듬해 당이 고구려 사람 <b>삼만 팔천삼백 호</b>를 서쪽의 빈 땅으로 옮겼다고 『삼국사기』가 적는데, 그 사람들이 흩어져 간 곳 가운데 <b>영주</b>라는 고을이 있었습니다. 그 이름은 삼십 년쯤 뒤에 다시 나옵니다."},{"n":5,"kind":"생각 넓히기","q":"학자들의 풀이를 따른다면, 668년에 세 나라의 시대가 끝난 이 일을 두고 오늘날 사람들의 말이 갈리는 까닭은 무엇일까요?","opts":["신라가 백제와 고구려를 무너뜨린 해가 책마다 다르게 적혀 있기 때문에","세 나라가 하나로 합쳐진 것과, 그 자리에 남의 나라 관청이 선 것이 함께 있기 때문에","검모잠과 안승이 실제로 있었던 사람인지 확인할 수 없기 때문에","그 무렵의 일을 적어 둔 기록이 한 줄도 남아 있지 않기 때문에"],"answer":1,"why":{"0":"백제가 660년에, 고구려가 668년에 무너진 것은 기록이 서로 다르지 않습니다.","2":"검모잠과 안승은 옛 책에 이름과 행적이 적힌 실제 인물입니다.","3":"이 무렵의 일은 『삼국사기』와 중국 책에 꽤 자세히 적혀 있습니다."},"ref":"그런데 세 나라가 하나로 합쳐진 그 자리에 남의 나라 관청이 함께 서 있었습니다.","more":"교과서는 이 일을 이렇게 적습니다. <b>「신라는 당과 동맹을 맺고 백제와 고구려를 차례로 멸망시켰다. 이후 당이 한반도 전체를 지배하려고 하자, 신라는 당과의 전쟁에서 승리해 삼국 통일을 이루었다.」</b> 학자들 사이에는 이 일을 크게 보는 쪽과 아쉽게 보는 쪽이 함께 있어요. 크게 보는 쪽은 오래 서로 싸우던 사람들이 한 나라 안에서 함께 살게 되었다는 것을 듭니다. 아쉽게 보는 쪽은 남의 나라 군대를 불러들인 일과, 옛 고구려 땅의 많은 곳이 남지 않았다는 것을 들고요. 아직 한쪽으로 정해지지 않은 이야기랍니다."}],"summary":["668년에 고구려가 무너진 뒤에도 당의 군대는 돌아가지 않았어요. 당은 옛 백제 땅에 웅진도독부를, 옛 고구려 땅 평양에 안동도호부를 두었고, 신라에도 계림대도독부라는 이름을 붙여 그 임금에게 계림주대도독이라는 벼슬을 내렸지요.","670년에 검모잠이 고구려를 되세우려고 사람들을 모아 안승을 임금으로 세웠어요. 그런데 안승이 검모잠을 죽이고 신라로 넘어갔지요. 왜 그랬는지는 어느 기록에도 없답니다.","문무왕은 안승을 받아들여 고구려왕으로 삼고 금마저 땅을 주었어요. 어제까지 싸우던 나라의 사람들을 제 나라 안에 들인 것이지요."],"bait":["세 나라가 다 사라진 땅에 신라 하나가 남았습니다. 그런데 평양성 위에 선 깃발은 아직 신라의 것이 아니었지요. 이긴 나라가 이긴 것을 갖지 못한 것입니다. 이제 신라는 <span class=\"blur\">제가 불러들인 군대와 싸워야</span> 했습니다. 그리고 서른 해 뒤, 서쪽으로 끌려간 사람들의 아들이 북쪽에 <span class=\"blur\">또 하나의 나라</span>를 세웁니다. 남쪽에 하나, 북쪽에 하나. 두 나라의 이야기가 이제 시작됩니다……"]};
